    const guestUserId = occupant.booking?.guest_user_id;
    if (!guestUserId) throw new NotFoundException('Booking guest not found');
    return this.staysService.getOccupantIdDocumentPath(
      guestUserId,
      assetId,
      side,
    );
  }

