  async freezeHost(
    hostProfileId: string,
    adminUserId: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const profile = await this.hostProfileRepo.findOne({
      where: { id: hostProfileId },
    });
    if (!profile) throw new NotFoundException('Host profile not found');
    if (profile.host_verification_status !== 'APPROVED') {
      throw new BadRequestException('Only approved hosts can be frozen');
    }
    profile.listing_frozen = true;
    await this.hostProfileRepo.save(profile);
    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: adminUserId,
        actor_role: 'ADMIN',
        entity_type: 'HOST_PROFILE',
        entity_id: hostProfileId,
        action: 'HOST_LISTING_FROZEN',
        metadata: {},
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );
    return {
      listing_frozen: true,
      message: 'Host listing access frozen. They can still book.',
    };
  }

  async unfreezeHost(
    hostProfileId: string,
    adminUserId: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const profile = await this.hostProfileRepo.findOne({
      where: { id: hostProfileId },
    });
    if (!profile) throw new NotFoundException('Host profile not found');
    profile.listing_frozen = false;
    await this.hostProfileRepo.save(profile);
    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: adminUserId,
        actor_role: 'ADMIN',
        entity_type: 'HOST_PROFILE',
        entity_id: hostProfileId,
        action: 'HOST_LISTING_UNFROZEN',
        metadata: {},
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );
    return { listing_frozen: false, message: 'Host can list again.' };
  }

  async approveListing(
    listingId: string,
    adminUserId: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const listing = await this.listingRepo.findOne({
      where: { id: listingId },
    });
    if (!listing) throw new NotFoundException('Listing not found');
    if (listing.status !== 'SUBMITTED') {
      throw new BadRequestException('Only SUBMITTED listings can be approved');
    }
    listing.status = 'APPROVED';
    await this.listingRepo.save(listing);
    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: adminUserId,
        actor_role: 'ADMIN',
        entity_type: 'LISTING',
        entity_id: listingId,
        action: 'LISTING_APPROVED',
        metadata: {},
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );
    return { status: 'APPROVED', message: 'Listing approved' };
  }

  async rejectListing(
    listingId: string,
    reason: string,
    adminUserId: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const listing = await this.listingRepo.findOne({
      where: { id: listingId },
    });
    if (!listing) throw new NotFoundException('Listing not found');
    if (listing.status !== 'SUBMITTED') {
      throw new BadRequestException('Only SUBMITTED listings can be rejected');
    }
    listing.status = 'REJECTED';
    await this.listingRepo.save(listing);
    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: adminUserId,
        actor_role: 'ADMIN',
        entity_type: 'LISTING',
        entity_id: listingId,
        action: 'LISTING_REJECTED',
        metadata: { reason },
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );
    return { status: 'REJECTED', message: 'Listing rejected' };
  }

  async setListingLive(
    listingId: string,
    adminUserId: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const listing = await this.listingRepo.findOne({
      where: { id: listingId },
    });
    if (!listing) throw new NotFoundException('Listing not found');
    if (listing.status !== 'APPROVED') {
      throw new BadRequestException('Only APPROVED listings can be set LIVE');
    }
    listing.status = 'LIVE';
    await this.listingRepo.save(listing);
    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: adminUserId,
        actor_role: 'ADMIN',
        entity_type: 'LISTING',
        entity_id: listingId,
        action: 'LISTING_SET_LIVE',
        metadata: {},
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );
    void this.domainEvents.publish(EVENTS.LISTING_PUBLISHED, 'stays', {
      listingId,
      hostUserId: listing.host_user_id,
    });
    void this.seoFreshness.refreshForSearchCity(listing.city);
    return { status: 'LIVE', message: 'Listing is now live' };
  }

  /**
   * Admin "Freeze" / "Take Offline": LIVE | APPROVED -> PAUSED.
   * Mirrors the host pause transition (no ownership check) with an admin audit
   * row. PAUSED is an operational, fully recoverable state — never archive here.
   */
  async pauseListing(
    listingId: string,
    adminUserId: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const listing = await this.listingRepo.findOne({
      where: { id: listingId },
    });
    if (!listing) throw new NotFoundException('Listing not found');
    if (!ADMIN_PAUSABLE_STATUSES.includes(listing.status)) {
      throw new BadRequestException(
        'Only LIVE or APPROVED listings can be paused',
      );
    }
    const previousStatus = listing.status;
    listing.paused_from_status =
      previousStatus === 'APPROVED' ? 'APPROVED' : 'LIVE';
    listing.status = 'PAUSED';
    await this.listingRepo.save(listing);
    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: adminUserId,
        actor_role: 'ADMIN',
        entity_type: 'LISTING',
        entity_id: listingId,
        action: 'LISTING_PAUSED',
        metadata: { previous_status: previousStatus },
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );
    void this.seoFreshness.refreshForSearchCity(listing.city);
    return {
      status: 'PAUSED',
      message:
        'Listing paused and hidden from search. It can be resumed later.',
    };
  }

  /**
   * Admin "Resume": PAUSED -> previous status (LIVE or APPROVED).
   * Respects host-wide `listing_frozen`. Never promotes APPROVED to LIVE —
   * that remains setListingLive only.
   */
  async unpauseListing(
    listingId: string,
    adminUserId: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const listing = await this.listingRepo.findOne({
      where: { id: listingId },
    });
    if (!listing) throw new NotFoundException('Listing not found');
    if (listing.status !== 'PAUSED') {
      throw new BadRequestException('Only PAUSED listings can be resumed');
    }
    const hostProfile = await this.hostProfileRepo.findOne({
      where: { user_id: listing.host_user_id },
    });
    if (hostProfile?.listing_frozen) {
      throw new BadRequestException(
        'Host listing access is frozen. Unfreeze the host before resuming this listing.',
      );
    }
    const restoreTo =
      listing.paused_from_status === 'APPROVED' ? 'APPROVED' : 'LIVE';
    listing.status = restoreTo;
    listing.paused_from_status = null;
    await this.listingRepo.save(listing);
    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: adminUserId,
        actor_role: 'ADMIN',
        entity_type: 'LISTING',
        entity_id: listingId,
        action: 'LISTING_RESUMED',
        metadata: { restored_status: restoreTo },
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );
    if (restoreTo === 'LIVE') {
      void this.domainEvents.publish(EVENTS.LISTING_PUBLISHED, 'stays', {
        listingId,
        hostUserId: listing.host_user_id,
      });
    }
    void this.seoFreshness.refreshForSearchCity(listing.city);
    return {
      status: restoreTo,
      message:
        restoreTo === 'LIVE'
          ? 'Listing is live again'
          : 'Listing restored to approved (not live). Use set-live when ready.',
    };
  }

  async checkHealth(): Promise<{ status: string; db: string }> {
    try {
      await this.listingRepo.query('SELECT 1');
      return { status: 'ok', db: 'connected' };
    } catch {
      return { status: 'degraded', db: 'disconnected' };
    }
  }

  private toMoney(value: unknown): number {
    const n = Number(value);
    return Number.isFinite(n) ? n : 0;
  }

  private toIsoDate(value: Date | string | null | undefined): string | null {
    if (value == null) return null;
    if (value instanceof Date) return value.toISOString().slice(0, 10);
    return String(value).slice(0, 10);
  }

  private summarizeBookings(
    rows: Array<{ status: string; count: string; amount: string }>,
    upcoming: readonly string[],
    completed: readonly string[],
    cancelled: readonly string[],
  ) {
    let total = 0;
    let upcomingCount = 0;
    let completedCount = 0;
    let cancelledCount = 0;
    let amount = 0;
    for (const row of rows) {
      const n = Number(row.count) || 0;
      total += n;
      amount += this.toMoney(row.amount);
      if (upcoming.includes(row.status)) upcomingCount += n;
      else if (completed.includes(row.status)) completedCount += n;
      else if (cancelled.includes(row.status)) cancelledCount += n;
    }
    return {
      total,
      upcoming: upcomingCount,
      completed: completedCount,
      cancelled: cancelledCount,
      amount,
    };
  }

  private toCompactBooking(booking: StaysBooking, amount: number) {
    return {
      id: booking.id,
      reference: booking.booking_reference,
      status: booking.status,
      checkinDate: this.toIsoDate(booking.checkin_date),
      checkoutDate: this.toIsoDate(booking.checkout_date),
      listingId: booking.listing_id,
      amount,
    };
  }
}

