import type { StaysMessage } from './entities/stays-message.entity';
import type {
  AttachmentDto,
  MessagePayload,
  TimelineCardPayload,
} from './messaging.types';

export type DeliveryState =
  | 'PERSISTED'
  | 'SENT'
  | 'DELIVERED'
  | 'READ'
  | 'PENDING';

export function resolveDeliveryState(message: StaysMessage): DeliveryState {
  if (message.status === 'READ' || message.read_at) return 'READ';
  if (message.status === 'DELIVERED' || message.delivered_at)
    return 'DELIVERED';
  if (message.status === 'PERSISTED' && message.sent_at) return 'SENT';
  if (message.status === 'PERSISTED') return 'PERSISTED';
  return 'PENDING';
}

export function buildMessagePayload(
  type: string,
  body: string | null,
  metadata: Record<string, unknown>,
  attachments: AttachmentDto[] = [],
): MessagePayload {
  const meta = metadata ?? {};
  const cardTypes = new Set([
    'BOOKING_CARD',
    'PROPERTY_CARD',
    'CHECKIN_CARD',
    'WIFI_CARD',
    'LOCATION_CARD',
    'REVIEW_CARD',
    'PAYMENT_CARD',
    'SYSTEM_EVENT',
    'SYSTEM_NOTICE',
  ]);

  if (type === 'TEXT') {
    return { text: body ?? '' };
  }

  if (type === 'IMAGE' || type === 'FILE') {
    const ids =
      (meta.attachment_ids as string[] | undefined) ??
      attachments.map((a) => a.id);
    return {
      attachmentIds: ids,
      caption: (meta.caption as string | undefined) ?? body ?? undefined,
      attachments,
    };
  }

  if (cardTypes.has(type) || meta.kind) {
    return {
      kind: String(meta.kind ?? type.replace(/_CARD$/, '').toLowerCase()),
      title: String(meta.title ?? body ?? ''),
      body: meta.body as string | undefined,
      icon: meta.icon as string | undefined,
      actions: (meta.actions as TimelineCardPayload['actions']) ?? [],
      coverMediaId: meta.coverMediaId as string | null | undefined,
      listingId: meta.listingId as string | null | undefined,
      bookingId: meta.bookingId as string | null | undefined,
      snapshot: meta.snapshot as Record<string, unknown> | undefined,
    };
  }

  return { text: body ?? '' };
}

export function payloadToStorage(
  type: string,
  payload: MessagePayload,
): { body: string | null; metadata: Record<string, unknown> } {
  if ('text' in payload && type === 'TEXT') {
    return {
      body: payload.text,
      metadata: {
        source: 'USER',
        schemaVersion: 1,
        cardVersion: 1,
        presentationVersion: 1,
      },
    };
  }

  if ('attachmentIds' in payload) {
    return {
      body: payload.caption ?? null,
      metadata: {
        source: 'USER',
        schemaVersion: 1,
        cardVersion: 1,
        presentationVersion: 1,
        attachment_ids: payload.attachmentIds,
        caption: payload.caption,
      },
    };
  }

  if ('kind' in payload) {
    return {
      body: null,
      metadata: {
        source: 'SYSTEM',
        schemaVersion: 1,
        cardVersion: 1,
        presentationVersion: 1,
        kind: payload.kind,
        title: payload.title,
        body: payload.body,
        icon: payload.icon,
        actions: payload.actions ?? [],
        coverMediaId: payload.coverMediaId,
        listingId: payload.listingId,
        bookingId: payload.bookingId,
        snapshot: payload.snapshot,
      },
    };
  }

  return { body: null, metadata: {} };
}

import type { MessageType } from './entities/stays-message.entity';
import type { ConversationViewerRole } from './messaging.types';

type PreviewInput = {
  type: MessageType | string;
  body?: string | null;
  metadata?: Record<string, unknown> | null;
  senderLabel?: string | null;
  viewerRole?: ConversationViewerRole;
};

type SenderContext = {
  senderId?: string | null;
  viewerUserId: string;
  guestUserId: string | null;
  hostUserId: string | null;
  hostDisplayName?: string | null;
  guestDisplayName?: string | null;
  counterpartDisplayName?: string | null;
};

function pickText(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

function sentMediaPreview(
  mediaLabel: string,
  senderLabel?: string | null,
  fallback?: string,
): string {
  if (senderLabel) return `${senderLabel} sent a ${mediaLabel}`;
  return fallback ?? mediaLabel.charAt(0).toUpperCase() + mediaLabel.slice(1);
}

/** Resolve "You" vs counterpart/sender name for inbox preview copy. */
export function resolveInboxSenderLabel(ctx: SenderContext): string | null {
  const { senderId, viewerUserId, guestUserId, hostUserId } = ctx;
  if (!senderId) return null;
  if (senderId === viewerUserId) return 'You';

  if (senderId === hostUserId) {
    return ctx.hostDisplayName ?? ctx.counterpartDisplayName ?? 'Host';
  }
  if (senderId === guestUserId) {
    return ctx.guestDisplayName ?? ctx.counterpartDisplayName ?? 'Guest';
  }
  return ctx.counterpartDisplayName ?? null;
}

function readRoleViewTitle(
  meta: Record<string, unknown>,
  viewerRole?: ConversationViewerRole,
): string | null {
  const reviewed = meta.reviewed === true;
  const viewKey = viewerRole === 'host' ? 'hostView' : 'guestView';
  const view = meta[viewKey];
  if (view && typeof view === 'object' && view !== null) {
    const title = pickText((view as Record<string, unknown>).title);
    if (title) return title;
  }

  if (viewerRole === 'host') {
    return reviewed ? 'Guest reviewed successfully' : 'Review request sent';
  }
  if (reviewed) return 'Thanks for reviewing!';
  return pickText(meta.title) ?? 'Review your stay';
}

/** Human-readable inbox preview for the chronologically latest message. */
export function formatInboxPreview(input: PreviewInput): string {
  const meta = input.metadata ?? {};
  const body = pickText(input.body);
  const caption = pickText(meta.caption);
  const title = pickText(meta.title);
  const cardBody = pickText(meta.body);
  const senderLabel = input.senderLabel ?? null;

  switch (input.type) {
    case 'TEXT':
      return body ?? '';
    case 'IMAGE':
      if (caption) return caption;
      return sentMediaPreview('photo', senderLabel, 'Photo');
    case 'FILE':
      if (caption && caption !== 'Voice message') return caption;
      if (caption === 'Voice message') {
        return sentMediaPreview('voice message', senderLabel, 'Voice message');
      }
      return sentMediaPreview('file', senderLabel, 'File');
    case 'VIDEO':
      if (caption) return caption;
      return sentMediaPreview('video', senderLabel, 'Video');
    case 'VOICE':
      return sentMediaPreview('voice message', senderLabel, 'Voice message');
    case 'LOCATION':
      if (caption) return caption;
      return sentMediaPreview('location', senderLabel, 'Location');
    case 'SYSTEM_EVENT':
      return body ?? title ?? 'Booking update';
    case 'SYSTEM_NOTICE':
      return body ?? title ?? 'Notice';
    case 'BOOKING_CARD':
      return title ?? cardBody ?? 'Booking confirmed';
    case 'PROPERTY_CARD':
      return title ?? cardBody ?? 'Property details';
    case 'CHECKIN_CARD':
      return title ?? cardBody ?? 'Check-in details';
    case 'WIFI_CARD':
      return title ?? (cardBody ? `Wi-Fi · ${cardBody}` : 'Wi-Fi details');
    case 'LOCATION_CARD':
      return title ?? cardBody ?? 'Location';
    case 'REVIEW_CARD':
      return readRoleViewTitle(meta, input.viewerRole) ?? 'Review your stay';
    case 'PAYMENT_CARD':
      return title ?? cardBody ?? 'Payment update';
    default:
      return title ?? cardBody ?? body ?? 'Message';
  }
}

import { Injectable, Logger, NotFoundException } from '@nestjs/common';
