function parseCheckoutDateTime(
  checkoutDate: Date | string,
  checkoutTime: string,
): Date {
  const dateStr =
    checkoutDate instanceof Date
      ? checkoutDate.toISOString().slice(0, 10)
      : String(checkoutDate).slice(0, 10);
  const [hourPart, minutePart] = checkoutTime.split(':');
  const hours = Number(hourPart) || 11;
  const minutes = Number(minutePart) || 0;
  return new Date(
    `${dateStr}T${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:00`,
  );
}

@Injectable()
export class MessagingStateService {
  private readonly logger = new Logger(MessagingStateService.name);

  constructor(
    @InjectRepository(StaysConversation)
    private readonly convRepo: Repository<StaysConversation>,
    @InjectRepository(StaysBooking)
    private readonly bookingRepo: Repository<StaysBooking>,
    @InjectRepository(StaysListing)
    private readonly listingRepo: Repository<StaysListing>,
    private readonly dataSource: DataSource,
    private readonly timelineSeeder: TimelineSeederService,
    private readonly domainEvents: DomainEventsService,
  ) {}

  getPostStayGraceHours(): number {
    const raw = Number(process.env.POST_STAY_GRACE_HOURS ?? 72);
    return Number.isFinite(raw) && raw > 0 ? raw : 72;
  }

  computePostStayEndsAt(
    booking: StaysBooking,
    listing?: StaysListing | null,
  ): Date {
    const checkoutAt =
      booking.completed_at ??
      parseCheckoutDateTime(
        booking.checkout_date,
        listing?.checkout_time ?? '11:00',
      );
    const graceMs = this.getPostStayGraceHours() * 60 * 60 * 1000;
    return new Date(checkoutAt.getTime() + graceMs);
  }

  /** Sync booking status → conversation state (cancel lock, post-stay entry, overdue archive). */
  async syncFromBooking(bookingId: string): Promise<void> {
    const booking = await this.bookingRepo.findOne({
      where: { id: bookingId },
      relations: ['listing'],
    });
    const conv = await this.convRepo.findOne({
      where: { booking_id: bookingId },
    });
    if (!booking || !conv) return;

    const now = new Date();
    if (
      booking.status === 'CANCELLED_BY_GUEST' ||
      booking.status === 'CANCELLED_BY_HOST'
    ) {
      await this.convRepo.update(conv.id, {
        messaging_state: 'LOCKED',
        locked_at: conv.locked_at ?? now,
        conversation_version: conv.conversation_version + 1,
      });
      return;
    }

    if (booking.status === 'COMPLETED') {
      if (conv.messaging_state === 'ARCHIVED') return;
      if (
        conv.post_stay_ends_at &&
        conv.post_stay_ends_at <= now &&
        !conv.auto_archive_disabled
      ) {
        await this.archiveConversation(conv.id, 'AUTO');
        return;
      }
      await this.enterPostStay(bookingId);
    }
  }

  /** Checkout → post-stay: chat stays active until post_stay_ends_at. */
  async enterPostStay(bookingId: string): Promise<void> {
    const booking = await this.bookingRepo.findOne({
      where: { id: bookingId },
    });
    const conv = await this.convRepo.findOne({
      where: { booking_id: bookingId },
    });
    if (!booking || !conv || booking.status !== 'COMPLETED') return;
    if (conv.messaging_state === 'ACTIVE' && conv.post_stay_ends_at) return;

    const listing = booking.listing_id
      ? await this.listingRepo.findOne({ where: { id: booking.listing_id } })
      : null;
    const postStayEndsAt = this.computePostStayEndsAt(booking, listing);

    await this.dataSource.transaction(async (manager) => {
      const messageRepo = manager.getRepository(StaysMessage);
      const convRepo = manager.getRepository(StaysConversation);

      const hasReviewCard = await messageRepo.exists({
        where: { conversation_id: conv.id, type: 'REVIEW_CARD' },
      });
      if (!hasReviewCard) {
        await this.timelineSeeder.seedCheckoutComplete(manager, conv, booking);
      }

      await convRepo.update(conv.id, {
        messaging_state: 'ACTIVE',
        guest_visibility: 'ACTIVE',
        host_visibility: 'ACTIVE',
        post_stay_ends_at: postStayEndsAt,
        archived_at: null,
        read_only_at: null,
        archive_reason: null,
        conversation_version: conv.conversation_version + 1,
      });
    });

    this.logger.log(
      `Post-stay started for booking ${bookingId}; archive scheduled at ${postStayEndsAt.toISOString()}`,
    );
  }

  async archiveConversation(
    conversationId: string,
    reason: ArchiveReason | string = 'AUTO',
  ): Promise<void> {
    const conv = await this.convRepo.findOne({ where: { id: conversationId } });
    if (!conv || conv.messaging_state === 'ARCHIVED') return;

    const booking = conv.booking_id
      ? await this.bookingRepo.findOne({ where: { id: conv.booking_id } })
      : null;
    const listing = booking?.listing_id
      ? await this.listingRepo.findOne({ where: { id: booking.listing_id } })
      : null;

    const now = new Date();

    await this.dataSource.transaction(async (manager) => {
      const messageRepo = manager.getRepository(StaysMessage);
      const convRepo = manager.getRepository(StaysConversation);

      const hasArchiveNotice = await messageRepo.exists({
        where: { conversation_id: conv.id, type: 'SYSTEM_NOTICE' },
      });

      if (!hasArchiveNotice) {
        await this.timelineSeeder.seedConversationArchived(
          manager,
          conv,
          booking?.id ?? conv.booking_id,
        );
      }

      await convRepo.update(conv.id, {
        messaging_state: 'ARCHIVED',
        guest_visibility: 'ARCHIVED',
        host_visibility: 'ARCHIVED',
        archived_at: conv.archived_at ?? now,
        read_only_at: conv.read_only_at ?? now,
        archive_reason: reason,
        conversation_version: conv.conversation_version + 1,
      });
    });

    if (conv.booking_id && conv.guest_user_id && conv.host_user_id) {
      void this.domainEvents.publish(EVENTS.CONVERSATION_ARCHIVED, 'stays', {
        bookingId: conv.booking_id,
        listingId: conv.listing_id ?? booking?.listing_id ?? '',
        conversationId: conv.id,
        guestUserId: conv.guest_user_id,
        hostUserId: conv.host_user_id,
        listingTitle: listing?.title,
      });
    }

    this.logger.log(`Archived conversation ${conversationId} (${reason})`);
  }

  async reopenConversation(
    conversationId: string,
    options: { reason?: string; disableAutoArchive?: boolean } = {},
  ): Promise<StaysConversation> {
    const conv = await this.convRepo.findOne({ where: { id: conversationId } });
    if (!conv) throw new NotFoundException('Conversation not found');

    const booking = conv.booking_id
      ? await this.bookingRepo.findOne({ where: { id: conv.booking_id } })
      : null;
    const listing = booking?.listing_id
      ? await this.listingRepo.findOne({ where: { id: booking.listing_id } })
      : null;

    const postStayEndsAt =
      booking?.status === 'COMPLETED' && !options.disableAutoArchive
        ? this.computePostStayEndsAt(booking, listing)
        : conv.post_stay_ends_at;

    await this.convRepo.update(conv.id, {
      messaging_state: 'ACTIVE',
      guest_visibility: 'ACTIVE',
      host_visibility: 'ACTIVE',
      archived_at: null,
      read_only_at: null,
      archive_reason: null,
      post_stay_ends_at: postStayEndsAt,
      auto_archive_disabled: options.disableAutoArchive ?? false,
      auto_archive_disabled_reason: options.disableAutoArchive
        ? (options.reason ?? 'manual')
        : null,
      conversation_version: conv.conversation_version + 1,
    });

    const updated = await this.convRepo.findOne({
      where: { id: conversationId },
    });
    if (!updated) throw new NotFoundException('Conversation not found');
    return updated;
  }

  async archiveDueConversations(): Promise<number> {
    const due = await this.convRepo
      .createQueryBuilder('c')
      .where('c.type = :t', { t: 'BOOKING' })
      .andWhere("c.messaging_state = 'ACTIVE'")
      .andWhere('c.post_stay_ends_at IS NOT NULL')
      .andWhere('c.post_stay_ends_at <= NOW()')
      .andWhere('c.auto_archive_disabled = FALSE')
      .getMany();

    for (const conv of due) {
      try {
        await this.archiveConversation(conv.id, 'AUTO');
      } catch (err) {
        this.logger.warn(
          `Failed to auto-archive ${conv.id}: ${err instanceof Error ? err.message : String(err)}`,
        );
      }
    }
    return due.length;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { Cron, CronExpression } from '@nestjs/schedule';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { StaysMessagingOutbox } from './entities/stays-messaging-outbox.entity';
import { DomainEventsService } from '../../common/events/domain-events.service';
import {
  isMessagingInternalEvent,
  MESSAGING_INTERNAL_EVENTS,
} from './messaging-internal.events';
import { SnapshotRepairService } from './snapshot-repair.service';
import { EVENTS, EventValidationError } from '@nexa/event-bus';

const MAX_OUTBOX_ATTEMPTS = 5;

function resolveProviderIntentId(
  bookingId: string,
  providerIntentId?: string | null,
  paymentIntentId?: string | null,
): string {
  const candidate = (providerIntentId ?? paymentIntentId ?? '').trim();
  return candidate || `booking-${bookingId}`;
}

@Injectable()
export class MessagingOutboxWorker {
  private readonly logger = new Logger(MessagingOutboxWorker.name);
  private processing = false;

  constructor(
    @InjectRepository(StaysMessagingOutbox)
    private readonly outboxRepo: Repository<StaysMessagingOutbox>,
    private readonly domainEvents: DomainEventsService,
    private readonly snapshotRepair: SnapshotRepairService,
  ) {}

  @Cron(CronExpression.EVERY_5_SECONDS)
  async processOutbox(): Promise<void> {
    if (this.processing) return;
    this.processing = true;
    try {
      await this.recoverStaleProcessingRows();
      const rows = await this.claimPendingRows(20);
      for (const row of rows) {
        if (!row?.id || !row.event_type) {
          this.logger.warn('Skipping outbox row with missing id or event_type');
          continue;
        }
        try {
          const payload = this.normalizePayload(row.event_type, row.payload);
          if (isMessagingInternalEvent(row.event_type)) {
            await this.handleInternalEvent(row.event_type, payload);
          } else {
            await this.domainEvents.publish(row.event_type, 'stays', payload);
          }
          await this.outboxRepo.update(row.id, {
            status: 'DONE',
            processed_at: new Date(),
          });
        } catch (err) {
          const attempts = (row.attempts ?? 0) + 1;
          const isValidationError = err instanceof EventValidationError;
          const isPermanentFailure =
            isValidationError || attempts >= MAX_OUTBOX_ATTEMPTS;
          const delayMs = Math.min(60_000, 1000 * 2 ** attempts);
          this.logger.warn(
            `Outbox ${row.id} failed attempt ${attempts}: ${err}`,
          );
          await this.outboxRepo.update(row.id, {
            status: isPermanentFailure ? 'FAILED' : 'PENDING',
            attempts,
            next_retry_at: isPermanentFailure
              ? row.next_retry_at
              : new Date(Date.now() + delayMs),
          });
        }
      }
    } finally {
      this.processing = false;
    }
  }

  private async handleInternalEvent(
    eventType: string,
    payload: Record<string, unknown>,
  ): Promise<void> {
    if (eventType === MESSAGING_INTERNAL_EVENTS.SNAPSHOT_REPAIR_REQUESTED) {
      const conversationId = payload.conversationId;
      if (typeof conversationId !== 'string' || !conversationId) {
        throw new Error('snapshot repair missing conversationId');
      }
      await this.snapshotRepair.repairConversation(conversationId);
      return;
    }
    throw new Error(`Unknown internal messaging event: ${eventType}`);
  }

  /** Atomically claim rows with SKIP LOCKED for multi-instance safety. */
  async claimPendingRows(limit: number): Promise<StaysMessagingOutbox[]> {
    const raw = await this.outboxRepo.manager.query(
      `UPDATE stays_messaging_outbox
       SET status = 'PROCESSING'
       WHERE id IN (
         SELECT id FROM stays_messaging_outbox
         WHERE status = 'PENDING'
           AND next_retry_at <= NOW()
         ORDER BY created_at ASC
         LIMIT $1
         FOR UPDATE SKIP LOCKED
       )
       RETURNING *`,
      [limit],
    );
    return this.unwrapQueryRows(raw);
  }

  /** TypeORM 0.3 pg driver returns [rows, rowCount] for UPDATE…RETURNING. */
  private unwrapQueryRows(raw: unknown): StaysMessagingOutbox[] {
    if (Array.isArray(raw) && raw.length === 2 && Array.isArray(raw[0])) {
      return raw[0] as StaysMessagingOutbox[];
    }
    if (Array.isArray(raw)) {
      return raw as StaysMessagingOutbox[];
    }
    return [];
  }

  /** Repair legacy rows enqueued before providerIntentId validation was enforced. */
  private normalizePayload(
    eventType: string,
    payload: Record<string, unknown>,
  ): Record<string, unknown> {
    if (
      eventType === EVENTS.PAYMENT_SUCCEEDED &&
      typeof payload.bookingId === 'string' &&
      payload.bookingId
    ) {
      const providerIntentId =
        typeof payload.providerIntentId === 'string'
          ? payload.providerIntentId
          : undefined;
      return {
        ...payload,
        providerIntentId: resolveProviderIntentId(
          payload.bookingId,
          providerIntentId,
          typeof payload.paymentIntentId === 'string'
            ? payload.paymentIntentId
            : undefined,
        ),
      };
    }
    return payload;
  }

  /** Re-queue rows left in PROCESSING after a crash or failed retry update. */
  private async recoverStaleProcessingRows(): Promise<void> {
    await this.outboxRepo.manager.query(
      `UPDATE stays_messaging_outbox
       SET status = 'PENDING', next_retry_at = NOW()
       WHERE status = 'PROCESSING'
         AND processed_at IS NULL
         AND created_at < NOW() - INTERVAL '1 minute'`,
    );
  }
}

import { Injectable, HttpException, HttpStatus } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { StaysMessage } from './entities/stays-message.entity';

interface RateBucket {
  timestamps: number[];
  bodies: Map<string, number[]>;
}

@Injectable()
export class MessagingRateLimitService {
  private readonly buckets = new Map<string, RateBucket>();
  private readonly perMinute = 10;
  private readonly perDay = 500;
  private readonly identicalPerMinute = 5;

  constructor(
    @InjectRepository(StaysMessage)
    private readonly messageRepo: Repository<StaysMessage>,
  ) {}

  async assertCanSend(
    userId: string,
    conversationId: string,
    body: string,
  ): Promise<void> {
    const key = `${userId}:${conversationId}`;
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { timestamps: [], bodies: new Map() };
      this.buckets.set(key, bucket);
    }

    bucket.timestamps = bucket.timestamps.filter((t) => now - t < 86_400_000);
    const lastMinute = bucket.timestamps.filter((t) => now - t < 60_000);
    if (lastMinute.length >= this.perMinute) {
      throw new HttpException(
        'Rate limit exceeded',
        HttpStatus.TOO_MANY_REQUESTS,
      );
    }
    if (bucket.timestamps.length >= this.perDay) {
      throw new HttpException(
        'Daily message limit exceeded',
        HttpStatus.TOO_MANY_REQUESTS,
      );
    }

    const normalized = body.trim().toLowerCase();
    const bodyTimes = bucket.bodies.get(normalized) ?? [];
    const recentBodies = bodyTimes.filter((t) => now - t < 60_000);
    if (recentBodies.length >= this.identicalPerMinute) {
      throw new HttpException(
        'Duplicate message limit exceeded',
        HttpStatus.TOO_MANY_REQUESTS,
      );
    }
    recentBodies.push(now);
    bucket.bodies.set(normalized, recentBodies);
    bucket.timestamps.push(now);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { Cron, CronExpression } from '@nestjs/schedule';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { SeoDestination } from './entities/seo-destination.entity';
import { SeoPageRegistry } from './entities/seo-page-registry.entity';
import { DestinationIntelligenceService } from './destination-intelligence.service';
import { SeoPageRegistryService } from './seo-page-registry.service';
import {
  SEO_AMENITIES,
  SEO_LANDMARKS,
  SEO_NEIGHBORHOODS_BY_CITY,
  SEO_PROPERTY_TYPES,
  amenityToExploreFilters,
  landmarkToExploreFilters,
  neighborhoodToExploreFilters,
} from './seo-catalog';
import {
  computeSeoQualityScore,
  isPageIndexable,
} from './seo-quality-scoring.service';

@Injectable()
export class SeoFreshnessEngineService {
  private readonly logger = new Logger(SeoFreshnessEngineService.name);

  constructor(
    @InjectRepository(SeoDestination)
    private readonly destinationRepo: Repository<SeoDestination>,
    @InjectRepository(SeoPageRegistry)
    private readonly registryRepo: Repository<SeoPageRegistry>,
    private readonly intelligence: DestinationIntelligenceService,
    private readonly registry: SeoPageRegistryService,
  ) {}

  @Cron(CronExpression.EVERY_DAY_AT_3AM)
  async refreshAllDestinations(): Promise<void> {
    await this.runRefresh();
  }

  @Cron(CronExpression.EVERY_HOUR)
  async refreshHourlyLight(): Promise<void> {
    if (process.env.SEO_FRESHNESS_HOURLY !== 'true') return;
    await this.runRefresh();
  }

  async runOnStartup(): Promise<void> {
    if (process.env.SEO_FRESHNESS_SYNC_ON_STARTUP === 'true') {
      await this.runRefresh();
    }
  }

  /** Refresh stats for a city when listings change. */
  async refreshForSearchCity(searchCity: string): Promise<void> {
    const dest = await this.destinationRepo.findOne({
      where: { search_city: searchCity, content_status: 'published' },
    });
    if (!dest) return;
    await this.refreshDestinationBundle(dest);
  }

  async runRefresh(): Promise<void> {
    const destinations = await this.destinationRepo.find({
      where: { content_status: 'published' },
    });
    const now = new Date();

    for (const dest of destinations) {
      try {
        await this.refreshDestinationBundle(dest, now);
      } catch (err) {
        this.logger.warn(
          `SEO freshness failed for ${dest.slug}: ${err instanceof Error ? err.message : err}`,
        );
      }
    }

    for (const pt of SEO_PROPERTY_TYPES) {
      try {
        const intel = await this.intelligence.compute({
          listing_type: pt.listingType,
        });
        const score = computeSeoQualityScore({ intelligence: intel });
        const indexable = isPageIndexable({
          seoScore: score,
          listingCount: intel.listingCount,
        });
        await this.registry.syncPageAllLocales({
          pageType: 'property_type',
          slug: pt.slug,
          indexable,
          seoScore: score,
          lastmod: now,
        });
      } catch (err) {
        this.logger.warn(`SEO freshness property_type ${pt.slug}: ${err}`);
      }
    }

    for (const am of SEO_AMENITIES) {
      try {
        const intel = await this.intelligence.compute(
          amenityToExploreFilters(am),
        );
        const score = computeSeoQualityScore({ intelligence: intel });
        const indexable = isPageIndexable({
          seoScore: score,
          listingCount: intel.listingCount,
        });
        await this.registry.syncPageAllLocales({
          pageType: 'amenity',
          slug: am.slug,
          indexable,
          seoScore: score,
          lastmod: now,
        });
      } catch (err) {
        this.logger.warn(`SEO freshness amenity ${am.slug}: ${err}`);
      }
    }

    for (const lm of SEO_LANDMARKS) {
      try {
        const intel = await this.intelligence.compute(
          landmarkToExploreFilters(lm),
        );
        const score = computeSeoQualityScore({ intelligence: intel });
        const indexable = isPageIndexable({
          seoScore: score,
          listingCount: intel.listingCount,
        });
        await this.registry.syncPageAllLocales({
          pageType: 'landmark',
          slug: lm.urlSlug,
          indexable,
          seoScore: score,
          lastmod: now,
        });
      } catch (err) {
        this.logger.warn(`SEO freshness landmark ${lm.urlSlug}: ${err}`);
      }
    }

    this.logger.log(
      `SEO freshness refreshed ${destinations.length} destinations + combos + landmarks`,
    );
  }

  private async refreshDestinationBundle(
    dest: SeoDestination,
    now: Date = new Date(),
  ): Promise<void> {
    const cityIntel = await this.intelligence.compute({
      city: dest.search_city,
    });
    const cityScore = computeSeoQualityScore({
      intelligence: cityIntel,
      destination: dest,
    });
    const cityIndexable = isPageIndexable({
      seoScore: cityScore,
      listingCount: cityIntel.listingCount,
    });

    await this.destinationRepo.update(dest.id, {
      stats_cache_json: JSON.parse(JSON.stringify(cityIntel)),
      stats_refreshed_at: now,
      listing_count_cache: cityIntel.listingCount,
      seo_score: cityScore,
      indexable: cityIndexable,
    });

    await this.registry.syncPageAllLocales({
      pageType: 'city',
      slug: dest.slug,
      indexable: cityIndexable,
      seoScore: cityScore,
      lastmod: now,
    });

    for (const pt of SEO_PROPERTY_TYPES) {
      const intel = await this.intelligence.compute({
        city: dest.search_city,
        listing_type: pt.listingType,
      });
      const score = computeSeoQualityScore({
        intelligence: intel,
        destination: dest,
      });
      const indexable = isPageIndexable({
        seoScore: score,
        listingCount: intel.listingCount,
      });
      await this.registry.syncPageAllLocales({
        pageType: 'city_property_type',
        slug: `${dest.slug}/${pt.slug}`,
        indexable,
        seoScore: score,
        lastmod: now,
      });
    }

    for (const am of SEO_AMENITIES) {
      const intel = await this.intelligence.compute({
        city: dest.search_city,
        ...amenityToExploreFilters(am),
      });
      const score = computeSeoQualityScore({
        intelligence: intel,
        destination: dest,
      });
      const indexable = isPageIndexable({
        seoScore: score,
        listingCount: intel.listingCount,
      });
      await this.registry.syncPageAllLocales({
        pageType: 'city_amenity',
        slug: `${dest.slug}/${am.slug}`,
        indexable,
        seoScore: score,
        lastmod: now,
      });
    }

    const neighborhoods = SEO_NEIGHBORHOODS_BY_CITY[dest.slug] ?? [];
    for (const nb of neighborhoods) {
      const intel = await this.intelligence.compute(
        neighborhoodToExploreFilters(dest.search_city, nb),
      );
      const score = computeSeoQualityScore({
        intelligence: intel,
        destination: dest,
      });
      const indexable = isPageIndexable({
        seoScore: score,
        listingCount: intel.listingCount,
      });
      await this.registry.syncPageAllLocales({
        pageType: 'city_neighborhood',
        slug: `${dest.slug}/${nb.slug}`,
        indexable,
        seoScore: score,
        lastmod: now,
      });
    }
  }
}

