const VERIFY_EXTS = ['.jpg', '.jpeg', '.png', '.webp'];

/** Admin-safe host profile: never document_number_hash or sumsub_applicant_id. */
export function toAdminHostProfileDto(profile: StaysHostProfile) {
  return {
    id: profile.id,
    user_id: profile.user_id,
    host_verification_status: profile.host_verification_status,
    application_status: profile.application_status,
    identity_status: profile.identity_status,
    source: profile.source,
    submitted_from: profile.submitted_from,
    full_name: profile.full_name,
    email: profile.email,
    phone: profile.phone,
    city: profile.city,
    host_type: profile.host_type,
    hosting_policies_accepted_at: profile.hosting_policies_accepted_at,
    identity_reused: profile.identity_reused,
    listing_frozen: profile.listing_frozen,
    document_type: profile.document_type,
    document_front_asset_id: profile.document_front_asset_id,
    document_back_asset_id: profile.document_back_asset_id,
    selfie_asset_id: profile.selfie_asset_id,
    submitted_at: profile.submitted_at,
    reviewed_at: profile.reviewed_at,
    reviewed_by: profile.reviewed_by,
    rejection_reason: profile.rejection_reason,
    created_at: profile.created_at,
    updated_at: profile.updated_at,
  };
}

export type SubmitHostOnboardingContext = {
  source: HostOnboardingSource;
  submitted_from: string;
  requirePolicies?: boolean;
};

@Injectable()
export class HostOnboardingService {
  constructor(
    @InjectRepository(StaysHostProfile)
    private readonly hostProfileRepo: Repository<StaysHostProfile>,
    @InjectRepository(StaysAuditLog)
    private readonly auditRepo: Repository<StaysAuditLog>,
    private readonly dataSource: DataSource,
    private readonly kycPolicy: StaysKycPolicyService,
    private readonly mediaStorage: MediaStorageService,
  ) {}

  private isIdentityVerified(user: StaysUserContext): boolean {
    return this.kycPolicy.meetsHostIdentityReuse(user.identitySnapshot);
  }

  async submitHostOnboarding(
    user: StaysUserContext,
    dto: SubmitHostOnboardingDto,
    context: SubmitHostOnboardingContext,
  ) {
    if (!this.isIdentityVerified(user)) {
      const hasDocuments = !!(
        dto.document_front_asset_id?.trim() && dto.selfie_asset_id?.trim()
      );
      const useExisting = dto.use_existing_kyc === true;
      if (useExisting || !hasDocuments) {
        throw new ForbiddenException(
          'Identity verification required. Complete KYC in Nexa Identity or upload ID documents.',
        );
      }
    }

    if (context.requirePolicies && dto.hosting_policies_accepted !== true) {
      throw new BadRequestException(
        'You must accept hosting policies to apply',
      );
    }

    await this.assertOwnedVerificationAssets(user.userId, dto);

    let profile = await this.hostProfileRepo.findOne({
      where: { user_id: user.userId },
    });

    if (
      profile?.application_status === 'PENDING' ||
      profile?.application_status === 'APPROVED'
    ) {
      if (profile.application_status === 'APPROVED') {
        throw new ConflictException(
          'You already have an approved host account',
        );
      }
      return this.toSubmitResponse(profile);
    }

    if (!profile) {
      profile = this.hostProfileRepo.create({
        user_id: user.userId,
        application_status: 'DRAFT',
        identity_status: 'VERIFIED',
        host_verification_status: 'PENDING',
        source: context.source,
        submitted_from: context.submitted_from,
        identity_reused: true,
      });
    }

    const phone = dto.phone ?? user.phone_number ?? null;
    if (!phone?.trim()) {
      throw new BadRequestException(
        'A verified phone number is required to submit host onboarding',
      );
    }

    profile.full_name = dto.full_name ?? profile.full_name;
    profile.email = dto.email ?? user.email ?? profile.email;
    profile.phone = normalizePhoneOrThrow(phone);
    profile.city = dto.city ?? profile.city;
    profile.host_type = dto.host_type ?? profile.host_type;
    profile.source = context.source;
    profile.submitted_from = context.submitted_from;
    profile.document_type = dto.document_type ?? profile.document_type;
    profile.document_number_hash =
      dto.document_number_hash ?? profile.document_number_hash;
    profile.document_front_asset_id =
      dto.document_front_asset_id ?? profile.document_front_asset_id;
    profile.document_back_asset_id =
      dto.document_back_asset_id ?? profile.document_back_asset_id;
    profile.selfie_asset_id = dto.selfie_asset_id ?? profile.selfie_asset_id;

    const useExistingKyc =
      dto.use_existing_kyc === true && this.isIdentityVerified(user);
    if (useExistingKyc) {
      profile.identity_status = 'VERIFIED';
      profile.identity_reused = true;
    } else if (dto.document_front_asset_id && dto.selfie_asset_id) {
      profile.identity_status = this.isIdentityVerified(user)
        ? 'VERIFIED'
        : 'PENDING';
      profile.identity_reused = false;
    } else {
      profile.identity_status = 'VERIFIED';
      profile.identity_reused = dto.identity_reused ?? true;
    }

    if (dto.hosting_policies_accepted === true) {
      profile.hosting_policies_accepted_at = new Date();
    }

    profile.application_status = 'PENDING';
    profile.host_verification_status = 'PENDING';
    profile.submitted_at = new Date();
    profile.reviewed_at = null;
    profile.reviewed_by = null;
    profile.rejection_reason = null;

    const saved = await this.hostProfileRepo.save(profile);
    return {
      ...this.toSubmitResponse(saved),
      message:
        'Host onboarding submitted. Your application will be reviewed shortly.',
    };
  }

  async getHostMe(user: StaysUserContext) {
    const profile = await this.hostProfileRepo.findOne({
      where: { user_id: user.userId },
    });

    const isHost = profile?.application_status === 'APPROVED';
    const canList =
      !!profile &&
      profile.application_status === 'APPROVED' &&
      profile.host_verification_status === 'APPROVED' &&
      !profile.listing_frozen;

    return {
      is_host: isHost,
      host_user_id: isHost ? user.userId : null,
      profile_id: profile?.id ?? null,
      application_status: profile?.application_status ?? 'NOT_STARTED',
      identity_status:
        profile?.identity_status ??
        (this.isIdentityVerified(user) ? 'VERIFIED' : 'NOT_STARTED'),
      host_verification_status:
        profile?.host_verification_status ?? 'NOT_STARTED',
      can_create_listing: canList,
      can_publish_listing: canList,
      rejection_reason: profile?.rejection_reason ?? null,
      submitted_at: profile?.submitted_at ?? null,
      reviewed_at: profile?.reviewed_at ?? null,
      source: profile?.source ?? null,
      submitted_from: profile?.submitted_from ?? null,
      kyc_verified: this.isIdentityVerified(user),
      identity_snapshot: user.identitySnapshot ?? null,
    };
  }

  async getLegacyApplicationStatus(userId: string) {
    const profile = await this.hostProfileRepo.findOne({
      where: { user_id: userId },
    });
    if (!profile) return null;
    return {
      id: profile.id,
      status:
        profile.application_status === 'PENDING'
          ? 'PENDING'
          : profile.application_status,
      identity_status: profile.identity_status,
      host_verification_status: profile.host_verification_status,
      submitted_at: profile.submitted_at,
      reviewed_at: profile.reviewed_at,
      rejection_reason: profile.rejection_reason,
    };
  }

  async getVerificationStatus(userId: string) {
    const profile = await this.resolveProfileForUser(userId);
    if (!profile) {
      return {
        status: 'NOT_STARTED',
        application_status: 'NOT_STARTED',
        identity_status: 'NOT_STARTED',
        message:
          'Host verification required to publish listings. Submit your host onboarding to get approved.',
      };
    }

    return {
      status: profile.host_verification_status,
      application_status: profile.application_status,
      identity_status: profile.identity_status,
      submitted_at: profile.submitted_at,
      reviewed_at: profile.reviewed_at,
      rejection_reason: profile.rejection_reason,
    };
  }

  async listForAdmin(params?: {
    application_status?: string;
    status?: string;
    limit?: number;
    offset?: number;
  }) {
    const { application_status, status, limit = 50, offset = 0 } = params || {};
    const safeLimit = Math.min(Math.max(1, Number(limit) || 50), 500);
    const safeOffset = Math.max(0, Number(offset) || 0);
    const qb = this.hostProfileRepo
      .createQueryBuilder('hp')
      .orderBy('hp.submitted_at', 'DESC', 'NULLS LAST')
      .addOrderBy('hp.created_at', 'DESC')
      .take(safeLimit)
      .skip(safeOffset);

    const appStatus = application_status ?? status;
    if (appStatus && appStatus !== 'all') {
      if (appStatus === 'UNDER_REVIEW') {
        qb.andWhere('hp.application_status = :pending', { pending: 'PENDING' });
      } else {
        qb.andWhere('hp.application_status = :appStatus', { appStatus });
      }
    }

    const [items, total] = await qb.getManyAndCount();
    return { items: items.map(toAdminHostProfileDto), total };
  }

  async approve(
    profileId: string,
    reviewedBy: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const profile = await this.dataSource.transaction(async (manager) => {
      const locked = await manager
        .getRepository(StaysHostProfile)
        .createQueryBuilder('hp')
        .where('hp.id = :id', { id: profileId })
        .setLock('pessimistic_write')
        .getOne();
      if (!locked) {
        throw new NotFoundException('Host profile not found');
      }
      if (
        locked.application_status !== 'PENDING' &&
        locked.application_status !== 'DRAFT'
      ) {
        throw new BadRequestException(
          `Cannot approve host onboarding with status ${locked.application_status}`,
        );
      }
      locked.application_status = 'APPROVED';
      locked.host_verification_status = 'APPROVED';
      locked.reviewed_at = new Date();
      locked.reviewed_by = reviewedBy;
      locked.rejection_reason = null;
      await manager.save(StaysHostProfile, locked);
      return locked;
    });

    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: reviewedBy,
        actor_role: 'ADMIN',
        entity_type: 'HOST_PROFILE',
        entity_id: profileId,
        action: 'HOST_ONBOARDING_APPROVED',
        metadata: {
          source: profile.source,
          submitted_from: profile.submitted_from,
        },
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );

    return {
      id: profile.id,
      status: 'APPROVED',
      application_status: 'APPROVED',
      host_user_id: profile.user_id,
      message: 'Host approved',
    };
  }

  async reject(
    profileId: string,
    reason: string,
    reviewedBy: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const profile = await this.hostProfileRepo.findOne({
      where: { id: profileId },
    });
    if (!profile) {
      throw new NotFoundException('Host profile not found');
    }
    if (
      profile.application_status !== 'PENDING' &&
      profile.application_status !== 'DRAFT'
    ) {
      throw new BadRequestException(
        `Cannot reject host onboarding with status ${profile.application_status}`,
      );
    }

    profile.application_status = 'REJECTED';
    profile.host_verification_status = 'REJECTED';
    profile.reviewed_at = new Date();
    profile.reviewed_by = reviewedBy;
    profile.rejection_reason = reason || 'Rejected by admin';
    await this.hostProfileRepo.save(profile);

    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: reviewedBy,
        actor_role: 'ADMIN',
        entity_type: 'HOST_PROFILE',
        entity_id: profileId,
        action: 'HOST_ONBOARDING_REJECTED',
        metadata: { reason },
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );

    return {
      id: profile.id,
      status: 'REJECTED',
      application_status: 'REJECTED',
      message: 'Host rejected',
    };
  }

  async findProfileByLegacyApplicationId(
    applicationId: string,
  ): Promise<StaysHostProfile | null> {
    const row = await this.dataSource.query(
      `SELECT applicant_user_id FROM host_applications WHERE id = $1 LIMIT 1`,
      [applicationId],
    );
    const applicantId = row?.[0]?.applicant_user_id as string | undefined;
    if (!applicantId) return null;
    return this.hostProfileRepo.findOne({ where: { user_id: applicantId } });
  }

  async approveLegacyApplication(applicationId: string, reviewedBy: string) {
    const profile = await this.findProfileByLegacyApplicationId(applicationId);
    if (!profile) {
      throw new NotFoundException(
        'No host profile found for this application. Resubmit onboarding.',
      );
    }
    return this.approve(profile.id, reviewedBy);
  }

  async rejectLegacyApplication(
    applicationId: string,
    reason: string,
    reviewedBy: string,
  ) {
    const profile = await this.findProfileByLegacyApplicationId(applicationId);
    if (!profile) {
      throw new NotFoundException('No host profile found for this application');
    }
    return this.reject(profile.id, reason, reviewedBy);
  }

  async countPendingApplications(): Promise<number> {
    return this.hostProfileRepo.count({
      where: { application_status: 'PENDING' },
    });
  }

  async resolveProfileForUser(userId: string) {
    return this.hostProfileRepo.findOne({ where: { user_id: userId } });
  }

  async isApprovedHost(userId: string): Promise<boolean> {
    const profile = await this.resolveProfileForUser(userId);
    return profile?.application_status === 'APPROVED';
  }

  async canList(userId: string): Promise<boolean> {
    const profile = await this.resolveProfileForUser(userId);
    return (
      profile?.application_status === 'APPROVED' &&
      profile?.host_verification_status === 'APPROVED' &&
      !profile?.listing_frozen
    );
  }

  private async assertOwnedVerificationAssets(
    userId: string,
    dto: SubmitHostOnboardingDto,
  ): Promise<void> {
    const checks: Array<{ assetId?: string; prefix: string }> = [
      { assetId: dto.document_front_asset_id, prefix: 'id_front' },
      { assetId: dto.document_back_asset_id, prefix: 'id_back' },
      { assetId: dto.selfie_asset_id, prefix: 'selfie' },
    ];
    for (const { assetId, prefix } of checks) {
      const id = assetId?.trim();
      if (!id) continue;
      const candidates = VERIFY_EXTS.map(
        (ext) => `host/${userId}/verification/${prefix}_${id}${ext}`,
      );
      const found = await this.mediaStorage.resolveFirstExisting(candidates);
      if (!found) {
        throw new BadRequestException(
          `Invalid ${prefix} asset_id — upload the document first as this user`,
        );
      }
    }
  }

  private toSubmitResponse(profile: StaysHostProfile) {
    return {
      id: profile.id,
      application_status: profile.application_status,
      identity_status: profile.identity_status,
      status: profile.application_status,
      message: 'Host onboarding status retrieved',
    };
  }
}

import { Inject, Injectable, Logger, Optional } from '@nestjs/common';
import { createHmac, randomBytes } from 'crypto';
import {
  isProductionRuntime,
  requirePublicBaseUrl,
} from '../../../common/security/secrets';

/** Optional Nest token so unit tests can inject a mock fetch without Nest DI. */
export const CMI_FETCH = 'CMI_FETCH';

export interface CmiOrderResult {
  provider: 'cmi';
  provider_intent_id: string;
  redirect_url: string;
  amount: number;
  currency: string;
}

export type CmiMerchantOp = 'PostAuth' | 'Void' | 'Credit';

export interface CmiMerchantResult {
  ok: boolean;
  op: CmiMerchantOp;
  providerIntentId: string;
  procReturnCode: string;
  raw?: string;
  error?: string;
}

function getCmiStoreKey(): string {
  const key = (process.env.CMI_STORE_KEY ?? '').trim();
  if (key) return key;
  if (isProductionRuntime() || process.env.STAYS_PAYMENT_PROVIDER === 'cmi') {
    throw new Error(
      'CMI_STORE_KEY is required when using CMI payments (set via environment variables).',
    );
  }
  return 'mock-store-key';
}

function getCmiClientId(): string {
  const id = (process.env.CMI_CLIENT_ID ?? '').trim();
  if (id) return id;
  if (isProductionRuntime() || process.env.STAYS_PAYMENT_PROVIDER === 'cmi') {
    throw new Error(
      'CMI_CLIENT_ID is required when using CMI payments (set via environment variables).',
    );
  }
  return 'mock-client';
}

/** Server-to-server merchant API (NestPay/CMI-style). Distinct from the 3D gate URL. */
export function getCmiApiUrl(env: NodeJS.ProcessEnv = process.env): string {
  const configured = (env.CMI_API_URL ?? '').trim();
  if (configured) return configured.replace(/\/$/, '');
  // Test gate host uses /fim/api for PostAuth/Void/Credit.
  const paymentUrl = (env.CMI_PAYMENT_URL ?? '').trim();
  if (paymentUrl.includes('est3Dgate')) {
    return paymentUrl.replace(/\/fim\/est3Dgate\/?$/i, '/fim/api');
  }
  return 'https://testpayment.cmi.co.ma/fim/api';
}

export type CmiFetch = (input: string, init?: RequestInit) => Promise<Response>;

@Injectable()
export class CmiPaymentProvider {
  private readonly logger = new Logger(CmiPaymentProvider.name);
  private readonly fetchImpl: CmiFetch;

  constructor(@Optional() @Inject(CMI_FETCH) fetchImpl?: CmiFetch) {
    this.fetchImpl = fetchImpl ?? fetch;
  }

  createOrder(input: {
    bookingId: string;
    amount: number;
    currency: string;
    guestUserId: string;
  }): CmiOrderResult {
    const clientId = getCmiClientId();
    const storeKey = getCmiStoreKey();
    const baseUrl =
      process.env.CMI_PAYMENT_URL ||
      'https://testpayment.cmi.co.ma/fim/est3Dgate';
    const callbackUrl =
      process.env.CMI_CALLBACK_URL ||
      `${requirePublicBaseUrl('STAYS_PUBLIC_URL', 'http://127.0.0.1:3002')}/api/v1/stays/webhooks/payments/cmi`;
    const okUrl =
      process.env.CMI_OK_URL ||
      `${requirePublicBaseUrl('STAYS_WEB_URL', 'http://127.0.0.1:3000')}/bookings`;
    const failUrl =
      process.env.CMI_FAIL_URL ||
      `${requirePublicBaseUrl('STAYS_WEB_URL', 'http://127.0.0.1:3000')}/bookings`;

    const orderId = `STAYS-${input.bookingId}-${Date.now()}`;
    const amount = input.amount.toFixed(2);
    const rnd = randomBytes(8).toString('hex');

    const hashPlain = [
      clientId,
      orderId,
      amount,
      input.currency,
      okUrl,
      failUrl,
      'PreAuth',
      rnd,
      storeKey,
    ].join('|');

    const hash = createHmac('sha512', storeKey)
      .update(hashPlain)
      .digest('base64');

    const params = new URLSearchParams({
      clientid: clientId,
      oid: orderId,
      amount,
      currency: input.currency,
      okUrl,
      failUrl,
      callbackUrl,
      TranType: 'PreAuth',
      rnd,
      hash,
      email: '',
      BillToName: input.guestUserId,
      lang: 'fr',
    });

    return {
      provider: 'cmi',
      provider_intent_id: orderId,
      redirect_url: `${baseUrl}?${params.toString()}`,
      amount: input.amount,
      currency: input.currency,
    };
  }

  verifyCallback(body: Record<string, unknown>): {
    valid: boolean;
    providerIntentId?: string;
    success: boolean;
  } {
    // Always verify HMAC — never accept unsigned callbacks (fail closed).
    const storeKey = getCmiStoreKey();
    const oid = String(body.oid ?? body.OID ?? '');
    const amount = String(body.amount ?? '');
    const procReturnCode = String(
      body.ProcReturnCode ?? body.procReturnCode ?? '',
    );
    const hashFromGateway = String(body.HASH ?? body.hash ?? '');

    if (!hashFromGateway || !oid) {
      return {
        valid: false,
        providerIntentId: oid || undefined,
        success: false,
      };
    }

    const hashPlain = [oid, storeKey, procReturnCode, amount].join('|');
    const expected = createHmac('sha512', storeKey)
      .update(hashPlain)
      .digest('base64');
    const valid = expected === hashFromGateway;
    return {
      valid,
      providerIntentId: oid || undefined,
      success: valid && procReturnCode === '00',
    };
  }

  /** Capture a successful PreAuth (PostAuth). */
  async capture(input: {
    providerIntentId: string;
    amount: number;
    currency: string;
  }): Promise<CmiMerchantResult> {
    return this.merchantRequest('PostAuth', input);
  }

  /** Release an unpaid PreAuth hold. */
  async voidAuthorization(input: {
    providerIntentId: string;
  }): Promise<CmiMerchantResult> {
    return this.merchantRequest('Void', {
      providerIntentId: input.providerIntentId,
      amount: 0,
      currency: 'MAD',
      omitAmount: true,
    });
  }

  /** Credit/refund after capture. */
  async refund(input: {
    providerIntentId: string;
    amount: number;
    currency: string;
  }): Promise<CmiMerchantResult> {
    return this.merchantRequest('Credit', input);
  }

  /**
   * NestPay/CMI merchant API: form POST with HASH.
   * Hash material: ClientId|OrderId|Amount|Currency|storeKey (Amount empty for Void).
   */
  async merchantRequest(
    op: CmiMerchantOp,
    input: {
      providerIntentId: string;
      amount: number;
      currency: string;
      omitAmount?: boolean;
    },
  ): Promise<CmiMerchantResult> {
    const clientId = getCmiClientId();
    const storeKey = getCmiStoreKey();
    const amount = input.omitAmount ? '' : Number(input.amount).toFixed(2);
    const currency = input.omitAmount ? '' : input.currency;
    const hashPlain = [
      clientId,
      input.providerIntentId,
      amount,
      currency,
      storeKey,
    ].join('|');
    const hash = createHmac('sha512', storeKey)
      .update(hashPlain)
      .digest('base64');

    const body = new URLSearchParams({
      CLIENTID: clientId,
      ORDERID: input.providerIntentId,
      NAME: op,
      TYPE: op,
      HASH: hash,
    });
    if (!input.omitAmount) {
      body.set('AMOUNT', amount);
      body.set('currency', currency);
    }

    const apiUrl = getCmiApiUrl();
    try {
      const res = await this.fetchImpl(apiUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: body.toString(),
      });
      const raw = await res.text();
      const procReturnCode = parseProcReturnCode(raw);
      const ok = res.ok && procReturnCode === '00';
      if (!ok) {
        this.logger.warn(
          `CMI ${op} failed for ${input.providerIntentId}: HTTP ${res.status} code=${procReturnCode}`,
        );
      }
      return {
        ok,
        op,
        providerIntentId: input.providerIntentId,
        procReturnCode,
        raw: raw.slice(0, 2000),
        error: ok ? undefined : `CMI_${op}_FAILED`,
      };
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      this.logger.error(`CMI ${op} network error: ${message}`);
      return {
        ok: false,
        op,
        providerIntentId: input.providerIntentId,
        procReturnCode: '',
        error: message,
      };
    }
  }
}

function parseProcReturnCode(raw: string): string {
  const xml = /<ProcReturnCode>([^<]*)<\/ProcReturnCode>/i.exec(raw);
  if (xml?.[1]) return xml[1].trim();
  const form = /(?:^|[&\n])ProcReturnCode=([^&\n\r]*)/i.exec(raw);
  if (form?.[1]) return decodeURIComponent(form[1].trim());
  try {
    const json = JSON.parse(raw) as {
      ProcReturnCode?: string;
      procReturnCode?: string;
    };
    return String(json.ProcReturnCode ?? json.procReturnCode ?? '').trim();
  } catch {
    return '';
  }
}

import {
  BadRequestException,
  ConflictException,
  Injectable,
  Logger,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { In, Repository } from 'typeorm';
import { randomUUID } from 'crypto';
import * as ical from 'node-ical';
import { StaysExternalCalendar } from '../entities/stays-external-calendar.entity';
import { StaysExternalCalendarEvent } from '../entities/stays-external-calendar-event.entity';
import { StaysExternalCalendarSyncLog } from '../entities/stays-external-calendar-sync-log.entity';
import { StaysAvailabilityBlock } from '../entities/stays-availability-block.entity';
import { StaysListing } from '../entities/stays-listing.entity';
import { StaysBooking } from '../entities/stays-booking.entity';
import { BOOKED_STATUSES } from './stays-availability.service';
import { validateOutboundHttpsUrl } from '../../../common/security/outbound-url';
import { fetchOutboundHttps } from '../../../common/security/outbound-https-fetch';

const MAX_CALENDARS_PER_LISTING = 10;
const SYNC_COOLDOWN_MS = 30_000;
const FETCH_TIMEOUT_MS = 15_000;
const MAX_ICS_BYTES = 2_000_000;
const IMPORT_PAST_DAYS = 30;
const HORIZON_MONTHS = 18;
const BATCH_LIMIT = 100;

export type SyncSummary = {
  calendar_id: string;
  outcome: 'SUCCESS' | 'NOT_MODIFIED' | 'TIMEOUT' | 'ERROR';
  imported_events: number;
  removed_events: number;
  blocked_nights: number;
  duration_ms: number;
  last_reservation: { start: string; end: string } | null;
  message?: string;
};

@Injectable()
export class CalendarSyncService {
  private readonly logger = new Logger(CalendarSyncService.name);

  constructor(
    @InjectRepository(StaysExternalCalendar)
    private readonly calendarRepo: Repository<StaysExternalCalendar>,
    @InjectRepository(StaysExternalCalendarEvent)
    private readonly eventRepo: Repository<StaysExternalCalendarEvent>,
    @InjectRepository(StaysExternalCalendarSyncLog)
    private readonly logRepo: Repository<StaysExternalCalendarSyncLog>,
    @InjectRepository(StaysAvailabilityBlock)
    private readonly blockRepo: Repository<StaysAvailabilityBlock>,
    @InjectRepository(StaysListing)
    private readonly listingRepo: Repository<StaysListing>,
    @InjectRepository(StaysBooking)
    private readonly bookingRepo: Repository<StaysBooking>,
  ) {}

  async listCalendars(listingId: string, hostUserId: string) {
    await this.assertListingOwner(listingId, hostUserId);
    const calendars = await this.calendarRepo.find({
      where: { listing_id: listingId },
      order: { created_at: 'ASC' },
    });
    const enriched = await Promise.all(
      calendars.map(async (c) => {
        const history = await this.logRepo.find({
          where: { external_calendar_id: c.id },
          order: { started_at: 'DESC' },
          take: 5,
        });
        return this.toCalendarDto(c, history);
      }),
    );
    return {
      listing_id: listingId,
      connected_calendars_count: calendars.length,
      calendars: enriched,
    };
  }

  async connectCalendar(
    listingId: string,
    hostUserId: string,
    input: {
      provider: StaysExternalCalendar['provider'];
      ics_url: string;
      label?: string;
      provider_listing_reference?: string;
    },
  ) {
    await this.assertListingOwner(listingId, hostUserId);
    const icsUrl = this.validateIcsUrl(input.ics_url);

    const count = await this.calendarRepo.count({
      where: { listing_id: listingId },
    });
    if (count >= MAX_CALENDARS_PER_LISTING) {
      throw new BadRequestException(
        `Maximum ${MAX_CALENDARS_PER_LISTING} calendars per listing`,
      );
    }

    const dup = await this.calendarRepo.findOne({
      where: { listing_id: listingId, ics_url: icsUrl },
    });
    if (dup) {
      throw new ConflictException('This calendar URL is already connected');
    }

    const cal = this.calendarRepo.create({
      listing_id: listingId,
      provider: input.provider,
      label: (input.label ?? '').trim() || input.provider,
      ics_url: icsUrl,
      provider_listing_reference:
        input.provider_listing_reference?.trim() || null,
      status: 'ACTIVE',
      next_sync_at: new Date(),
    });
    await this.calendarRepo.save(cal);

    const summary = await this.syncCalendar(cal.id, { force: true });
    const fresh = await this.calendarRepo.findOneOrFail({
      where: { id: cal.id },
    });
    const history = await this.logRepo.find({
      where: { external_calendar_id: cal.id },
      order: { started_at: 'DESC' },
      take: 5,
    });
    return {
      calendar: this.toCalendarDto(fresh, history),
      sync: summary,
    };
  }

  async updateCalendar(
    listingId: string,
    calendarId: string,
    hostUserId: string,
    patch: { label?: string; status?: 'ACTIVE' | 'PAUSED' },
  ) {
    const cal = await this.getOwnedCalendar(listingId, calendarId, hostUserId);
    if (patch.label !== undefined) cal.label = patch.label.trim();
    if (patch.status === 'PAUSED' || patch.status === 'ACTIVE') {
      cal.status = patch.status;
      if (patch.status === 'ACTIVE') {
        cal.next_sync_at = new Date();
        cal.consecutive_failures = 0;
      }
    }
    await this.calendarRepo.save(cal);
    return this.toCalendarDto(cal);
  }

  async deleteCalendar(
    listingId: string,
    calendarId: string,
    hostUserId: string,
  ) {
    await this.getOwnedCalendar(listingId, calendarId, hostUserId);
    // Cascade removes events, logs, ICAL blocks via FK
    await this.calendarRepo.delete({ id: calendarId });
    return { deleted: true, calendar_id: calendarId };
  }

  async syncNow(listingId: string, calendarId: string, hostUserId: string) {
    const cal = await this.getOwnedCalendar(listingId, calendarId, hostUserId);
    if (cal.status === 'PAUSED') {
      throw new BadRequestException(
        'Calendar is paused — resume before syncing',
      );
    }
    if (
      cal.last_attempt_at &&
      Date.now() - cal.last_attempt_at.getTime() < SYNC_COOLDOWN_MS
    ) {
      throw new BadRequestException('Please wait 30 seconds between syncs');
    }
    return this.syncCalendar(calendarId, { force: true });
  }

  async getOrCreateExport(
    listingId: string,
    hostUserId: string,
  ): Promise<{ url: string; token: string }> {
    const listing = await this.assertListingOwner(listingId, hostUserId);
    if (!listing.calendar_export_token) {
      listing.calendar_export_token = randomUUID();
      await this.listingRepo.save(listing);
    }
    return {
      token: listing.calendar_export_token,
      url: this.publicExportUrl(listing.calendar_export_token),
    };
  }

  async regenerateExport(
    listingId: string,
    hostUserId: string,
  ): Promise<{ url: string; token: string }> {
    const listing = await this.assertListingOwner(listingId, hostUserId);
    listing.calendar_export_token = randomUUID();
    await this.listingRepo.save(listing);
    return {
      token: listing.calendar_export_token,
      url: this.publicExportUrl(listing.calendar_export_token),
    };
  }

  async buildExportIcs(token: string): Promise<string> {
    const listing = await this.listingRepo.findOne({
      where: { calendar_export_token: token },
      select: ['id', 'title'],
    });
    if (!listing) throw new NotFoundException('Calendar not found');

    const { from, to } = this.exportHorizon();
    const bookings = await this.bookingRepo
      .createQueryBuilder('b')
      .where('b.listing_id = :listingId', { listingId: listing.id })
      .andWhere('b.status IN (:...statuses)', {
        statuses: [...BOOKED_STATUSES],
      })
      .andWhere('b.checkin_date < :to', { to })
      .andWhere('b.checkout_date > :from', { from })
      .getMany();

    const blocks = await this.blockRepo
      .createQueryBuilder('ab')
      .where('ab.listing_id = :listingId', { listingId: listing.id })
      .andWhere('ab.is_blocked = true')
      .andWhere('ab.source IN (:...sources)', { sources: ['HOST', 'ADMIN'] })
      .andWhere('ab.date >= :from', { from })
      .andWhere('ab.date < :to', { to })
      .getMany();

    const lines = [
      'BEGIN:VCALENDAR',
      'VERSION:2.0',
      'PRODID:-//Nexa Stays//Calendar Export//EN',
      'CALSCALE:GREGORIAN',
      'METHOD:PUBLISH',
    ];

    for (const b of bookings) {
      const start = this.dateStr(b.checkin_date);
      const end = this.dateStr(b.checkout_date);
      lines.push(
        'BEGIN:VEVENT',
        `UID:nexa-booking-${b.id}@nexastays`,
        `DTSTART;VALUE=DATE:${start.replace(/-/g, '')}`,
        `DTEND;VALUE=DATE:${end.replace(/-/g, '')}`,
        'SUMMARY:Reserved',
        'END:VEVENT',
      );
    }

    // Collapse consecutive HOST/ADMIN nights into ranges for cleaner ICS
    const nights = blocks.map((b) => this.dateStr(b.date)).sort();
    for (const range of this.collapseNights(nights)) {
      lines.push(
        'BEGIN:VEVENT',
        `UID:nexa-block-${listing.id}-${range.start}@nexastays`,
        `DTSTART;VALUE=DATE:${range.start.replace(/-/g, '')}`,
        `DTEND;VALUE=DATE:${range.end.replace(/-/g, '')}`,
        'SUMMARY:Unavailable',
        'END:VEVENT',
      );
    }

    lines.push('END:VCALENDAR');
    return lines.join('\r\n');
  }

  /** Cron: drain due calendars */
  async processDueCalendars(): Promise<number> {
    const now = new Date();
    const due = await this.calendarRepo
      .createQueryBuilder('c')
      .where('c.status IN (:...statuses)', { statuses: ['ACTIVE', 'ERROR'] })
      .andWhere('c.next_sync_at <= :now', { now })
      .andWhere('(c.locked_until IS NULL OR c.locked_until < :now)', { now })
      .orderBy('c.next_sync_at', 'ASC')
      .take(BATCH_LIMIT)
      .getMany();

    let n = 0;
    for (const cal of due) {
      try {
        await this.syncCalendar(cal.id, { force: false });
        n += 1;
      } catch (err) {
        this.logger.warn(
          `Sync failed for ${cal.id}: ${err instanceof Error ? err.message : err}`,
        );
      }
    }
    return n;
  }

  async syncCalendar(
    calendarId: string,
    opts: { force: boolean },
  ): Promise<SyncSummary> {
    const started = Date.now();
    const claimUntil = new Date(Date.now() + 2 * 60_000);
    const claim = await this.calendarRepo
      .createQueryBuilder()
      .update(StaysExternalCalendar)
      .set({
        status: 'SYNCING',
        locked_until: claimUntil,
        last_attempt_at: new Date(),
      })
      .where('id = :id', { id: calendarId })
      .andWhere('(locked_until IS NULL OR locked_until < NOW())')
      .andWhere('status != :syncing', { syncing: 'SYNCING' })
      .execute();

    if (!claim.affected && !opts.force) {
      return {
        calendar_id: calendarId,
        outcome: 'ERROR',
        imported_events: 0,
        removed_events: 0,
        blocked_nights: 0,
        duration_ms: 0,
        last_reservation: null,
        message: 'Sync already in progress',
      };
    }

    // Force path: still try claim; if locked by another, wait/fail
    if (!claim.affected && opts.force) {
      const forced = await this.calendarRepo
        .createQueryBuilder()
        .update(StaysExternalCalendar)
        .set({
          status: 'SYNCING',
          locked_until: claimUntil,
          last_attempt_at: new Date(),
        })
        .where('id = :id', { id: calendarId })
        .andWhere('(locked_until IS NULL OR locked_until < NOW())')
        .execute();
      if (!forced.affected) {
        throw new ConflictException('Sync already in progress');
      }
    }

    const cal = await this.calendarRepo.findOneOrFail({
      where: { id: calendarId },
    });
    const previousStatus = cal.status === 'PAUSED' ? 'PAUSED' : 'ACTIVE';

    try {
      const fetched = await this.fetchIcs(cal);
      if (fetched.notModified) {
        const duration_ms = Date.now() - started;
        const summary: SyncSummary = {
          calendar_id: calendarId,
          outcome: 'NOT_MODIFIED',
          imported_events: 0,
          removed_events: 0,
          blocked_nights: cal.sync_result?.blocked_nights ?? 0,
          duration_ms,
          last_reservation: cal.sync_result?.last_reservation ?? null,
        };
        await this.finishSuccess(cal, summary, {
          not_modified: true,
          restoreStatus: previousStatus === 'PAUSED' ? 'PAUSED' : 'ACTIVE',
        });
        return summary;
      }

      const parsed = this.parseIcsEvents(fetched.body);
      const { from, to } = this.importHorizon();
      const inHorizon = parsed.filter(
        (e) => e.end_date > from && e.start_date < to,
      );

      const oldEvents = await this.eventRepo.find({
        where: { external_calendar_id: calendarId },
      });
      await this.eventRepo.delete({ external_calendar_id: calendarId });

      if (inHorizon.length) {
        await this.eventRepo.insert(
          inHorizon.map((e) => ({
            external_calendar_id: calendarId,
            uid: e.uid,
            recurrence_id: e.recurrence_id,
            start_date: this.parseYmd(e.start_date),
            end_date: this.parseYmd(e.end_date),
            summary: e.summary,
          })),
        );
      }

      const nights = this.expandNights(inHorizon, from, to);
      const removed_events = Math.max(0, oldEvents.length - inHorizon.length);

      // Remove ICAL nights belonging to this calendar that are no longer present
      const existingIcal = await this.blockRepo.find({
        where: { external_calendar_id: calendarId, source: 'ICAL' },
      });
      const toRemove = existingIcal.filter(
        (b) => !nights.has(this.dateStr(b.date)),
      );
      if (toRemove.length) {
        await this.blockRepo.delete({ id: In(toRemove.map((b) => b.id)) });
      }

      // Insert new ICAL nights without overwriting HOST/ADMIN
      let blocked_nights = 0;
      for (const night of nights) {
        const existing = await this.blockRepo.findOne({
          where: {
            listing_id: cal.listing_id,
            date: this.parseYmd(night) as unknown as Date,
          },
        });
        if (existing?.source === 'HOST' || existing?.source === 'ADMIN') {
          continue;
        }
        if (
          existing?.source === 'ICAL' &&
          existing.external_calendar_id &&
          existing.external_calendar_id !== calendarId
        ) {
          blocked_nights += 1;
          continue;
        }
        await this.blockRepo.upsert(
          {
            listing_id: cal.listing_id,
            date: this.parseYmd(night),
            is_blocked: true,
            source: 'ICAL',
            external_calendar_id: calendarId,
          },
          ['listing_id', 'date'],
        );
        blocked_nights += 1;
      }

      // Recount actual ICAL nights for this calendar
      blocked_nights = await this.blockRepo.count({
        where: {
          external_calendar_id: calendarId,
          source: 'ICAL',
          is_blocked: true,
        },
      });

      const last_reservation = this.pickLastReservation(inHorizon);
      const duration_ms = Date.now() - started;
      const summary: SyncSummary = {
        calendar_id: calendarId,
        outcome: 'SUCCESS',
        imported_events: inHorizon.length,
        removed_events,
        blocked_nights,
        duration_ms,
        last_reservation,
      };

      if (fetched.etag) cal.etag = fetched.etag;
      if (fetched.lastModified) cal.last_modified = fetched.lastModified;

      await this.finishSuccess(cal, summary, {
        restoreStatus: 'ACTIVE',
      });
      return summary;
    } catch (err) {
      const duration_ms = Date.now() - started;
      const isTimeout =
        err instanceof Error &&
        (err.name === 'AbortError' || /timeout/i.test(err.message));
      const message = err instanceof Error ? err.message : String(err);
      const summary: SyncSummary = {
        calendar_id: calendarId,
        outcome: isTimeout ? 'TIMEOUT' : 'ERROR',
        imported_events: 0,
        removed_events: 0,
        blocked_nights: cal.sync_result?.blocked_nights ?? 0,
        duration_ms,
        last_reservation: cal.sync_result?.last_reservation ?? null,
        message,
      };
      await this.finishFailure(cal, summary);
      return summary;
    }
  }

  private async finishSuccess(
    cal: StaysExternalCalendar,
    summary: SyncSummary,
    opts: { not_modified?: boolean; restoreStatus: 'ACTIVE' | 'PAUSED' },
  ) {
    const now = new Date();
    cal.status = opts.restoreStatus;
    cal.locked_until = null;
    cal.last_successful_sync_at = now;
    cal.last_error = null;
    cal.consecutive_failures = 0;
    cal.next_sync_at = this.nextSyncAt(0);
    cal.sync_result = {
      imported_events: summary.imported_events,
      removed_events: summary.removed_events,
      blocked_nights: summary.blocked_nights,
      duration_ms: summary.duration_ms,
      not_modified: opts.not_modified ?? false,
      last_reservation: summary.last_reservation,
    };
    await this.calendarRepo.save(cal);
    await this.appendLog(cal.id, summary);
    await this.trimLogs(cal.id);
  }

  private async finishFailure(
    cal: StaysExternalCalendar,
    summary: SyncSummary,
  ) {
    const failures = (cal.consecutive_failures ?? 0) + 1;
    cal.status = 'ERROR';
    cal.locked_until = null;
    cal.last_error = summary.message ?? 'Sync failed';
    cal.consecutive_failures = failures;
    cal.next_sync_at = this.nextSyncAt(failures);
    cal.sync_result = {
      ...(cal.sync_result ?? {}),
      duration_ms: summary.duration_ms,
    };
    await this.calendarRepo.save(cal);
    await this.appendLog(cal.id, summary);
    await this.trimLogs(cal.id);
  }

  private async appendLog(calendarId: string, summary: SyncSummary) {
    await this.logRepo.save(
      this.logRepo.create({
        external_calendar_id: calendarId,
        started_at: new Date(Date.now() - (summary.duration_ms || 0)),
        finished_at: new Date(),
        outcome: summary.outcome,
        message: summary.message ?? null,
        imported_events: summary.imported_events,
        removed_events: summary.removed_events,
        blocked_nights: summary.blocked_nights,
        duration_ms: summary.duration_ms,
      }),
    );
  }

  private async trimLogs(calendarId: string) {
    const keep = await this.logRepo.find({
      where: { external_calendar_id: calendarId },
      order: { started_at: 'DESC' },
      take: 5,
      select: ['id'],
    });
    const keepIds = keep.map((l) => l.id);
    if (keepIds.length === 0) return;
    await this.logRepo
      .createQueryBuilder()
      .delete()
      .from(StaysExternalCalendarSyncLog)
      .where('external_calendar_id = :cid', { cid: calendarId })
      .andWhere('id NOT IN (:...ids)', { ids: keepIds })
      .execute();
  }

  private nextSyncAt(consecutiveFailures: number): Date {
    const steps = [5, 15, 60, 180, 360]; // minutes
    const idx = Math.min(consecutiveFailures, steps.length - 1);
    const baseMin = consecutiveFailures === 0 ? 5 : steps[idx];
    const jitterMs = Math.floor(Math.random() * 60_000);
    return new Date(Date.now() + baseMin * 60_000 + jitterMs);
  }

  private async fetchIcs(cal: StaysExternalCalendar): Promise<{
    body: string;
    notModified: boolean;
    etag?: string;
    lastModified?: string;
  }> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);
    try {
      // Re-validate stored URL on every fetch (defense in depth).
      const icsUrl = validateOutboundHttpsUrl(cal.ics_url);
      const headers: Record<string, string> = {
        Accept: 'text/calendar, text/plain, */*',
        'User-Agent': 'NexaStaysCalendarSync/1.0',
      };
      if (cal.etag) headers['If-None-Match'] = cal.etag;
      if (cal.last_modified) headers['If-Modified-Since'] = cal.last_modified;

      // SSRF-safe: HTTPS-only, DNS public-only, IP pin, manual redirect revalidation.
      const res = await fetchOutboundHttps(icsUrl, {
        headers,
        signal: controller.signal,
        timeoutMs: FETCH_TIMEOUT_MS,
      });

      if (res.statusCode === 304) {
        return { body: '', notModified: true };
      }
      if (res.statusCode < 200 || res.statusCode >= 300) {
        throw new Error(`HTTP ${res.statusCode} fetching calendar`);
      }

      if (res.body.byteLength > MAX_ICS_BYTES) {
        throw new Error('Calendar file too large');
      }
      const header = (name: string): string | undefined => {
        const v = res.headers[name];
        if (Array.isArray(v)) return v[0];
        return v;
      };
      return {
        body: res.body.toString('utf8'),
        notModified: false,
        etag: header('etag'),
        lastModified: header('last-modified'),
      };
    } catch (err) {
      if (err instanceof BadRequestException) {
        throw err;
      }
      // Do not leak DNS/network internals to clients via sync summaries upstream.
      this.logger.warn(
        `ICS fetch failed for calendar ${cal.id}: ${err instanceof Error ? err.message : 'error'}`,
      );
      throw err;
    } finally {
      clearTimeout(timer);
    }
  }

  private parseIcsEvents(body: string): Array<{
    uid: string;
    recurrence_id: string;
    start_date: string;
    end_date: string;
    summary: string | null;
  }> {
    const data = ical.sync.parseICS(body);
    const out: Array<{
      uid: string;
      recurrence_id: string;
      start_date: string;
      end_date: string;
      summary: string | null;
    }> = [];

    for (const key of Object.keys(data)) {
      const ev = data[key];
      if (!ev || (ev as { type?: string }).type !== 'VEVENT') continue;
      const vevent = ev as ical.VEvent;
      if (vevent.status === 'CANCELLED') continue;
      const start = this.toDateOnly(vevent.start);
      let end = this.toDateOnly(vevent.end);
      if (!start) continue;
      if (!end || end <= start) {
        // All-day single day or missing end → one night
        const d = new Date(start + 'T00:00:00Z');
        d.setUTCDate(d.getUTCDate() + 1);
        end = d.toISOString().slice(0, 10);
      }
      const uid = String(vevent.uid ?? key);
      const recurrence_id = vevent.recurrenceid
        ? (this.toDateOnly(vevent.recurrenceid) ?? '')
        : '';
      out.push({
        uid,
        recurrence_id,
        start_date: start,
        end_date: end,
        summary: vevent.summary ? String(vevent.summary) : null,
      });
    }
    return out;
  }

  private toDateOnly(value: unknown): string | null {
    if (!value) return null;
    if (value instanceof Date && !Number.isNaN(value.getTime())) {
      return value.toISOString().slice(0, 10);
    }
    if (typeof value === 'string') {
      const m = /^(\d{4})(\d{2})(\d{2})/.exec(value.replace(/-/g, ''));
      if (m) return `${m[1]}-${m[2]}-${m[3]}`;
      const d = new Date(value);
      if (!Number.isNaN(d.getTime())) return d.toISOString().slice(0, 10);
    }
    return null;
  }

  private expandNights(
    events: Array<{ start_date: string; end_date: string }>,
    from: string,
    to: string,
  ): Set<string> {
    const nights = new Set<string>();
    for (const e of events) {
      let cursor = e.start_date < from ? from : e.start_date;
      const end = e.end_date > to ? to : e.end_date;
      while (cursor < end) {
        nights.add(cursor);
        const d = new Date(cursor + 'T00:00:00Z');
        d.setUTCDate(d.getUTCDate() + 1);
        cursor = d.toISOString().slice(0, 10);
      }
    }
    return nights;
  }

  private pickLastReservation(
    events: Array<{ start_date: string; end_date: string }>,
  ): { start: string; end: string } | null {
    if (!events.length) return null;
    const sorted = [...events].sort((a, b) =>
      b.start_date.localeCompare(a.start_date),
    );
    return { start: sorted[0].start_date, end: sorted[0].end_date };
  }

  private importHorizon(): { from: string; to: string } {
    const now = new Date();
    const fromD = new Date(
      Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()),
    );
    fromD.setUTCDate(fromD.getUTCDate() - IMPORT_PAST_DAYS);
    const toD = new Date(fromD);
    toD.setUTCDate(toD.getUTCDate() + IMPORT_PAST_DAYS);
    toD.setUTCMonth(toD.getUTCMonth() + HORIZON_MONTHS);
    return {
      from: fromD.toISOString().slice(0, 10),
      to: toD.toISOString().slice(0, 10),
    };
  }

  private exportHorizon(): { from: string; to: string } {
    const now = new Date();
    const fromD = new Date(
      Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()),
    );
    const toD = new Date(fromD);
    toD.setUTCMonth(toD.getUTCMonth() + HORIZON_MONTHS);
    return {
      from: fromD.toISOString().slice(0, 10),
      to: toD.toISOString().slice(0, 10),
    };
  }

  private collapseNights(
    nights: string[],
  ): Array<{ start: string; end: string }> {
    if (!nights.length) return [];
    const ranges: Array<{ start: string; end: string }> = [];
    let start = nights[0];
    let prev = nights[0];
    for (let i = 1; i < nights.length; i++) {
      const nextExpected = (() => {
        const d = new Date(prev + 'T00:00:00Z');
        d.setUTCDate(d.getUTCDate() + 1);
        return d.toISOString().slice(0, 10);
      })();
      if (nights[i] === nextExpected) {
        prev = nights[i];
        continue;
      }
      const endD = new Date(prev + 'T00:00:00Z');
      endD.setUTCDate(endD.getUTCDate() + 1);
      ranges.push({ start, end: endD.toISOString().slice(0, 10) });
      start = nights[i];
      prev = nights[i];
    }
    const endD = new Date(prev + 'T00:00:00Z');
    endD.setUTCDate(endD.getUTCDate() + 1);
    ranges.push({ start, end: endD.toISOString().slice(0, 10) });
    return ranges;
  }

  private validateIcsUrl(raw: string): string {
    return validateOutboundHttpsUrl(raw);
  }

  private publicExportUrl(token: string): string {
    const base =
      process.env.STAYS_PUBLIC_URL?.replace(/\/$/, '') ||
      'http://127.0.0.1:3002';
    return `${base}/api/v1/stays/calendar/${token}.ics`;
  }

  private dateStr(d: Date | string): string {
    if (typeof d === 'string') return d.slice(0, 10);
    return d.toISOString().slice(0, 10);
  }

  private parseYmd(ymd: string): Date {
    const [y, m, d] = ymd.split('-').map(Number);
    return new Date(Date.UTC(y, m - 1, d));
  }

  private async assertListingOwner(listingId: string, hostUserId: string) {
    const listing = await this.listingRepo.findOne({
      where: { id: listingId },
      select: ['id', 'host_user_id', 'calendar_export_token', 'title'],
    });
    if (!listing || listing.host_user_id !== hostUserId) {
      throw new NotFoundException('Listing not found');
    }
    return listing;
  }

  private async getOwnedCalendar(
    listingId: string,
    calendarId: string,
    hostUserId: string,
  ) {
    await this.assertListingOwner(listingId, hostUserId);
    const cal = await this.calendarRepo.findOne({
      where: { id: calendarId, listing_id: listingId },
    });
    if (!cal) throw new NotFoundException('Calendar not found');
    return cal;
  }

  private toCalendarDto(
    c: StaysExternalCalendar,
    history?: StaysExternalCalendarSyncLog[],
  ) {
    const health =
      c.status === 'PAUSED'
        ? 'Paused'
        : c.status === 'ERROR'
          ? 'Error'
          : c.status === 'SYNCING'
            ? 'Syncing'
            : 'Healthy';
    return {
      id: c.id,
      listing_id: c.listing_id,
      provider: c.provider,
      provider_listing_reference: c.provider_listing_reference,
      label: c.label,
      ics_url: c.ics_url,
      status: c.status,
      health,
      next_sync_at: c.next_sync_at,
      last_attempt_at: c.last_attempt_at,
      last_successful_sync_at: c.last_successful_sync_at,
      last_error: c.last_error,
      sync_result: c.sync_result,
      sync_version: c.sync_version,
      created_at: c.created_at,
      history: (history ?? []).map((h) => ({
        id: h.id,
        started_at: h.started_at,
        finished_at: h.finished_at,
        outcome: h.outcome,
        message: h.message,
        imported_events: h.imported_events,
        blocked_nights: h.blocked_nights,
        duration_ms: h.duration_ms,
      })),
    };
  }
}

import { BadRequestException, Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { In, Repository } from 'typeorm';
import { StaysBooking } from '../entities/stays-booking.entity';
import { StaysListing } from '../entities/stays-listing.entity';
import { StaysLedgerEntry } from '../entities/stays-ledger-entry.entity';
import { StaysExternalCalendar } from '../entities/stays-external-calendar.entity';
import { BookingLifecycleService } from './booking-lifecycle.service';
import { HostListingsService } from './host-listings.service';
import {
  HOST_ANALYTICS_OCCUPANCY_BASIS,
  HOST_ANALYTICS_PERIODS,
  type HostAnalyticsPeriodId,
  type HostAnalyticsPropertyDto,
  type HostAnalyticsResponseDto,
} from '../dto/host-analytics.dto';
import {
  bookedNightsInHalfOpenRange,
  getDashboardNow,
  stayNights,
  toCasablancaYmd,
  toDateOnlyYmd,
  ymdCompare,
  ymdInHalfOpen,
  type DashboardNow,
} from './host-dashboard-timezone';

const EARNING_STATUSES: StaysBooking['status'][] = [
  'CONFIRMED',
  'CHECKED_IN',
  'COMPLETED',
];

const PENDING_STATUSES: StaysBooking['status'][] = [
  'INITIATED',
  'PAYMENT_PENDING',
];

const FUTURE_EARNING_STATUSES: StaysBooking['status'][] = [
  'CONFIRMED',
  'CHECKED_IN',
];

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}

function hostPayout(b: StaysBooking): number {
  if (b.payout_amount != null) return Number(b.payout_amount);
  return Math.max(0, Number(b.total_subtotal) - Number(b.host_fee));
}

function grossPaid(b: StaysBooking): number {
  return Number(b.total_paid ?? 0);
}

function platformFees(b: StaysBooking): number {
  return Number(b.guest_fee ?? 0) + Number(b.host_fee ?? 0);
}

type ResolvedPeriod = {
  id: HostAnalyticsPeriodId;
  start: string;
  end_exclusive: string;
  /** Finite Casablanca period days for occupancy; null for all_time. */
  period_days: number | null;
  /**
   * Earnings attribution:
   * - attr: confirmed_at ?? created_at in period (H3 money)
   * - checkin_window: CONFIRMED|CHECKED_IN check-in in [start,end)
   * - all: all earning bookings
   */
  earnings_mode: 'attr' | 'checkin_window' | 'all';
};

function parsePeriodId(raw?: string): HostAnalyticsPeriodId {
  const id = (raw?.trim() || 'this_month') as HostAnalyticsPeriodId;
  if (!(HOST_ANALYTICS_PERIODS as readonly string[]).includes(id)) {
    throw new BadRequestException(
      `Invalid period. Supported: ${HOST_ANALYTICS_PERIODS.join(', ')}`,
    );
  }
  return id;
}

function resolvePeriod(
  id: HostAnalyticsPeriodId,
  dash: DashboardNow,
): ResolvedPeriod {
  switch (id) {
    case 'this_month':
      return {
        id,
        start: dash.thisMonthStart,
        end_exclusive: dash.thisMonthEndExclusive,
        period_days: dash.daysInThisMonth,
        earnings_mode: 'attr',
      };
    case 'previous_month':
      return {
        id,
        start: dash.previousMonthStart,
        end_exclusive: dash.previousMonthEndExclusive,
        period_days: dash.daysInPreviousMonth,
        earnings_mode: 'attr',
      };
    case 'next_30d':
      return {
        id,
        start: dash.today,
        end_exclusive: dash.in30EndExclusive,
        period_days: 30,
        earnings_mode: 'checkin_window',
      };
    case 'all_time':
      return {
        id,
        start: '1970-01-01',
        end_exclusive: '9999-01-01',
        period_days: null,
        earnings_mode: 'all',
      };
    default: {
      const _exhaustive: never = id;
      throw new BadRequestException(`Unsupported period: ${_exhaustive}`);
    }
  }
}

type Acc = {
  listing: Pick<
    StaysListing,
    'id' | 'title' | 'city' | 'status' | 'avg_rating' | 'review_count'
  >;
  bookings: {
    total: number;
    payment_pending: number;
    upcoming: number;
    current: number;
    completed: number;
    cancelled: number;
  };
  booked_in_period: number;
  gross: number;
  net: number;
  fees: number;
  upcoming_30d: number;
  checkins_today: number;
  checkouts_today: number;
  next_checkin_date: string | null;
  upcoming_bookings: number;
  currently_staying: number;
  payout_pending: number;
  payout_paid_out: number;
};

/**
 * H10 host property performance analytics (H7 locked contract).
 *
 * Host scope = JWT userId → listings.host_user_id only (never client hostId).
 * Money rules match H3. Occupancy basis is BOOKED_NIGHTS_OVER_PERIOD_DAYS_V1
 * (not host BOOKED_OVER_CAPACITY_V1). Blocks/ICAL busy are ignored.
 *
 * Limitation: in-memory aggregation over host listings/bookings (same H3 pattern).
 */
@Injectable()
export class HostAnalyticsService {
  constructor(
    @InjectRepository(StaysBooking)
    private readonly bookingRepo: Repository<StaysBooking>,
    @InjectRepository(StaysListing)
    private readonly listingRepo: Repository<StaysListing>,
    @InjectRepository(StaysLedgerEntry)
    private readonly ledgerRepo: Repository<StaysLedgerEntry>,
    @InjectRepository(StaysExternalCalendar)
    private readonly calendarRepo: Repository<StaysExternalCalendar>,
    private readonly lifecycleService: BookingLifecycleService,
    private readonly hostListingsService: HostListingsService,
  ) {}

  async getHostAnalytics(
    hostUserId: string,
    periodRaw?: string,
    at?: Date,
  ): Promise<HostAnalyticsResponseDto> {
    const periodId = parsePeriodId(periodRaw);
    const dash = getDashboardNow(at ?? new Date());
    const period = resolvePeriod(periodId, dash);

    const listings = await this.listingRepo.find({
      where: { host_user_id: hostUserId },
      select: ['id', 'title', 'city', 'status', 'avg_rating', 'review_count'],
      order: { created_at: 'DESC' },
    });
    const listingIds = listings.map((l) => l.id);

    const empty: HostAnalyticsResponseDto = {
      as_of: dash.asOfIso,
      timezone: dash.timezone,
      currency: 'MAD',
      period: {
        id: period.id,
        start: period.start,
        end_exclusive: period.end_exclusive,
      },
      eligible_booking_statuses: [...EARNING_STATUSES],
      properties: [],
    };

    if (listingIds.length === 0) {
      return empty;
    }

    const [bookings, calendars, summaries, payoutByListing] = await Promise.all(
      [
        this.bookingRepo.find({
          where: { listing_id: In(listingIds) },
        }),
        this.calendarRepo.find({
          where: { listing_id: In(listingIds) },
          select: ['listing_id', 'status'],
        }),
        this.hostListingsService.getHostListings(hostUserId),
        this.sumPayoutsByListing(hostUserId),
      ],
    );

    const accById = new Map<string, Acc>();
    for (const listing of listings) {
      const payout = payoutByListing.get(listing.id) ?? {
        pending: 0,
        paid_out: 0,
      };
      accById.set(listing.id, {
        listing,
        bookings: {
          total: 0,
          payment_pending: 0,
          upcoming: 0,
          current: 0,
          completed: 0,
          cancelled: 0,
        },
        booked_in_period: 0,
        gross: 0,
        net: 0,
        fees: 0,
        upcoming_30d: 0,
        checkins_today: 0,
        checkouts_today: 0,
        next_checkin_date: null,
        upcoming_bookings: 0,
        currently_staying: 0,
        payout_pending: payout.pending,
        payout_paid_out: payout.paid_out,
      });
    }

    for (const b of bookings) {
      const acc = accById.get(b.listing_id);
      if (!acc) continue; // host isolation — foreign listing ids never present

      const checkin = toDateOnlyYmd(b.checkin_date);
      const checkout = toDateOnlyYmd(b.checkout_date);

      acc.bookings.total += 1;
      if (PENDING_STATUSES.includes(b.status)) {
        acc.bookings.payment_pending += 1;
      }
      if (b.status === 'COMPLETED') {
        acc.bookings.completed += 1;
      }
      if (
        b.status === 'CANCELLED_BY_GUEST' ||
        b.status === 'CANCELLED_BY_HOST' ||
        b.status === 'EXPIRED'
      ) {
        acc.bookings.cancelled += 1;
      }

      const life = this.lifecycleService.computeLifecycle(b, {
        now: dash.nowJs,
      });
      if (life === 'UPCOMING') {
        acc.bookings.upcoming += 1;
        acc.upcoming_bookings += 1;
        if (
          !acc.next_checkin_date ||
          ymdCompare(checkin, acc.next_checkin_date) < 0
        ) {
          acc.next_checkin_date = checkin;
        }
      }

      const stayStatuses =
        b.status === 'CONFIRMED' || b.status === 'CHECKED_IN';
      const checkoutStatuses = stayStatuses || b.status === 'COMPLETED';

      if (
        stayStatuses &&
        ymdCompare(checkin, dash.today) <= 0 &&
        ymdCompare(checkout, dash.today) > 0
      ) {
        acc.bookings.current += 1;
        acc.currently_staying += 1;
      }

      if (stayStatuses && checkin === dash.today) {
        acc.checkins_today += 1;
      }
      if (checkoutStatuses && checkout === dash.today) {
        acc.checkouts_today += 1;
      }

      // Upcoming 30d net (always H3 check-in window, independent of selected period)
      if (
        FUTURE_EARNING_STATUSES.includes(b.status) &&
        ymdInHalfOpen(checkin, dash.today, dash.in30EndExclusive)
      ) {
        acc.upcoming_30d += hostPayout(b);
      }

      if (!EARNING_STATUSES.includes(b.status)) continue;

      const inEarnings = this.bookingInPeriodEarnings(b, period, checkin);
      if (inEarnings) {
        acc.gross += grossPaid(b);
        acc.net += hostPayout(b);
        acc.fees += platformFees(b);
      }

      if (period.earnings_mode === 'all') {
        acc.booked_in_period += stayNights(checkin, checkout);
      } else {
        acc.booked_in_period += bookedNightsInHalfOpenRange(
          checkin,
          checkout,
          period.start,
          period.end_exclusive,
        );
      }
    }

    const summaryById = new Map(summaries.map((s) => [s.id, s] as const));
    const calendarByListing = this.calendarStatusByListing(calendars);

    const currency = bookings.find((b) => b.currency)?.currency ?? 'MAD';

    const properties: HostAnalyticsPropertyDto[] = listings.map((listing) => {
      const acc = accById.get(listing.id)!;
      const summary = summaryById.get(listing.id);
      const cal = calendarByListing.get(listing.id) ?? 'NONE';
      const completionPct = summary?.completion_percentage ?? 0;
      const photosComplete = Boolean(
        summary?.completion_flags?.photos_complete,
      );
      const missing = (summary?.missing ?? []).map(
        (m: { key?: string; code?: string; label: string }) => ({
          code: m.code ?? m.key ?? 'missing',
          label: m.label,
        }),
      );
      const attention: string[] = [];
      if (cal === 'ERROR') attention.push('CALENDAR_ERROR');
      if (listing.status === 'LIVE' && missing.length > 0) {
        attention.push('INCOMPLETE_LIVE');
      }
      if (listing.status === 'PAUSED') attention.push('PAUSED');
      if (listing.status === 'DRAFT') attention.push('DRAFT');
      if (listing.status === 'REJECTED') attention.push('REJECTED');
      if (acc.bookings.payment_pending > 0) {
        attention.push('PAYMENT_PENDING');
      }

      const occupancyValue =
        period.period_days != null && period.period_days > 0
          ? Math.min(
              100,
              Math.round((acc.booked_in_period / period.period_days) * 1000) /
                10,
            )
          : null;

      const avgRating =
        listing.avg_rating != null &&
        Number.isFinite(Number(listing.avg_rating))
          ? Number(listing.avg_rating)
          : null;
      const reviewCount = listing.review_count ?? 0;

      return {
        listing_id: listing.id,
        title: listing.title ?? '',
        city: listing.city ?? '',
        status: listing.status,
        bookings: { ...acc.bookings },
        nights: { booked_in_period: acc.booked_in_period },
        earnings: {
          gross_revenue: round2(acc.gross),
          net_host_earnings: round2(acc.net),
          platform_fees: round2(acc.fees),
          upcoming_revenue_30d: round2(acc.upcoming_30d),
        },
        occupancy: {
          value: occupancyValue,
          basis: HOST_ANALYTICS_OCCUPANCY_BASIS,
        },
        reviews: {
          avg_rating: avgRating,
          total_reviews: reviewCount,
        },
        operations: {
          checkins_today: acc.checkins_today,
          checkouts_today: acc.checkouts_today,
          next_checkin_date: acc.next_checkin_date,
          upcoming_bookings: acc.upcoming_bookings,
          currently_staying: acc.currently_staying,
        },
        payouts: {
          pending: round2(acc.payout_pending),
          paid_out: round2(acc.payout_paid_out),
        },
        health: {
          completion_percentage: completionPct,
          photos_complete: photosComplete,
          calendar_status: cal,
          missing,
          attention,
        },
      };
    });

    return {
      as_of: dash.asOfIso,
      timezone: dash.timezone,
      currency,
      period: {
        id: period.id,
        start: period.start,
        end_exclusive: period.end_exclusive,
      },
      eligible_booking_statuses: [...EARNING_STATUSES],
      properties,
    };
  }

  private bookingInPeriodEarnings(
    b: StaysBooking,
    period: ResolvedPeriod,
    checkinYmd: string,
  ): boolean {
    if (period.earnings_mode === 'all') {
      return EARNING_STATUSES.includes(b.status);
    }
    if (period.earnings_mode === 'checkin_window') {
      return (
        FUTURE_EARNING_STATUSES.includes(b.status) &&
        ymdInHalfOpen(checkinYmd, period.start, period.end_exclusive)
      );
    }
    // attr
    if (!EARNING_STATUSES.includes(b.status)) return false;
    const attrYmd = toCasablancaYmd(b.confirmed_at ?? b.created_at);
    return ymdInHalfOpen(attrYmd, period.start, period.end_exclusive);
  }

  private calendarStatusByListing(
    calendars: Array<{ listing_id: string; status: string }>,
  ): Map<string, string> {
    const byListing = new Map<string, Set<string>>();
    for (const c of calendars) {
      const set = byListing.get(c.listing_id) ?? new Set<string>();
      set.add(c.status);
      byListing.set(c.listing_id, set);
    }
    const out = new Map<string, string>();
    for (const [listingId, statuses] of byListing) {
      if (statuses.has('ERROR')) out.set(listingId, 'ERROR');
      else if (statuses.size > 1) out.set(listingId, 'MIXED');
      else out.set(listingId, [...statuses][0] ?? 'NONE');
    }
    return out;
  }

  private async sumPayoutsByListing(
    hostUserId: string,
  ): Promise<Map<string, { pending: number; paid_out: number }>> {
    const rows = await this.ledgerRepo
      .createQueryBuilder('e')
      .innerJoinAndSelect('e.booking', 'b')
      .innerJoin('b.listing', 'l')
      .where('l.host_user_id = :hostUserId', { hostUserId })
      .andWhere('e.type = :type', { type: 'HOST_PAYOUT' })
      .andWhere('e.status IN (:...statuses)', {
        statuses: ['PENDING', 'SETTLED'],
      })
      .getMany();

    const map = new Map<string, { pending: number; paid_out: number }>();
    for (const row of rows) {
      const listingId = (row.booking as StaysBooking | undefined)?.listing_id;
      if (!listingId) continue;
      const cur = map.get(listingId) ?? { pending: 0, paid_out: 0 };
      const amt = Number(row.amount);
      if (row.status === 'PENDING') cur.pending += amt;
      if (row.status === 'SETTLED') cur.paid_out += amt;
      map.set(listingId, cur);
    }
    return map;
  }
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, SelectQueryBuilder } from 'typeorm';
import { StaysBooking } from '../entities/stays-booking.entity';
import { StaysListing } from '../entities/stays-listing.entity';
import { getDashboardNow } from './host-dashboard-timezone';
import {
  encodeHostListCursor,
  decodeHostListCursor,
} from '../utils/host-list-cursor.util';
import {
  applyHostBookingFilterSql,
  escapeIlikePattern,
  guestDisplayNameSql,
  opsUrgencyRankSql,
} from '../utils/host-bookings-list-sql.util';
import type {
  HostBookingFilterParam,
  HostBookingSortParam,
  HostBookingsListQueryDto,
  HostBookingsCountsQueryDto,
} from '../dto/host-bookings-list.dto';

export type HostBookingListItem = Record<string, unknown>;

@Injectable()
export class HostBookingsListService {
  constructor(
    @InjectRepository(StaysBooking)
    private readonly bookingRepo: Repository<StaysBooking>,
  ) {}

  async listHostBookingsPage(
    hostUserId: string,
    query: HostBookingsListQueryDto,
    mapItem: (booking: StaysBooking) => HostBookingListItem,
  ) {
    const limit = Math.min(Math.max(query.limit ?? 20, 1), 50);
    const filter: HostBookingFilterParam = query.filter ?? 'all';
    const sort: HostBookingSortParam = query.sort ?? 'ops';
    const search = (query.search ?? '').trim();
    const listingId = query.listing_id ?? '';
    const now = getDashboardNow();
    const today = now.today;
    const tomorrow = now.tomorrow;

    const ctx = {
      kind: 'bookings' as const,
      hostId: hostUserId,
      sort,
      filter,
      search: search.toLowerCase(),
      listingId,
      status: '',
    };

    const cursorPayload = decodeHostListCursor(query.cursor, ctx);

    const qb = this.baseQb(hostUserId);
    this.applyScope(qb, { listingId, search, today, tomorrow, filter });

    const rankSql = opsUrgencyRankSql('b');
    const guestSql = guestDisplayNameSql('b');
    qb.addSelect(rankSql, 'ops_rank');
    // Lowercased guest name for ORDER BY / keyset (matches client localeCompare base)
    qb.addSelect(`LOWER(COALESCE(${guestSql}, ''))`, 'guest_sort_name');

    this.applyOrder(qb, sort);
    this.applyKeyset(qb, sort, cursorPayload, rankSql);

    qb.take(limit + 1);

    const { entities, raw } = await qb.getRawAndEntities();
    const hasNext = entities.length > limit;
    const pageEntities = hasNext ? entities.slice(0, limit) : entities;
    const pageRaw = hasNext ? raw.slice(0, limit) : raw;

    const items = pageEntities.map(mapItem);

    let nextCursor: string | null = null;
    if (hasNext && pageEntities.length > 0) {
      const last = pageEntities[pageEntities.length - 1];
      const lastRaw = pageRaw[pageRaw.length - 1] as Record<string, unknown>;
      const keys = this.cursorKeys(sort, last, lastRaw);
      nextCursor = encodeHostListCursor(ctx, keys, last.id);
    }

    return {
      items,
      pagination: {
        limit,
        has_next: hasNext,
        next_cursor: nextCursor,
      },
    };
  }

  private rawField(raw: Record<string, unknown>, name: string): unknown {
    if (name in raw) return raw[name];
    const hit = Object.keys(raw).find(
      (k) => k === name || k.endsWith('_' + name),
    );
    return hit ? raw[hit] : undefined;
  }

  async getHostBookingsCounts(
    hostUserId: string,
    query: HostBookingsCountsQueryDto,
  ) {
    const search = (query.search ?? '').trim();
    const listingId = query.listing_id ?? '';
    const now = getDashboardNow();
    const today = now.today;
    const tomorrow = now.tomorrow;

    const filters: HostBookingFilterParam[] = [
      'all',
      'today',
      'checkin_today',
      'checkout_today',
      'upcoming',
      'current',
      'awaiting_payment',
      'completed',
      'cancelled',
    ];

    const counts: Record<string, number> = {};
    for (const filter of filters) {
      const qb = this.bookingRepo
        .createQueryBuilder('b')
        .innerJoin('b.listing', 'listing')
        .where('listing.host_user_id = :hostUserId', { hostUserId });
      this.applyScope(qb, {
        listingId,
        search,
        today,
        tomorrow,
        filter,
      });
      counts[filter] = await qb.getCount();
    }
    return counts;
  }

  private baseQb(hostUserId: string): SelectQueryBuilder<StaysBooking> {
    return this.bookingRepo
      .createQueryBuilder('b')
      .innerJoinAndSelect('b.listing', 'listing')
      .leftJoinAndSelect('b.occupants', 'occupants')
      .where('listing.host_user_id = :hostUserId', { hostUserId });
  }

  private applyScope(
    qb: SelectQueryBuilder<StaysBooking>,
    opts: {
      listingId: string;
      search: string;
      today: string;
      tomorrow: string;
      filter: HostBookingFilterParam;
    },
  ) {
    qb.setParameter('today', opts.today);
    qb.setParameter('tomorrow', opts.tomorrow);

    if (opts.listingId) {
      qb.andWhere('b.listing_id = :listingId', { listingId: opts.listingId });
    }

    const filterSql = applyHostBookingFilterSql(opts.filter, 'b');
    if (filterSql) {
      qb.andWhere(filterSql);
    }

    if (opts.search) {
      const pattern = `%${escapeIlikePattern(opts.search.toLowerCase())}%`;
      const guestSql = guestDisplayNameSql('b');
      qb.andWhere(
        `(
          LOWER(COALESCE(${guestSql}, '')) LIKE :searchPattern ESCAPE '\\'
          OR LOWER(COALESCE(listing.title, '')) LIKE :searchPattern ESCAPE '\\'
          OR LOWER(b.id::text) LIKE :searchPattern ESCAPE '\\'
          OR LOWER(COALESCE(b.booking_reference, '')) LIKE :searchPattern ESCAPE '\\'
          OR LOWER(b.listing_id::text) LIKE :searchPattern ESCAPE '\\'
        )`,
        { searchPattern: pattern },
      );
    }
  }

  private applyOrder(
    qb: SelectQueryBuilder<StaysBooking>,
    sort: HostBookingSortParam,
  ) {
    if (sort === 'ops') {
      // Sort by selected alias (see addSelect ops_rank)
      qb.orderBy('ops_rank', 'ASC');
      qb.addOrderBy('b.checkin_date', 'ASC');
      qb.addOrderBy('b.id', 'ASC');
      return;
    }
    if (sort === 'checkin') {
      qb.orderBy('b.checkin_date', 'ASC');
      qb.addOrderBy('b.id', 'ASC');
      return;
    }
    if (sort === 'checkout') {
      qb.orderBy('b.checkout_date', 'ASC');
      qb.addOrderBy('b.id', 'ASC');
      return;
    }
    if (sort === 'amount') {
      // total_subtotal NOT NULL in schema
      qb.orderBy('b.total_subtotal', 'ASC');
      qb.addOrderBy('b.id', 'ASC');
      return;
    }
    if (sort === 'guest') {
      // Client uses (guest_name ?? "").trim() ASC — empty/null first
      qb.orderBy('guest_sort_name', 'ASC');
      qb.addOrderBy('b.id', 'ASC');
    }
  }

  private applyKeyset(
    qb: SelectQueryBuilder<StaysBooking>,
    sort: HostBookingSortParam,
    cursor: ReturnType<typeof decodeHostListCursor>,
    rankSql: string,
  ) {
    if (!cursor) return;
    const k = cursor.keys;
    const id = cursor.id;

    if (sort === 'ops') {
      qb.andWhere(
        `(
          (${rankSql}) > :cRank
          OR ((${rankSql}) = :cRank AND b.checkin_date > CAST(:cCheckin AS date))
          OR ((${rankSql}) = :cRank AND b.checkin_date = CAST(:cCheckin AS date) AND b.id > :cId)
        )`,
        {
          cRank: Number(k.ops_rank),
          cCheckin: String(k.checkin_date),
          cId: id,
        },
      );
      return;
    }
    if (sort === 'checkin') {
      qb.andWhere(
        `(
          b.checkin_date > CAST(:cCheckin AS date)
          OR (b.checkin_date = CAST(:cCheckin AS date) AND b.id > :cId)
        )`,
        { cCheckin: String(k.checkin_date), cId: id },
      );
      return;
    }
    if (sort === 'checkout') {
      qb.andWhere(
        `(
          b.checkout_date > CAST(:cCheckout AS date)
          OR (b.checkout_date = CAST(:cCheckout AS date) AND b.id > :cId)
        )`,
        { cCheckout: String(k.checkout_date), cId: id },
      );
      return;
    }
    if (sort === 'amount') {
      qb.andWhere(
        `(
          b.total_subtotal > :cAmount
          OR (b.total_subtotal = :cAmount AND b.id > :cId)
        )`,
        { cAmount: Number(k.total_subtotal), cId: id },
      );
      return;
    }
    if (sort === 'guest') {
      const guestSql = guestDisplayNameSql('b');
      qb.andWhere(
        `(
          LOWER(COALESCE(${guestSql}, '')) > :cGuest
          OR (LOWER(COALESCE(${guestSql}, '')) = :cGuest AND b.id > :cId)
        )`,
        {
          cGuest: String(k.guest_sort_name ?? '').toLowerCase(),
          cId: id,
        },
      );
    }
  }

  private cursorKeys(
    sort: HostBookingSortParam,
    booking: StaysBooking,
    raw: Record<string, unknown>,
  ): Record<string, string | number | null> {
    const ymd = (v: Date | string) => {
      if (typeof v === 'string') return v.slice(0, 10);
      return v.toISOString().slice(0, 10);
    };
    if (sort === 'ops') {
      return {
        ops_rank: Number(this.rawField(raw, 'ops_rank') ?? 8),
        checkin_date: ymd(booking.checkin_date),
      };
    }
    if (sort === 'checkin') {
      return { checkin_date: ymd(booking.checkin_date) };
    }
    if (sort === 'checkout') {
      return { checkout_date: ymd(booking.checkout_date) };
    }
    if (sort === 'amount') {
      return { total_subtotal: Number(booking.total_subtotal) };
    }
    return {
      guest_sort_name: String(
        this.rawField(raw, 'guest_sort_name') ?? '',
      ).toLowerCase(),
    };
  }
}

/** Slim listing embed for host booking list (no media / check_in_contact). */
export function toSlimHostBookingListing(listing: StaysListing | undefined) {
  if (!listing) return null;
  return {
    id: listing.id,
    title: listing.title,
    city: listing.city,
    checkin_time: listing.checkin_time ?? null,
    checkout_time: listing.checkout_time ?? null,
    address: null,
    check_in_instructions: null,
    check_in_contact: null,
    media: [] as unknown[],
  };
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, In } from 'typeorm';
import { StaysBooking } from '../entities/stays-booking.entity';
import { StaysListing } from '../entities/stays-listing.entity';
import { StaysLedgerEntry } from '../entities/stays-ledger-entry.entity';
import { StaysExternalCalendar } from '../entities/stays-external-calendar.entity';
import { StaysReviewsService } from './stays-reviews.service';
import { BookingLifecycleService } from './booking-lifecycle.service';
import { HostListingsService } from './host-listings.service';
import {
  getStaysPaymentProvider,
  isHostPayoutEnabled,
  isMockPaymentProvider,
} from '../payments/payment-provider.config';
import { resolveNexaStage } from '../../../common/security/cors-origins';
import {
  bookedNightsInCalendarMonth,
  getDashboardNow,
  toCasablancaYmd,
  toDateOnlyYmd,
  ymdCompare,
  ymdInHalfOpen,
} from './host-dashboard-timezone';

const EARNING_STATUSES: StaysBooking['status'][] = [
  'CONFIRMED',
  'CHECKED_IN',
  'COMPLETED',
];

const PENDING_STATUSES: StaysBooking['status'][] = [
  'INITIATED',
  'PAYMENT_PENDING',
];

const ACTIVE_STATUSES: StaysBooking['status'][] = ['CONFIRMED', 'CHECKED_IN'];

const FUTURE_EARNING_STATUSES: StaysBooking['status'][] = [
  'CONFIRMED',
  'CHECKED_IN',
];

function startOfLocalDay(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

function parseDateOnly(value: Date | string): Date {
  if (typeof value === 'string') {
    const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(value);
    if (m) {
      return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
    }
  }
  const d = new Date(value);
  return startOfLocalDay(d);
}

function toIsoDate(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function addDays(d: Date, days: number): Date {
  const next = new Date(d);
  next.setDate(next.getDate() + days);
  return next;
}

function daysInMonth(year: number, monthIndex: number): number {
  return new Date(year, monthIndex + 1, 0).getDate();
}

/** Nights of [checkin, checkout) that fall inside calendar month (local). */
function bookedNightsInMonth(
  checkin: Date,
  checkout: Date,
  year: number,
  monthIndex: number,
): number {
  const monthStart = new Date(year, monthIndex, 1);
  const monthEnd = new Date(year, monthIndex + 1, 1);
  const start = Math.max(checkin.getTime(), monthStart.getTime());
  const end = Math.min(checkout.getTime(), monthEnd.getTime());
  if (end <= start) return 0;
  return Math.round((end - start) / 86_400_000);
}

function momPct(current: number, previous: number): number | null {
  if (previous <= 0) return null;
  return Math.round(((current - previous) / previous) * 1000) / 10;
}

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}

@Injectable()
export class HostDashboardService {
  constructor(
    @InjectRepository(StaysBooking)
    private readonly bookingRepo: Repository<StaysBooking>,
    @InjectRepository(StaysListing)
    private readonly listingRepo: Repository<StaysListing>,
    @InjectRepository(StaysLedgerEntry)
    private readonly ledgerRepo: Repository<StaysLedgerEntry>,
    @InjectRepository(StaysExternalCalendar)
    private readonly calendarRepo: Repository<StaysExternalCalendar>,
    private readonly staysReviewsService: StaysReviewsService,
    private readonly lifecycleService: BookingLifecycleService,
    private readonly hostListingsService: HostListingsService,
  ) {}

  /**
   * H3 aggregated host dashboard — Casablanca TZ, gross/net/fees split,
   * mock payout contract. Host scope = JWT sub only (no client hostId).
   *
   * Limitation: in-memory aggregation over host bookings (same as getHostStats).
   * SQL rollups deferred if volume requires it later.
   */
  async getHostDashboard(hostUserId: string, at?: Date) {
    const dash = getDashboardNow(at ?? new Date());
    const listings = await this.listingRepo.find({
      where: { host_user_id: hostUserId },
      select: ['id', 'status'],
    });
    const listingIds = listings.map((l) => l.id);
    const liveListings = listings.filter((l) => l.status === 'LIVE').length;

    let bookings: StaysBooking[] = [];
    if (listingIds.length > 0) {
      bookings = await this.bookingRepo.find({
        where: { listing_id: In(listingIds) },
        relations: ['occupants'],
      });
    }

    const hostPayout = (b: StaysBooking) => {
      if (b.payout_amount != null) return Number(b.payout_amount);
      return Math.max(0, Number(b.total_subtotal) - Number(b.host_fee));
    };
    const grossPaid = (b: StaysBooking) => Number(b.total_paid ?? 0);
    const platformFees = (b: StaysBooking) =>
      Number(b.guest_fee ?? 0) + Number(b.host_fee ?? 0);

    let grossAll = 0;
    let netAll = 0;
    let feesAll = 0;
    let grossThis = 0;
    let netThis = 0;
    let feesThis = 0;
    let grossPrev = 0;
    let netPrev = 0;
    let feesPrev = 0;
    let upcomingRevenue30d = 0;
    let bookedNightsThisMonth = 0;
    let bookedNightsPrevMonth = 0;

    for (const b of bookings) {
      if (!EARNING_STATUSES.includes(b.status)) continue;
      const payout = hostPayout(b);
      const gross = grossPaid(b);
      const fees = platformFees(b);
      grossAll += gross;
      netAll += payout;
      feesAll += fees;

      // Month attribution: confirmed_at ?? created_at in Africa/Casablanca
      const attrYmd = toCasablancaYmd(b.confirmed_at ?? b.created_at);
      if (
        ymdInHalfOpen(attrYmd, dash.thisMonthStart, dash.thisMonthEndExclusive)
      ) {
        grossThis += gross;
        netThis += payout;
        feesThis += fees;
      }
      if (
        ymdInHalfOpen(
          attrYmd,
          dash.previousMonthStart,
          dash.previousMonthEndExclusive,
        )
      ) {
        grossPrev += gross;
        netPrev += payout;
        feesPrev += fees;
      }

      const checkin = toDateOnlyYmd(b.checkin_date);
      const checkout = toDateOnlyYmd(b.checkout_date);
      bookedNightsThisMonth += bookedNightsInCalendarMonth(
        checkin,
        checkout,
        dash.year,
        dash.month,
      );
      bookedNightsPrevMonth += bookedNightsInCalendarMonth(
        checkin,
        checkout,
        dash.previousYear,
        dash.previousMonth,
      );
    }

    // upcoming_revenue_30d = net payout of FUTURE earning bookings with
    // check-in in [today, today+30) Casablanca days (CONFIRMED | CHECKED_IN).
    for (const b of bookings) {
      if (!FUTURE_EARNING_STATUSES.includes(b.status)) continue;
      const checkin = toDateOnlyYmd(b.checkin_date);
      if (ymdInHalfOpen(checkin, dash.today, dash.in30EndExclusive)) {
        upcomingRevenue30d += hostPayout(b);
      }
    }

    /**
     * Occupancy (v1): booked nights in month /
     * (days_in_month × max(live_listings, 1)).
     * Ignores availability blocks — BOOKED_OVER_CAPACITY_V1.
     */
    const capacity = dash.daysInThisMonth * Math.max(liveListings, 1);
    const occupancyPctThisMonth =
      capacity > 0
        ? Math.min(
            100,
            Math.round((bookedNightsThisMonth / capacity) * 1000) / 10,
          )
        : 0;

    let checkinsToday = 0;
    let checkoutsToday = 0;
    let checkoutsTomorrow = 0;
    let currentlyStaying = 0;
    let newBookingsToday = 0;
    let awaitingGuestPayment = 0;
    let upcomingCheckins = 0;
    let nextUpcoming: StaysBooking | null = null;

    for (const b of bookings) {
      const checkin = toDateOnlyYmd(b.checkin_date);
      const checkout = toDateOnlyYmd(b.checkout_date);
      const createdYmd = toCasablancaYmd(b.created_at);

      if (createdYmd === dash.today) {
        newBookingsToday += 1;
      }

      const life = this.lifecycleService.computeLifecycle(b, {
        now: dash.nowJs,
      });
      if (life === 'PENDING_PAYMENT') {
        awaitingGuestPayment += 1;
      }
      if (life === 'UPCOMING') {
        upcomingCheckins += 1;
        if (
          !nextUpcoming ||
          ymdCompare(checkin, toDateOnlyYmd(nextUpcoming.checkin_date)) < 0
        ) {
          nextUpcoming = b;
        }
      }

      const stayStatuses =
        b.status === 'CONFIRMED' || b.status === 'CHECKED_IN';
      const checkoutStatuses = stayStatuses || b.status === 'COMPLETED';

      if (stayStatuses && checkin === dash.today) {
        checkinsToday += 1;
      }
      if (checkoutStatuses && checkout === dash.today) {
        checkoutsToday += 1;
      }
      if (checkoutStatuses && checkout === dash.tomorrow) {
        checkoutsTomorrow += 1;
      }
      // Currently staying: calendar overlap with Casablanca today
      if (
        stayStatuses &&
        ymdCompare(checkin, dash.today) <= 0 &&
        ymdCompare(checkout, dash.today) > 0
      ) {
        currentlyStaying += 1;
      }
    }

    const { pending, paidOut } = await this.sumHostPayoutLedger(
      hostUserId,
      listingIds,
    );

    let calendarStatus = {
      healthy: true,
      listings_needing_attention: 0,
    };
    if (listingIds.length > 0) {
      const calendars = await this.calendarRepo.find({
        where: { listing_id: In(listingIds) },
        select: ['id', 'listing_id', 'status'],
      });
      const badListings = new Set(
        calendars.filter((c) => c.status === 'ERROR').map((c) => c.listing_id),
      );
      calendarStatus = {
        healthy: badListings.size === 0,
        listings_needing_attention: badListings.size,
      };
    }

    const listingHealth = await this.buildListingHealth(
      hostUserId,
      listingIds,
      liveListings,
    );

    const reviewsPayload = await this.staysReviewsService.listHostReviews(
      hostUserId,
      1,
      1,
    );

    const currency = bookings.find((b) => b.currency)?.currency ?? 'MAD';
    const payoutMeta = this.buildPayoutMeta();

    return {
      as_of: dash.asOfIso,
      timezone: dash.timezone,
      currency,
      today: {
        checkins_today: checkinsToday,
        checkouts_today: checkoutsToday,
        checkouts_tomorrow: checkoutsTomorrow,
        currently_staying: currentlyStaying,
        new_bookings_today: newBookingsToday,
        awaiting_guest_payment: awaitingGuestPayment,
      },
      earnings: {
        gross_revenue_all_time: round2(grossAll),
        net_host_earnings_all_time: round2(netAll),
        platform_fees_all_time: round2(feesAll),
        this_month: {
          gross_revenue: round2(grossThis),
          net_host_earnings: round2(netThis),
          platform_fees: round2(feesThis),
          mom_pct: momPct(netThis, netPrev),
        },
        previous_month: {
          gross_revenue: round2(grossPrev),
          net_host_earnings: round2(netPrev),
          platform_fees: round2(feesPrev),
        },
        upcoming_revenue_30d: round2(upcomingRevenue30d),
      },
      payouts: {
        provider: payoutMeta.provider,
        mode: payoutMeta.mode,
        host_payout_enabled: payoutMeta.host_payout_enabled,
        pending,
        available: 0,
        paid_out: paidOut,
        currency,
        disclaimer: payoutMeta.disclaimer,
      },
      operations: {
        upcoming_checkins: upcomingCheckins,
        next_checkin_date: nextUpcoming
          ? toDateOnlyYmd(nextUpcoming.checkin_date)
          : null,
        next_guest_name: nextUpcoming
          ? this.resolveGuestDisplayName(nextUpcoming)
          : null,
      },
      inventory: {
        live_listings: liveListings,
        pending_listings: listings.filter(
          (l) => l.status === 'SUBMITTED' || l.status === 'DRAFT',
        ).length,
        total_listings: listings.length,
        occupancy_pct_this_month: occupancyPctThisMonth,
        occupancy_basis: 'BOOKED_OVER_CAPACITY_V1' as const,
      },
      reviews: {
        avg_rating: reviewsPayload.summary.overall_avg_rating,
        total_reviews: reviewsPayload.summary.total_count,
      },
      messaging: {
        unread_count: null,
        status: 'unavailable' as const,
      },
      calendar_status: calendarStatus,
      listing_health: listingHealth,
      bookings_summary: {
        total: bookings.length,
        pending: bookings.filter((b) => PENDING_STATUSES.includes(b.status))
          .length,
        active: bookings.filter((b) => ACTIVE_STATUSES.includes(b.status))
          .length,
        completed: bookings.filter((b) => b.status === 'COMPLETED').length,
        cancelled: bookings.filter(
          (b) =>
            b.status === 'CANCELLED_BY_GUEST' ||
            b.status === 'CANCELLED_BY_HOST' ||
            b.status === 'EXPIRED',
        ).length,
      },
    };
  }

  private buildPayoutMeta(): {
    provider: string;
    mode: string;
    disclaimer: string;
    host_payout_enabled: boolean;
  } {
    const provider = getStaysPaymentProvider();
    const stage = resolveNexaStage();
    const mock = isMockPaymentProvider();
    const hostPayoutEnabled = !mock && isHostPayoutEnabled();
    const mode = mock
      ? stage === 'dogfood'
        ? 'dogfood'
        : stage === 'staging'
          ? 'staging_mock'
          : 'mock'
      : stage;
    const disclaimer = mock
      ? 'Test environment — payouts are simulated. No real money is transferred.'
      : hostPayoutEnabled
        ? 'Host payout settlement is enabled for CMI. Pending amounts settle via the configured payout rails.'
        : 'Host payout settlement is not enabled (set STAYS_HOST_PAYOUT_ENABLED=true with CMI). Pending amounts reflect ledger HOST_PAYOUT entries only.';
    return {
      provider,
      mode,
      disclaimer,
      host_payout_enabled: hostPayoutEnabled,
    };
  }

  private async sumHostPayoutLedger(
    hostUserId: string,
    listingIds: string[],
  ): Promise<{ pending: number; paidOut: number }> {
    if (listingIds.length === 0) {
      return { pending: 0, paidOut: 0 };
    }
    const rows = await this.ledgerRepo
      .createQueryBuilder('e')
      .innerJoin('e.booking', 'b')
      .innerJoin('b.listing', 'l')
      .where('l.host_user_id = :hostUserId', { hostUserId })
      .andWhere('e.type = :type', { type: 'HOST_PAYOUT' })
      .andWhere('e.status IN (:...statuses)', {
        statuses: ['PENDING', 'SETTLED'],
      })
      .getMany();

    let pending = 0;
    let paidOut = 0;
    for (const row of rows) {
      const amt = Number(row.amount);
      if (row.status === 'PENDING') pending += amt;
      if (row.status === 'SETTLED') paidOut += amt;
    }
    return { pending: round2(pending), paidOut: round2(paidOut) };
  }

  async getHostStats(hostUserId: string) {
    const listings = await this.listingRepo.find({
      where: { host_user_id: hostUserId },
      select: ['id', 'status'],
    });
    const listingIds = listings.map((l) => l.id);
    const liveListings = listings.filter((l) => l.status === 'LIVE').length;

    let bookings: StaysBooking[] = [];
    if (listingIds.length > 0) {
      bookings = await this.bookingRepo.find({
        where: { listing_id: In(listingIds) },
        relations: ['occupants'],
      });
    }

    const hostPayout = (b: StaysBooking) => {
      if (b.payout_amount != null) return Number(b.payout_amount);
      return Math.max(0, Number(b.total_subtotal) - Number(b.host_fee));
    };

    const now = new Date();
    const today = startOfLocalDay(now);
    const tomorrow = addDays(today, 1);
    const in30 = addDays(today, 30);
    const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
    const prevMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const prevMonthEnd = monthStart;

    let totalEarnings = 0;
    let thisMonthEarnings = 0;
    let previousMonthEarnings = 0;
    let upcomingRevenue30d = 0;
    let bookedNightsThisMonth = 0;
    let bookedNightsPrevMonth = 0;

    for (const b of bookings) {
      if (!EARNING_STATUSES.includes(b.status)) continue;
      const payout = hostPayout(b);
      totalEarnings += payout;
      const refDate = b.confirmed_at ?? b.created_at;
      const ref = new Date(refDate);
      if (ref >= monthStart) {
        thisMonthEarnings += payout;
      }
      if (ref >= prevMonthStart && ref < prevMonthEnd) {
        previousMonthEarnings += payout;
      }

      const checkin = parseDateOnly(b.checkin_date);
      const checkout = parseDateOnly(b.checkout_date);
      bookedNightsThisMonth += bookedNightsInMonth(
        checkin,
        checkout,
        now.getFullYear(),
        now.getMonth(),
      );
      bookedNightsPrevMonth += bookedNightsInMonth(
        checkin,
        checkout,
        prevMonthStart.getFullYear(),
        prevMonthStart.getMonth(),
      );
    }

    for (const b of bookings) {
      if (!FUTURE_EARNING_STATUSES.includes(b.status)) continue;
      const checkin = parseDateOnly(b.checkin_date);
      if (checkin >= today && checkin < in30) {
        upcomingRevenue30d += hostPayout(b);
      }
    }

    /**
     * Occupancy (v1): booked nights in month /
     * (days_in_month × max(live_listings, 1)).
     * Later: booked nights / available nights from calendars.
     */
    const dim = daysInMonth(now.getFullYear(), now.getMonth());
    const capacity = dim * Math.max(liveListings, 1);
    const occupancyPctThisMonth =
      capacity > 0
        ? Math.min(
            100,
            Math.round((bookedNightsThisMonth / capacity) * 1000) / 10,
          )
        : 0;

    const prevDim = daysInMonth(
      prevMonthStart.getFullYear(),
      prevMonthStart.getMonth(),
    );
    const prevCapacity = prevDim * Math.max(liveListings, 1);
    const occupancyPrev =
      prevCapacity > 0
        ? Math.min(
            100,
            Math.round((bookedNightsPrevMonth / prevCapacity) * 1000) / 10,
          )
        : 0;

    const avgNightlyEarnings =
      bookedNightsThisMonth > 0
        ? round2(thisMonthEarnings / bookedNightsThisMonth)
        : null;

    let upcomingCheckins = 0;
    let currentGuests = 0;
    let checkinsToday = 0;
    let checkoutsTomorrow = 0;
    let awaitingGuestPayment = 0;
    let nextUpcoming: StaysBooking | null = null;

    for (const b of bookings) {
      const life = this.lifecycleService.computeLifecycle(b, { now });
      const checkin = parseDateOnly(b.checkin_date);
      const checkout = parseDateOnly(b.checkout_date);

      if (life === 'PENDING_PAYMENT') {
        awaitingGuestPayment += 1;
      }
      if (life === 'UPCOMING') {
        upcomingCheckins += 1;
        if (
          !nextUpcoming ||
          checkin < parseDateOnly(nextUpcoming.checkin_date)
        ) {
          nextUpcoming = b;
        }
      }
      if (life === 'ACTIVE') {
        currentGuests += 1;
      }
      if (
        (b.status === 'CONFIRMED' || b.status === 'CHECKED_IN') &&
        checkin.getTime() === today.getTime()
      ) {
        checkinsToday += 1;
      }
      if (
        (b.status === 'CONFIRMED' ||
          b.status === 'CHECKED_IN' ||
          b.status === 'COMPLETED') &&
        checkout.getTime() === tomorrow.getTime()
      ) {
        checkoutsTomorrow += 1;
      }
    }

    const nextGuestName = nextUpcoming
      ? this.resolveGuestDisplayName(nextUpcoming)
      : null;
    const nextCheckinDate = nextUpcoming
      ? toIsoDate(parseDateOnly(nextUpcoming.checkin_date))
      : null;

    const revenueSeries30d = this.buildRevenueSeries(
      bookings,
      hostPayout,
      today,
    );

    let pendingPayoutAmount: number | null = null;
    if (listingIds.length > 0) {
      const pendingRows = await this.ledgerRepo
        .createQueryBuilder('e')
        .innerJoin('e.booking', 'b')
        .innerJoin('b.listing', 'l')
        .where('l.host_user_id = :hostUserId', { hostUserId })
        .andWhere('e.type = :type', { type: 'HOST_PAYOUT' })
        .andWhere('e.status = :status', { status: 'PENDING' })
        .getMany();
      if (pendingRows.length > 0) {
        pendingPayoutAmount = round2(
          pendingRows.reduce((sum, row) => sum + Number(row.amount), 0),
        );
      } else {
        pendingPayoutAmount = 0;
      }
    }

    let calendarStatus = {
      healthy: true,
      listings_needing_attention: 0,
    };
    if (listingIds.length > 0) {
      const calendars = await this.calendarRepo.find({
        where: { listing_id: In(listingIds) },
        select: ['id', 'listing_id', 'status'],
      });
      const badListings = new Set(
        calendars.filter((c) => c.status === 'ERROR').map((c) => c.listing_id),
      );
      calendarStatus = {
        healthy: badListings.size === 0,
        listings_needing_attention: badListings.size,
      };
    }

    const listingHealth = await this.buildListingHealth(
      hostUserId,
      listingIds,
      liveListings,
    );

    const reviewsPayload = await this.staysReviewsService.listHostReviews(
      hostUserId,
      1,
      1,
    );

    const currency = bookings.find((b) => b.currency)?.currency ?? 'MAD';

    return {
      total_earnings: round2(totalEarnings),
      this_month_earnings: round2(thisMonthEarnings),
      previous_month_earnings: round2(previousMonthEarnings),
      earnings_mom_pct: momPct(thisMonthEarnings, previousMonthEarnings),
      upcoming_revenue_30d: round2(upcomingRevenue30d),
      occupancy_pct_this_month: occupancyPctThisMonth,
      occupancy_mom_pct: momPct(occupancyPctThisMonth, occupancyPrev),
      avg_nightly_earnings: avgNightlyEarnings,
      currency,
      total_bookings: bookings.length,
      pending_bookings: bookings.filter((b) =>
        PENDING_STATUSES.includes(b.status),
      ).length,
      active_bookings: bookings.filter((b) =>
        ACTIVE_STATUSES.includes(b.status),
      ).length,
      completed_bookings: bookings.filter((b) => b.status === 'COMPLETED')
        .length,
      cancelled_bookings: bookings.filter(
        (b) =>
          b.status === 'CANCELLED_BY_GUEST' ||
          b.status === 'CANCELLED_BY_HOST' ||
          b.status === 'EXPIRED',
      ).length,
      live_listings: liveListings,
      pending_listings: listings.filter(
        (l) => l.status === 'SUBMITTED' || l.status === 'DRAFT',
      ).length,
      total_listings: listings.length,
      avg_rating: reviewsPayload.summary.overall_avg_rating,
      total_reviews: reviewsPayload.summary.total_count,
      upcoming_checkins: upcomingCheckins,
      next_checkin_date: nextCheckinDate,
      next_guest_name: nextGuestName,
      current_guests: currentGuests,
      checkins_today: checkinsToday,
      checkouts_tomorrow: checkoutsTomorrow,
      awaiting_guest_payment: awaitingGuestPayment,
      pending_payout_amount: pendingPayoutAmount,
      calendar_status: calendarStatus,
      revenue_series_30d: revenueSeries30d,
      listing_health: listingHealth,
    };
  }

  private buildRevenueSeries(
    bookings: StaysBooking[],
    hostPayout: (b: StaysBooking) => number,
    today: Date,
  ): Array<{ date: string; amount: number }> {
    const amounts = new Map<string, number>();
    for (let i = 29; i >= 0; i--) {
      amounts.set(toIsoDate(addDays(today, -i)), 0);
    }
    for (const b of bookings) {
      if (!EARNING_STATUSES.includes(b.status)) continue;
      const checkin = parseDateOnly(b.checkin_date);
      const key = toIsoDate(checkin);
      if (!amounts.has(key)) continue;
      amounts.set(key, (amounts.get(key) ?? 0) + hostPayout(b));
    }
    return Array.from(amounts.entries()).map(([date, amount]) => ({
      date,
      amount: round2(amount),
    }));
  }

  private async buildListingHealth(
    hostUserId: string,
    listingIds: string[],
    liveListings: number,
  ) {
    const empty = {
      verified_live: false,
      calendar_synced: false,
      photos_complete: false,
      avg_completion_pct: 0,
      missing: [] as Array<{ code: string; label: string; count?: number }>,
    };
    if (listingIds.length === 0) return empty;

    const summaries =
      await this.hostListingsService.getHostListings(hostUserId);
    const calendars = await this.calendarRepo.find({
      where: { listing_id: In(listingIds) },
      select: ['listing_id', 'status'],
    });
    const syncedListings = new Set(
      calendars
        .filter((c) => c.status === 'ACTIVE' || c.status === 'SYNCING')
        .map((c) => c.listing_id),
    );

    let photosCompleteCount = 0;
    let completionSum = 0;
    const missingCounts = new Map<string, { label: string; count: number }>();

    for (const s of summaries) {
      const pct = s.completion_percentage ?? 0;
      completionSum += pct;
      const flags = s.completion_flags;
      if (flags?.photos_complete) photosCompleteCount += 1;
      for (const m of s.missing ?? []) {
        if (!m.required) continue;
        const prev = missingCounts.get(m.key);
        if (prev) prev.count += 1;
        else missingCounts.set(m.key, { label: m.label, count: 1 });
      }
    }

    const missing = Array.from(missingCounts.entries()).map(
      ([code, { label, count }]) => ({
        code,
        label: count > 1 ? `${label} (${count} listings)` : label,
        count,
      }),
    );

    return {
      verified_live: liveListings > 0,
      calendar_synced: syncedListings.size > 0,
      photos_complete:
        summaries.length > 0 && photosCompleteCount === summaries.length,
      avg_completion_pct:
        summaries.length > 0 ? Math.round(completionSum / summaries.length) : 0,
      missing,
    };
  }

  private resolveGuestDisplayName(booking: StaysBooking): string | null {
    const occupants = booking.occupants ?? [];
    if (occupants.length === 0) return null;
    const primary =
      occupants.find((o) => o.is_primary) ??
      occupants.find((o) => o.full_name?.trim()) ??
      occupants[0];
    return primary?.full_name?.trim() || null;
  }
}

