const SUPPORT_PRESENCE_TTL_MS = 60_000;

function parseCsatRating(raw: unknown, label: string): number {
  const n = Math.round(Number(raw) * 2) / 2;
  if (!(SUPPORT_CSAT_RATINGS as readonly number[]).includes(n)) {
    throw new BadRequestException(
      `${label} must be in 0.5 increments from 0.5 to 5`,
    );
  }
  return n;
}

function isUniqueViolation(err: unknown): boolean {
  if (err instanceof QueryFailedError) {
    const driver = err.driverError as { code?: string };
    return driver?.code === '23505';
  }
  return (
    typeof err === 'object' &&
    err !== null &&
    (err as { code?: string }).code === '23505'
  );
}

const ENSURE_TICKET_FAILED = 'Failed to ensure support ticket.';

function requireTicket(
  ticket: StaysSupportTicket | null | undefined,
): StaysSupportTicket {
  if (!ticket) {
    throw new InternalServerErrorException(ENSURE_TICKET_FAILED);
  }
  return ticket;
}

