  /**
   * Atomically create a conversation report + Support ticket + SUPPORT thread.
   * Failure rolls back all newly created rows (no orphan canonical report).
   */
  async provisionReportWithTicket(input: {
    conversationId: string;
    reporterUserId: string;
    reason?: string;
    attachmentIds?: string[];
    bookingId?: string | null;
    listingId?: string | null;
    reportedUserId?: string | null;
    sourceConversation: StaysConversation;
  }): Promise<{
    report: StaysConversationReport;
    ticket: StaysSupportTicket;
  }> {
    const result = await this.dataSource.transaction(async (manager) => {
      const report = await this.createReport(
        {
          conversationId: input.conversationId,
          reporterUserId: input.reporterUserId,
          reason: input.reason,
          attachmentIds: input.attachmentIds,
          bookingId: input.bookingId,
          listingId: input.listingId,
          reportedUserId: input.reportedUserId,
        },
        manager,
      );
      const ticket = await this.ensureTicketForReport({
        report,
        sourceConversation: input.sourceConversation,
        manager,
      });
      return { report, ticket };
    });
    this.realtime.publish(input.reporterUserId, {
      conversationId: result.ticket.conversation_id,
      reason: 'MESSAGE_CREATED',
    });
    await this.ops.safeEvaluate(() =>
      this.ops.evaluateReport('conversation_reported', result.report.id),
    );
    await this.scheduleAutoAssignment(result.ticket.id);
    return result;
  }

  /**
   * Atomically create a safety issue + Support ticket + SUPPORT thread.
   * Failure rolls back all newly created rows (no orphan canonical safety row).
   */
  async provisionSafetyIssueWithTicket(input: {
    conversationId: string;
    reporterUserId: string;
    category: string;
    details?: string;
    attachmentIds?: string[];
    bookingId?: string | null;
    listingId?: string | null;
    reportedUserId?: string | null;
    sourceConversation: StaysConversation;
  }): Promise<{
    safety: StaysSafetyIssue;
    ticket: StaysSupportTicket;
  }> {
    const result = await this.dataSource.transaction(async (manager) => {
      const safety = await this.createSafetyIssue(
        {
          conversationId: input.conversationId,
          reporterUserId: input.reporterUserId,
          category: input.category,
          details: input.details,
          attachmentIds: input.attachmentIds,
          bookingId: input.bookingId,
          listingId: input.listingId,
          reportedUserId: input.reportedUserId,
        },
        manager,
      );
      const ticket = await this.ensureTicketForSafetyIssue({
        safety,
        sourceConversation: input.sourceConversation,
        manager,
      });
      return { safety, ticket };
    });
    this.realtime.publish(input.reporterUserId, {
      conversationId: result.ticket.conversation_id,
      reason: 'MESSAGE_CREATED',
    });
    await this.ops.safeEvaluate(() =>
      this.ops.evaluateReport('safety_issue', result.safety.id),
    );
    await this.scheduleAutoAssignment(result.ticket.id);
    return result;
  }

  /**
   * Opens an ops Support Ticket for a conversation report so it appears in
   * the admin Support queue without requiring a separate Contact Support step.
   * When `manager` is provided, participates in the caller's transaction
   * (no nested independent TX).
   * Always returns a valid ticket or throws — never null.
   */
  async ensureTicketForReport(input: {
    report: StaysConversationReport;
    sourceConversation: StaysConversation;
    manager?: EntityManager;
  }): Promise<StaysSupportTicket> {
    const ticketRepo = input.manager
      ? input.manager.getRepository(StaysSupportTicket)
      : this.ticketRepo;
    const existing = await ticketRepo.findOne({
      where: { report_id: input.report.id },
    });
    if (existing) return existing;

    const party = this.partyFromConversation(
      input.sourceConversation,
      input.report.reporter_user_id,
    );
    const reason =
      input.report.reason?.trim() || 'Conversation reported by customer';
    const subject = reason.slice(0, 120) || 'Conversation report';

    try {
      const created = await this.createTicketForUser(
        input.report.reporter_user_id,
        {
          category: 'OTHER',
          subject,
          message: reason,
          reportId: input.report.id,
          ...(input.sourceConversation.booking_id
            ? { bookingId: input.sourceConversation.booking_id }
            : {}),
          ...(input.sourceConversation.listing_id
            ? { listingId: input.sourceConversation.listing_id }
            : {}),
        },
        { party, manager: input.manager },
      );
      return requireTicket(
        await ticketRepo.findOne({ where: { id: created.id } }),
      );
    } catch (err) {
      if (isUniqueViolation(err)) {
        // createTicketForUser already rolled back the failed insert via
        // savepoint (nested) or aborted standalone TX; outer TX is still usable.
        return requireTicket(
          await ticketRepo.findOne({
            where: { report_id: input.report.id },
          }),
        );
      }
      throw err;
    }
  }

  /**
   * Opens an ops Support Ticket for a safety issue so agents can action it.
   * When `manager` is provided, participates in the caller's transaction.
   * Always returns a valid ticket or throws — never null.
   */
  async ensureTicketForSafetyIssue(input: {
    safety: StaysSafetyIssue;
    sourceConversation: StaysConversation;
    manager?: EntityManager;
  }): Promise<StaysSupportTicket> {
    const ticketRepo = input.manager
      ? input.manager.getRepository(StaysSupportTicket)
      : this.ticketRepo;
    const existing = await ticketRepo.findOne({
      where: { safety_issue_id: input.safety.id },
    });
    if (existing) return existing;

    const party = this.partyFromConversation(
      input.sourceConversation,
      input.safety.reporter_user_id,
    );
    const details = input.safety.details?.trim();
    const message = details
      ? `[${input.safety.category}] ${details}`
      : `[${input.safety.category}] Safety issue reported`;
    const subject = message.slice(0, 120);

    try {
      const created = await this.createTicketForUser(
        input.safety.reporter_user_id,
        {
          category: 'FRAUD',
          subject,
          message,
          safetyIssueId: input.safety.id,
          ...(input.sourceConversation.booking_id
            ? { bookingId: input.sourceConversation.booking_id }
            : {}),
          ...(input.sourceConversation.listing_id
            ? { listingId: input.sourceConversation.listing_id }
            : {}),
        },
        { party, priority: 'HIGH', manager: input.manager },
      );
      return requireTicket(
        await ticketRepo.findOne({ where: { id: created.id } }),
      );
    } catch (err) {
      if (isUniqueViolation(err)) {
        return requireTicket(
          await ticketRepo.findOne({
            where: { safety_issue_id: input.safety.id },
          }),
        );
      }
      throw err;
    }
  }

  /**
   * Unique violations abort the PostgreSQL transaction. Isolate ticket inserts
   * in a savepoint so callers can safely reuse an existing row on 23505.
   */
  private async withUniqueConflictSavepoint<T>(
    manager: EntityManager,
    work: () => Promise<T>,
  ): Promise<T> {
    const sp = `sp_support_ticket_${Date.now().toString(36)}`;
    await manager.query(`SAVEPOINT ${sp}`);
    try {
      const result = await work();
      await manager.query(`RELEASE SAVEPOINT ${sp}`);
      return result;
    } catch (err) {
      await manager.query(`ROLLBACK TO SAVEPOINT ${sp}`);
      throw err;
    }
  }

  private partyFromConversation(
    conversation: StaysConversation,
    reporterUserId: string,
  ): SupportTicketParty {
    if (conversation.host_user_id === reporterUserId) return 'HOST';
    return 'GUEST';
  }

  async createTicketForUser(
    userId: string,
    dto: CreateSupportTicketDto,
    options: {
      party?: SupportTicketParty;
      customerName?: string | null;
      priority?: SupportTicketPriority;
      /** When set, join this TX (no nested dataSource.transaction / no SSE). */
      manager?: EntityManager;
    } = {},
  ) {
    const ticketRepo = options.manager
      ? options.manager.getRepository(StaysSupportTicket)
      : this.ticketRepo;

    if (dto.reportId) {
      const existing = await ticketRepo.findOne({
        where: { report_id: dto.reportId, requester_user_id: userId },
      });
      if (existing) {
        return {
          id: existing.id,
          ticket_number: existing.ticket_number,
          conversation_id: existing.conversation_id,
          status: existing.status,
          category: existing.category,
          subject: existing.subject,
          party: existing.party,
          created_at: existing.created_at.toISOString(),
        };
      }
    }
    if (dto.safetyIssueId) {
      const existing = await ticketRepo.findOne({
        where: {
          safety_issue_id: dto.safetyIssueId,
          requester_user_id: userId,
        },
      });
      if (existing) {
        return {
          id: existing.id,
          ticket_number: existing.ticket_number,
          conversation_id: existing.conversation_id,
          status: existing.status,
          category: existing.category,
          subject: existing.subject,
          party: existing.party,
          created_at: existing.created_at.toISOString(),
        };
      }
    }

    const party = options.party ?? (await this.resolveParty(userId));
    const links = await this.resolveOwnedLinks(
      userId,
      party,
      dto,
      options.manager,
    );
    const identity = await this.identityUsers.getProfileSummary(userId);
    const customerName =
      options.customerName?.trim() || identity?.fullName || null;
    const requesterEmail = identity?.email || null;
    const requesterLanguage = canonicalizeRequesterLanguage(
      identity?.preferredLanguage,
    );

    const insertTicket = async (manager: EntityManager) => {
      const ticketNumber = await this.allocateTicketNumber(manager);
      const subject = dto.subject.trim();
      const conversation = await this.createSupportConversation(
        manager,
        userId,
        party,
        links.listingId,
        {
          subject,
          ticketNumber,
        },
      );

      const preview = dto.message.trim().slice(0, 200);
      const ticket = manager.getRepository(StaysSupportTicket).create({
        ticket_number: ticketNumber,
        requester_user_id: userId,
        party,
        category: dto.category as SupportTicketCategory,
        subject,
        status: 'OPEN',
        priority: options.priority ?? 'NORMAL',
        assigned_admin_id: null,
        conversation_id: conversation.id,
        booking_id: links.bookingId,
        listing_id: links.listingId,
        report_id: links.reportId,
        safety_issue_id: links.safetyIssueId,
        unread_for_support: true,
        last_message_preview: preview,
        customer_name: customerName,
        requester_email: requesterEmail,
        requester_language: requesterLanguage,
        resolved_at: null,
        first_admin_response_at: null,
        closed_at: null,
      });
      const savedTicket = await manager
        .getRepository(StaysSupportTicket)
        .save(ticket);

      await this.timelineSeeder.insertMessage(manager, conversation, {
        type: 'TEXT',
        body: dto.message.trim(),
        metadata: {
          source: 'USER',
          schemaVersion: 1,
          cardVersion: 1,
          presentationVersion: 1,
          supportTicketId: savedTicket.id,
          ...(dto.clientRequestId
            ? { clientRequestId: dto.clientRequestId }
            : {}),
        },
        senderId: userId,
        clientMessageId: dto.clientRequestId ?? null,
        senderDisplayName: customerName ?? 'Customer',
      });

      return savedTicket;
    };

    const toCreatedDto = (created: StaysSupportTicket) => ({
      id: created.id,
      ticket_number: created.ticket_number,
      conversation_id: created.conversation_id,
      status: created.status,
      category: created.category,
      subject: created.subject,
      party: created.party,
      created_at: created.created_at.toISOString(),
    });

    const reuseAfterUnique = async (manager?: EntityManager) => {
      const repo = manager
        ? manager.getRepository(StaysSupportTicket)
        : this.ticketRepo;
      if (dto.reportId) {
        const existing = await repo.findOne({
          where: { report_id: dto.reportId, requester_user_id: userId },
        });
        if (existing) return toCreatedDto(existing);
      }
      if (dto.safetyIssueId) {
        const existing = await repo.findOne({
          where: {
            safety_issue_id: dto.safetyIssueId,
            requester_user_id: userId,
          },
        });
        if (existing) return toCreatedDto(existing);
      }
      return null;
    };

    let created: StaysSupportTicket;
    try {
      if (options.manager) {
        // Nested in an outer TX: isolate 23505 with a savepoint so the outer
        // transaction stays usable for conflict reuse.
        created = await this.withUniqueConflictSavepoint(options.manager, () =>
          insertTicket(options.manager!),
        );
      } else {
        created = await this.dataSource.transaction((manager) =>
          insertTicket(manager),
        );
      }
    } catch (err) {
      if (isUniqueViolation(err)) {
        const reused = await reuseAfterUnique(options.manager);
        if (reused) return reused;
        throw new InternalServerErrorException(ENSURE_TICKET_FAILED);
      }
      throw err;
    }

    if (!options.manager) {
      this.realtime.publish(userId, {
        conversationId: created.conversation_id,
        reason: 'MESSAGE_CREATED',
      });
      await this.ops.safeEvaluate(() => this.ops.evaluateTicket(created.id));
      await this.scheduleAutoAssignment(created.id);
    }

    return toCreatedDto(created);
  }

  async listForUser(userId: string, limit = 50) {
    const take = Math.min(Math.max(limit, 1), 200);
    const rows = await this.ticketRepo.find({
      where: { requester_user_id: userId },
      order: { updated_at: 'DESC' },
      take,
    });
    return { items: rows.map((row) => this.toListRow(row)) };
  }

  async getForUser(userId: string, ticketId: string) {
    const ticket = await this.ticketRepo.findOne({
      where: { id: ticketId, requester_user_id: userId },
    });
    if (!ticket) throw new NotFoundException('Ticket not found');
    return this.toListRow(ticket);
  }

  async closedConversationIds(conversationIds: string[]): Promise<Set<string>> {
    if (!conversationIds.length) return new Set();
    const rows = await this.ticketRepo.find({
      where: { conversation_id: In(conversationIds), status: 'CLOSED' },
      select: ['conversation_id'],
    });
    return new Set(rows.map((row) => row.conversation_id));
  }

  async listForAdmin(
    query: AdminListTicketsQueryDto = {},
    actor: SupportStaffActor = DEFAULT_ADMIN_ACTOR,
  ) {
    if (
      !isSupportAgentActor(actor) &&
      query.unassigned === true &&
      query.assignedAdminId
    ) {
      throw new BadRequestException(
        'Cannot combine unassigned=true with assignedAdminId',
      );
    }
    const limit = Math.min(Math.max(query.limit ?? 50, 1), 100);
    const offset = Math.max(query.offset ?? 0, 0);
    const qb = this.ticketRepo
      .createQueryBuilder('t')
      .leftJoin(StaysBooking, 'b', 'b.id = t.booking_id')
      .leftJoin(StaysListing, 'l', 'l.id = t.listing_id');

    const statuses = (query.status ?? '')
      .split(',')
      .map((s) => s.trim().toUpperCase())
      .filter((s): s is SupportTicketStatus =>
        (SUPPORT_TICKET_STATUSES as readonly string[]).includes(s),
      );
    if (statuses.length) {
      qb.andWhere('t.status IN (:...statuses)', { statuses });
    }
    if (query.priority) {
      qb.andWhere('t.priority = :priority', { priority: query.priority });
    }
    if (query.category) {
      qb.andWhere('t.category = :category', { category: query.category });
    }
    if (isSupportAgentActor(actor)) {
      qb.andWhere('t.assigned_admin_id = :assignedAdminId', {
        assignedAdminId: actor.userId,
      });
    } else if (query.unassigned === true) {
      qb.andWhere('t.assigned_admin_id IS NULL');
    } else if (query.assignedAdminId) {
      qb.andWhere('t.assigned_admin_id = :assignedAdminId', {
        assignedAdminId: query.assignedAdminId,
      });
    }
    if (query.requesterUserId) {
      qb.andWhere('t.requester_user_id = :requesterUserId', {
        requesterUserId: query.requesterUserId,
      });
    }
    if (query.bookingId) {
      qb.andWhere('t.booking_id = :bookingId', { bookingId: query.bookingId });
    }
    if (query.listingId) {
      qb.andWhere('t.listing_id = :listingId', { listingId: query.listingId });
    }
    if (query.slaState === 'AT_RISK' || query.slaState === 'BREACHED') {
      this.ops.applySlaStateFilter(qb, 't', query.slaState);
    }
    const search = query.search?.trim();
    if (search) {
      const q = `%${search.replace(/\\/g, '\\\\').replace(/[%_]/g, '\\$&')}%`;
      qb.andWhere(
        `(t.ticket_number ILIKE :q ESCAPE '\\'
          OR t.subject ILIKE :q ESCAPE '\\'
          OR t.customer_name ILIKE :q ESCAPE '\\'
          OR t.requester_email ILIKE :q ESCAPE '\\'
          OR b.booking_reference ILIKE :q ESCAPE '\\'
          OR l.title ILIKE :q ESCAPE '\\')`,
        { q },
      );
    }

    const total = await qb.clone().getCount();
    const rows = await qb
      .orderBy('t.updated_at', 'DESC')
      .skip(offset)
      .take(limit)
      .getMany();

    await this.hydrateTicketIdentities(rows);
    await this.ops.safeEvaluate(() => this.ops.evaluateListedTickets(rows));
    const bookingRefs = await this.loadBookingRefs(
      rows.map((r) => r.booking_id).filter(Boolean) as string[],
    );
    const signalTypes = await this.ops.activeTypesByTicketIds(
      rows.map((r) => r.id),
    );
    const csatByTicket = await this.loadCsatByTicketIds(rows.map((r) => r.id));
    return {
      items: rows.map((row) => ({
        ...this.toListRow(row, bookingRefs.get(row.booking_id ?? '') ?? null),
        operational_signal_types: signalTypes.get(row.id) ?? [],
        csat: csatByTicket.get(row.id) ?? null,
      })),
      total,
      limit,
      offset,
      hasMore: offset + rows.length < total,
    };
  }

  async listSupportReviewsForAdmin(
    query: AdminListSupportReviewsQueryDto = {},
    actor: SupportStaffActor = DEFAULT_ADMIN_ACTOR,
  ) {
    const limit = Math.min(Math.max(query.limit ?? 50, 1), 100);
    const offset = Math.max(query.offset ?? 0, 0);
    const qb = this.csatRepo
      .createQueryBuilder('c')
      .innerJoin(StaysSupportTicket, 't', 't.id = c.ticket_id');

    if (isSupportAgentActor(actor)) {
      qb.andWhere('(t.assigned_admin_id = :actorId OR c.agent_id = :actorId)', {
        actorId: actor.userId,
      });
    }
    if (query.problemSolved === true) {
      qb.andWhere('c.problem_solved = true');
    } else if (query.problemSolved === false) {
      qb.andWhere('c.problem_solved = false');
    }
    if (query.maxRating != null) {
      qb.andWhere('c.rating <= :maxRating', { maxRating: query.maxRating });
    }
    const search = query.search?.trim();
    if (search) {
      const q = `%${search.replace(/\\/g, '\\\\').replace(/[%_]/g, '\\$&')}%`;
      qb.andWhere(
        `(t.ticket_number ILIKE :q ESCAPE '\\'
          OR t.customer_name ILIKE :q ESCAPE '\\'
          OR COALESCE(c.comment, '') ILIKE :q ESCAPE '\\')`,
        { q },
      );
    }

    const total = await qb.clone().getCount();
    const rows = await qb
      .select([
        'c.ticket_id AS ticket_id',
        'c.rating AS rating',
        'c.agent_rating AS agent_rating',
        'c.agent_id AS agent_id',
        'c.problem_solved AS problem_solved',
        'c.comment AS comment',
        'c.submitted_at AS submitted_at',
        't.ticket_number AS ticket_number',
        't.status AS status',
        't.customer_name AS customer_name',
        't.review_agent_id AS review_agent_id',
        't.review_agent_name AS review_agent_name',
      ])
      .orderBy('c.submitted_at', 'DESC')
      .skip(offset)
      .take(limit)
      .getRawMany();

    return {
      items: rows.map((row) => this.mapSupportReviewRow(row)),
      total,
      limit,
      offset,
      hasMore: offset + rows.length < total,
    };
  }

  async countOpenTicketsForAdmin(): Promise<number> {
    return this.ticketRepo
      .createQueryBuilder('t')
      .where('t.status IN (:...statuses)', { statuses: OPEN_TICKET_STATUSES })
      .getCount();
  }

  private async requireAccessibleTicket(
    ticketId: string,
    actor: SupportStaffActor,
  ): Promise<StaysSupportTicket> {
    const ticket = await this.ticketRepo.findOne({ where: { id: ticketId } });
    assertCanAccessTicket(ticket, actor);
    return ticket;
  }

  private async assertEligibleAssignee(userId: string) {
    const authz = await this.identityUsers.getAuthz(userId);
    if (!authz) {
      throw new NotFoundException('Admin user not found');
    }
    if (
      authz.account_type !== 'ADMIN' ||
      authz.staff_role !== 'SUPPORT_AGENT' ||
      authz.status !== 'ACTIVE'
    ) {
      throw new UnprocessableEntityException(
        'Support agent is not eligible for assignment',
      );
    }
  }

  async getForAdmin(
    ticketId: string,
    actor: SupportStaffActor = DEFAULT_ADMIN_ACTOR,
  ) {
    const ticket = await this.requireAccessibleTicket(ticketId, actor);

    const bookingRefs = ticket.booking_id
      ? await this.loadBookingRefs([ticket.booking_id])
      : new Map<string, string>();

    let listing: Record<string, unknown> | null = null;
    let listingHostId: string | null = null;
    if (ticket.listing_id) {
      const row = await this.listingRepo.findOne({
        where: { id: ticket.listing_id },
        relations: ['check_in_contact'],
      });
      if (row) {
        listingHostId = row.host_user_id;
        listing = {
          id: row.id,
          title: row.title,
          host_user_id: row.host_user_id,
          city: row.city,
          address: row.address_encrypted?.trim() || null,
        };
        if (row.check_in_contact) {
          listing.check_in_contact = {
            name: row.check_in_contact.full_name,
            phone: row.check_in_contact.phone_encrypted,
            role: row.check_in_contact.role,
          };
        }
      }
    }

    let guestUserId: string | null = null;
    if (ticket.booking_id) {
      const booking = await this.bookingRepo.findOne({
        where: { id: ticket.booking_id },
      });
      guestUserId = booking?.guest_user_id ?? null;
    }

    const contacts = await this.resolveSupportContacts([
      listingHostId,
      guestUserId,
      ticket.requester_user_id,
    ]);
    const emptyContact = (id: string) => ({
      id,
      name: null,
      email: null,
      phone: null,
    });
    if (listing && listingHostId) {
      listing.host = contacts.get(listingHostId) ?? emptyContact(listingHostId);
    }

    let report: Record<string, unknown> | null = null;
    if (ticket.report_id) {
      const row = await this.reportRepo.findOne({
        where: { id: ticket.report_id },
      });
      if (row) {
        report = {
          id: row.id,
          reason: row.reason,
          conversation_id: row.conversation_id,
          reporter_user_id: row.reporter_user_id,
        };
      }
    }

    let safety_issue: Record<string, unknown> | null = null;
    if (ticket.safety_issue_id) {
      const row = await this.safetyRepo.findOne({
        where: { id: ticket.safety_issue_id },
      });
      if (row) {
        safety_issue = {
          id: row.id,
          category: row.category,
          details: row.details,
          conversation_id: row.conversation_id,
          reporter_user_id: row.reporter_user_id,
        };
      }
    }

    await this.ops.safeEvaluate(() => this.ops.evaluateTicket(ticket.id));
    await this.ops.safeEvaluate(() =>
      this.quality.evaluateAfterLifecycle({ ticketId: ticket.id }),
    );
    const [csat, signals, relatedTickets, viewers] = await Promise.all([
      this.loadCsatForTicket(ticket.id),
      this.ops
        .listSignalsForTicket(ticket.id, false, actor)
        .catch(() => ({ items: [] })),
      this.ops.findRelatedTickets(ticket.id, actor).catch(() => []),
      this.listActiveViewers(ticket.id).catch(() => []),
    ]);

    return {
      ...this.toListRow(
        ticket,
        bookingRefs.get(ticket.booking_id ?? '') ?? null,
      ),
      conversation_id: ticket.conversation_id,
      listing,
      host: listingHostId
        ? (contacts.get(listingHostId) ?? emptyContact(listingHostId))
        : null,
      guest: guestUserId
        ? (contacts.get(guestUserId) ?? emptyContact(guestUserId))
        : null,
      reporter: ticket.requester_user_id
        ? (contacts.get(ticket.requester_user_id) ??
          emptyContact(ticket.requester_user_id))
        : null,
      report,
      safety_issue,
      csat,
      signals: signals.items,
      related_tickets: relatedTickets,
      viewers,
    };
  }

  async patchForAdmin(
    ticketId: string,
    patch: PatchSupportTicketDto,
    actorUserId?: string | SupportStaffActor,
    actorArg?: SupportStaffActor,
  ) {
    const actor: SupportStaffActor =
      actorArg ??
      (typeof actorUserId === 'object' && actorUserId
        ? actorUserId
        : {
            userId: typeof actorUserId === 'string' ? actorUserId : 'system',
            role: 'ADMIN',
          });
    const auditUserId =
      typeof actorUserId === 'string' ? actorUserId : actor.userId || 'system';

    if (patch.assigned_admin_id) {
      await this.assertEligibleAssignee(patch.assigned_admin_id);
    }

    const committed = await this.dataSource.transaction(async (manager) => {
      const repo = manager.getRepository(StaysSupportTicket);
      const locked = await repo
        .createQueryBuilder('t')
        .setLock('pessimistic_write')
        .where('t.id = :id', { id: ticketId })
        .getOne();
      if (!locked) throw new NotFoundException('Ticket not found');
      assertCanAccessTicket(locked, actor);

      if (isSupportAgentActor(actor) && patch.assigned_admin_id !== undefined) {
        throw new ForbiddenException(
          'Support agents cannot change ticket assignment',
        );
      }
      if (isSupportAgentActor(actor) && patch.priority !== undefined) {
        throw new ForbiddenException(
          'Support agents cannot change ticket priority',
        );
      }

      const fromStatus = locked.status;
      const fromPriority = locked.priority;
      const fromAdminId = locked.assigned_admin_id;
      const fromResolutionType = locked.resolution_type;
      let firstClose = false;

      if (patch.assigned_admin_id !== undefined) {
        locked.assigned_admin_id = patch.assigned_admin_id ?? null;
      }
      if (
        locked.status === 'CLOSED' &&
        patch.status !== undefined &&
        patch.status !== 'CLOSED'
      ) {
        throw new ConflictException(TICKET_MUST_BE_REOPENED_MESSAGE);
      }
      if (patch.status !== undefined) {
        locked.status = patch.status as SupportTicketStatus;
        if (patch.status === 'RESOLVED') {
          locked.resolved_at = locked.resolved_at ?? new Date();
        } else if (patch.status === 'CLOSED') {
          firstClose = !locked.closed_at;
          locked.closed_at = locked.closed_at ?? new Date();
          locked.resolved_at = locked.resolved_at ?? new Date();
          if (firstClose && locked.review_agent_id == null) {
            locked.review_agent_id = locked.assigned_admin_id;
            if (locked.assigned_admin_id) {
              const summary = await this.identityUsers.getProfileSummary(
                locked.assigned_admin_id,
              );
              locked.review_agent_name =
                summary?.fullName?.trim() || locked.review_agent_name || null;
            }
          }
          if (firstClose && locked.conversation_id) {
            const convRepo = manager.getRepository(StaysConversation);
            const conv = await convRepo.findOne({
              where: { id: locked.conversation_id },
            });
            if (conv && conv.messaging_state !== 'ARCHIVED') {
              const now = new Date();
              conv.messaging_state = 'ARCHIVED';
              conv.archived_at = conv.archived_at ?? now;
              conv.read_only_at = conv.read_only_at ?? now;
              conv.archive_reason = 'SUPPORT';
              conv.conversation_version = (conv.conversation_version ?? 0) + 1;
              await convRepo.save(conv);
            }
          }
        }
      }
      if (patch.priority !== undefined) {
        locked.priority = patch.priority as SupportTicketPriority;
      }
      if (patch.resolutionType !== undefined) {
        locked.resolution_type = patch.resolutionType ?? null;
      }
      locked.updated_at = new Date();
      const saved = await repo.save(locked);
      return {
        saved,
        fromStatus,
        fromPriority,
        fromAdminId,
        fromResolutionType,
        firstClose,
      };
    });
    const {
      saved,
      fromStatus,
      fromPriority,
      fromAdminId,
      fromResolutionType,
      firstClose,
    } = committed;

    if (firstClose && saved.requester_user_id && saved.conversation_id) {
      this.realtime.publish(saved.requester_user_id, {
        conversationId: saved.conversation_id,
        reason: 'MESSAGE_READ',
      });
    }

    if (patch.assigned_admin_id !== undefined) {
      await this.staysAudit.log({
        actorUserId: auditUserId,
        actorRole: 'ADMIN',
        entityType: 'support_ticket',
        entityId: saved.id,
        action: 'support_ticket_assigned',
        metadata: {
          fromAdminId: fromAdminId,
          toAdminId: saved.assigned_admin_id,
        },
      });
    }
    if (patch.status !== undefined && patch.status !== fromStatus) {
      await this.staysAudit.log({
        actorUserId: auditUserId,
        actorRole: 'ADMIN',
        entityType: 'support_ticket',
        entityId: saved.id,
        action: 'ticket_status_changed',
        metadata: { from: fromStatus, to: saved.status },
      });
    }
    if (patch.priority !== undefined && patch.priority !== fromPriority) {
      await this.staysAudit.log({
        actorUserId: auditUserId,
        actorRole: 'ADMIN',
        entityType: 'support_ticket',
        entityId: saved.id,
        action: 'ticket_priority_changed',
        metadata: { from: fromPriority, to: saved.priority },
      });
    }
    if (
      patch.resolutionType !== undefined &&
      (patch.resolutionType ?? null) !== (fromResolutionType ?? null)
    ) {
      await this.staysAudit.log({
        actorUserId: auditUserId,
        actorRole: 'ADMIN',
        entityType: 'support_ticket',
        entityId: saved.id,
        action: 'support_ticket_resolution_changed',
        metadata: {
          previousResolutionType: fromResolutionType,
          newResolutionType: saved.resolution_type,
        },
      });
    }

    await this.ops.safeEvaluate(() => this.ops.evaluateTicket(saved.id));
    if (patch.status === 'CLOSED' || saved.status === 'CLOSED') {
      await this.ops.safeEvaluate(() =>
        this.quality.evaluateAfterLifecycle({
          reviewAgentId: saved.review_agent_id,
          ticketId: saved.id,
        }),
      );
    }
    return this.toListRow(saved);
  }

  async reopenForAdmin(
    ticketId: string,
    actorUserId: string,
    reason: string = 'CUSTOMER_UNRESOLVED',
    actor: SupportStaffActor = DEFAULT_ADMIN_ACTOR,
  ) {
    if (isSupportAgentActor(actor)) {
      throw new ForbiddenException('Support agents cannot reopen tickets');
    }
    const committed = await this.dataSource.transaction(async (manager) => {
      const repo = manager.getRepository(StaysSupportTicket);
      const locked = await repo
        .createQueryBuilder('t')
        .setLock('pessimistic_write')
        .where('t.id = :id', { id: ticketId })
        .getOne();
      if (!locked) throw new NotFoundException('Ticket not found');
      if (locked.status !== 'CLOSED') {
        throw new ConflictException(TICKET_IS_NOT_CLOSED_MESSAGE);
      }
      const previousStatus = locked.status;
      const previousAgentId = locked.assigned_admin_id;
      locked.status = locked.assigned_admin_id ? 'IN_PROGRESS' : 'OPEN';
      locked.closed_at = null;
      locked.updated_at = new Date();
      const saved = await repo.save(locked);

      if (locked.conversation_id) {
        const convRepo = manager.getRepository(StaysConversation);
        const conv = await convRepo.findOne({
          where: { id: locked.conversation_id },
        });
        if (conv) {
          conv.messaging_state = 'ACTIVE';
          conv.archived_at = null;
          conv.read_only_at = null;
          conv.archive_reason = null;
          conv.conversation_version = (conv.conversation_version ?? 0) + 1;
          await convRepo.save(conv);
        }
      }

      return { saved, previousStatus, previousAgentId };
    });

    const { saved, previousStatus, previousAgentId } = committed;
    await this.ops.resolveActiveFollowUpRequired(
      saved.id,
      actorUserId,
      'REOPENED',
    );
    await this.staysAudit.log({
      actorUserId,
      actorRole: 'ADMIN',
      entityType: 'support_ticket',
      entityId: saved.id,
      action: 'support_ticket_reopened',
      metadata: {
        reason,
        previousStatus,
        previousAgentId,
        reopenedBy: 'ADMIN',
      },
    });
    if (saved.requester_user_id && saved.conversation_id) {
      this.realtime.publish(saved.requester_user_id, {
        conversationId: saved.conversation_id,
        reason: 'MESSAGE_READ',
      });
    }
    await this.ops.safeEvaluate(() => this.ops.evaluateTicket(saved.id));
    await this.ops.safeEvaluate(() =>
      this.quality.evaluateAfterLifecycle({
        reviewAgentId: saved.review_agent_id,
        ticketId: saved.id,
      }),
    );
    return this.toListRow(saved);
  }

  async heartbeatPresence(
    ticketId: string,
    viewerId: string,
    actor: SupportStaffActor = DEFAULT_ADMIN_ACTOR,
    handling = false,
  ) {
    await this.requireAccessibleTicket(ticketId, actor);
    const now = new Date();
    const expiresAt = new Date(now.getTime() + SUPPORT_PRESENCE_TTL_MS);
    const activityState = handling ? 'HANDLING' : 'VIEWING';
    await this.dataSource.query(
      `
      INSERT INTO stays_support_ticket_viewers (
        ticket_id, viewer_id, last_seen_at, expires_at, last_activity_at, activity_state
      )
      VALUES ($1, $2, $3, $4, $5, $6)
      ON CONFLICT (ticket_id, viewer_id)
      DO UPDATE SET
        last_seen_at = EXCLUDED.last_seen_at,
        expires_at = EXCLUDED.expires_at,
        last_activity_at = CASE
          WHEN EXCLUDED.activity_state = 'HANDLING' THEN EXCLUDED.last_activity_at
          ELSE stays_support_ticket_viewers.last_activity_at
        END,
        activity_state = CASE
          WHEN EXCLUDED.activity_state = 'HANDLING' THEN 'HANDLING'
          WHEN stays_support_ticket_viewers.expires_at > now()
            AND stays_support_ticket_viewers.activity_state = 'HANDLING'
            AND stays_support_ticket_viewers.last_activity_at > now() - interval '60 seconds'
          THEN 'HANDLING'
          ELSE 'VIEWING'
        END
      `,
      [
        ticketId,
        viewerId,
        now.toISOString(),
        expiresAt.toISOString(),
        handling ? now.toISOString() : null,
        activityState,
      ],
    );
    return {
      ok: true as const,
      viewers: await this.listActiveViewers(ticketId),
    };
  }

  async listActiveViewers(ticketId: string) {
    const rows = await this.dataSource.query(
      `
      SELECT viewer_id, last_seen_at, expires_at, last_activity_at, activity_state
      FROM stays_support_ticket_viewers
      WHERE ticket_id = $1 AND expires_at > now()
      ORDER BY last_seen_at DESC
      `,
      [ticketId],
    );
    return rows.map((row) => ({
      viewerId: row.viewer_id,
      lastSeenAt:
        row.last_seen_at instanceof Date
          ? row.last_seen_at.toISOString()
          : String(row.last_seen_at),
      expiresAt:
        row.expires_at instanceof Date
          ? row.expires_at.toISOString()
          : String(row.expires_at),
      lastActivityAt: row.last_activity_at
        ? row.last_activity_at instanceof Date
          ? row.last_activity_at.toISOString()
          : String(row.last_activity_at)
        : null,
      activityState: row.activity_state === 'HANDLING' ? 'HANDLING' : 'VIEWING',
    }));
  }

  async renderCannedReplyForAdmin(
    replyId: string,
    ticketId: string,
    actorUserId: string,
    actor: SupportStaffActor = DEFAULT_ADMIN_ACTOR,
  ) {
    const ticket = await this.requireAccessibleTicket(ticketId, actor);
    const reply = await this.dataSource
      .getRepository(StaysSupportCannedReply)
      .findOne({ where: { id: replyId } });
    if (!reply || !reply.is_active) {
      throw new NotFoundException('Canned reply not found');
    }
    let bookingReference = '';
    if (ticket.booking_id) {
      const booking = await this.bookingRepo.findOne({
        where: { id: ticket.booking_id },
      });
      bookingReference = booking?.booking_reference ?? '';
    }
    let listingName = '';
    if (ticket.listing_id) {
      const listing = await this.listingRepo.findOne({
        where: { id: ticket.listing_id },
      });
      listingName = listing?.title ?? '';
    }
    const body = interpolateCannedBody(reply.body, {
      customer_name: ticket.customer_name?.trim() || '',
      ticket_number: ticket.ticket_number,
      booking_reference: bookingReference,
      listing_name: listingName,
    });
    await this.staysAudit.log({
      actorUserId,
      actorRole: 'ADMIN',
      entityType: 'support_canned_reply',
      entityId: reply.id,
      action: 'support_canned_reply_used',
      metadata: { replyId: reply.id, ticketId: ticket.id },
    });
    return { id: reply.id, title: reply.title, body };
  }

  async listMessagesForAdmin(
    ticketId: string,
    actor: SupportStaffActor = DEFAULT_ADMIN_ACTOR,
  ) {
    const ticket = await this.requireAccessibleTicket(ticketId, actor);
    const now = new Date();
    const receiptChanges = await this.dataSource.transaction(
      async (manager) => {
        if (ticket.unread_for_support) {
          await manager.getRepository(StaysSupportTicket).update(ticket.id, {
            unread_for_support: false,
            updated_at: now,
          });
        }
        if (!ticket.requester_user_id || !ticket.conversation_id) return 0;
        const updated = await manager
          .getRepository(StaysMessage)
          .createQueryBuilder()
          .update(StaysMessage)
          .set({
            status: 'READ',
            read_at: now,
            delivered_at: () => 'COALESCE(delivered_at, NOW())',
          })
          .where('conversation_id = :cid', { cid: ticket.conversation_id })
          .andWhere('sender_id = :uid', { uid: ticket.requester_user_id })
          .andWhere("status IN ('PERSISTED', 'SENT', 'DELIVERED')")
          .andWhere('read_at IS NULL')
          .execute();
        return Number(updated.affected ?? 0);
      },
    );

    if (receiptChanges > 0 && ticket.requester_user_id) {
      this.realtime.publish(ticket.requester_user_id, {
        conversationId: ticket.conversation_id,
        reason: 'MESSAGE_READ',
      });
    }

    const messages = await this.messageRepo.find({
      where: { conversation_id: ticket.conversation_id },
      order: { conversation_sequence: 'ASC' },
      take: 500,
    });

    return {
      items: messages
        .filter((m) => m.type !== 'SYSTEM_INTERNAL' && !m.deleted_at)
        .map((m) => ({
          id: m.id,
          sender_type: this.resolveSenderType(ticket, m.sender_id, m.is_system),
          sender_id: m.sender_id,
          body: m.body ?? '',
          created_at: (m.sent_at ?? m.created_at).toISOString(),
        })),
    };
  }

  async sendAdminMessage(
    ticketId: string,
    adminUserId: string,
    body: string,
    actor: SupportStaffActor = {
      userId: adminUserId,
      role: 'ADMIN',
    },
  ) {
    const trimmed = body.trim();
    if (!trimmed) throw new BadRequestException('Message body required');

    const saved = await this.dataSource.transaction(async (manager) => {
      const ticket = await manager
        .getRepository(StaysSupportTicket)
        .createQueryBuilder('t')
        .setLock('pessimistic_write')
        .where('t.id = :id', { id: ticketId })
        .getOne();
      if (!ticket) throw new NotFoundException('Ticket not found');
      assertCanAccessTicket(ticket, actor);
      if (ticket.status === 'CLOSED') {
        throw new ConflictException(CLOSED_SUPPORT_TICKET_MESSAGE);
      }

      const conv = await manager.getRepository(StaysConversation).findOne({
        where: { id: ticket.conversation_id },
      });
      if (!conv) throw new NotFoundException('Ticket not found');

      const message = await this.timelineSeeder.insertMessage(manager, conv, {
        type: 'TEXT',
        body: trimmed,
        metadata: {
          source: 'SUPPORT_AGENT',
          schemaVersion: 1,
          cardVersion: 1,
          presentationVersion: 1,
          supportTicketId: ticket.id,
        },
        senderId: adminUserId,
        senderDisplayName: 'Support',
      });

      const unreadPatch =
        ticket.party === 'GUEST'
          ? { unread_guest: (conv.unread_guest ?? 0) + 1 }
          : { unread_host: (conv.unread_host ?? 0) + 1 };

      await manager
        .getRepository(StaysConversation)
        .update(conv.id, unreadPatch);
      await manager.getRepository(StaysSupportTicket).update(ticket.id, {
        unread_for_support: false,
        last_message_preview: trimmed.slice(0, 200),
        assigned_admin_id: ticket.assigned_admin_id ?? adminUserId,
        status:
          ticket.status === 'OPEN' || ticket.status === 'WAITING_FOR_CUSTOMER'
            ? 'IN_PROGRESS'
            : ticket.status,
        // First successful admin SUPPORT reply only (COALESCE / once).
        first_admin_response_at: ticket.first_admin_response_at ?? new Date(),
        updated_at: new Date(),
      });

      return {
        message,
        requesterUserId: ticket.requester_user_id,
        conversationId: conv.id,
        conversationVersion: (conv.conversation_version ?? 0) + 1,
        bookingId: conv.booking_id,
      };
    });

    if (saved.requesterUserId) {
      await this.outbox.enqueueDirect(EVENTS.MESSAGE_RECEIVED, {
        messageId: saved.message.id,
        conversationId: saved.conversationId,
        recipientUserId: saved.requesterUserId,
        senderUserId: adminUserId,
        senderName: 'Support',
        preview: trimmed.slice(0, 120),
        bookingId: saved.bookingId,
        conversationVersion: saved.conversationVersion,
        lastMessageId: saved.message.id,
        lastMessageSequence: Number(saved.message.conversation_sequence),
        listingTitle: '',
      });
    }

    this.realtime.publish(saved.requesterUserId, {
      conversationId: saved.conversationId,
      reason: 'MESSAGE_CREATED',
      messageId: saved.message.id,
    });

    await this.ops.safeEvaluate(() => this.ops.evaluateTicket(ticketId));
    await this.ops.safeEvaluate(() =>
      this.quality.evaluateAfterLifecycle({ ticketId }),
    );

    return {
      id: saved.message.id,
      sender_type: 'SUPPORT_AGENT',
      sender_id: adminUserId,
      body: trimmed,
      created_at: (
        saved.message.sent_at ?? saved.message.created_at
      ).toISOString(),
    };
  }

  /**
   * Lock the SUPPORT ticket before inserting a customer message.
   * Throws 409 if CLOSED. Returns null when no ticket is linked.
   */
  async lockTicketForCustomerSend(
    manager: EntityManager,
    conversationId: string,
  ): Promise<StaysSupportTicket | null> {
    const ticket = await manager
      .getRepository(StaysSupportTicket)
      .createQueryBuilder('t')
      .setLock('pessimistic_write')
      .where('t.conversation_id = :id', { id: conversationId })
      .getOne();
    if (!ticket) return null;
    if (ticket.status === 'CLOSED') {
      throw new ConflictException(CLOSED_SUPPORT_TICKET_MESSAGE);
    }
    return ticket;
  }

  /**
   * After a customer SUPPORT message is inserted, update unread + status
   * in the same transaction. Preserves first resolved_at on RESOLVED → OPEN.
   */
  async applyCustomerSupportMessageEffects(
    manager: EntityManager,
    ticket: StaysSupportTicket,
    preview: string,
  ): Promise<void> {
    const nextStatus = nextStatusAfterCustomerMessage({
      status: ticket.status,
      party: ticket.party,
