  async createNoteForAdmin(
    ticketId: string,
    authorAdminId: string,
    body: string,
    actor: SupportStaffActor = {
      userId: authorAdminId,
      role: 'ADMIN',
    },
  ) {
    const trimmed = body.trim();
    if (!trimmed) throw new BadRequestException('Note body required');
    if (trimmed.length > 5000) {
      throw new BadRequestException('Note body too long');
    }
    const note = await this.dataSource.transaction(async (manager) => {
      const ticket = await manager
        .getRepository(StaysSupportTicket)
        .createQueryBuilder('t')
        .setLock('pessimistic_write')
        .where('t.id = :id', { id: ticketId })
        .getOne();
      if (!ticket) throw new NotFoundException('Ticket not found');
      assertCanAccessTicket(ticket, actor);

      const notes = manager.getRepository(StaysSupportTicketNote);
      return notes.save(
        notes.create({
          ticket_id: ticketId,
          author_admin_id: authorAdminId,
          body: trimmed,
        }),
      );
    });
    await this.staysAudit.log({
      actorUserId: authorAdminId,
      actorRole: 'ADMIN',
      entityType: 'support_ticket',
      entityId: ticketId,
      action: 'support_ticket_note_added',
      metadata: { ticketId, noteId: note.id },
    });
    return {
      id: note.id,
      ticket_id: note.ticket_id,
      author_admin_id: note.author_admin_id,
      body: note.body,
      created_at: note.created_at.toISOString(),
    };
  }

  private mapCsatRow(row: StaysSupportTicketCsat) {
    return {
      rating: Number(row.rating),
      comment: row.comment,
      agent_rating: row.agent_rating == null ? null : Number(row.agent_rating),
      agent_id: row.agent_id ?? null,
      problem_solved: row.problem_solved ?? null,
      submitted_at: row.submitted_at.toISOString(),
    };
  }

  private async reviewAgentPayload(
    reviewAgentId: string | null | undefined,
    reviewAgentName?: string | null,
  ) {
    if (!reviewAgentId) return null;
    const summary = await this.identityUsers.getProfileSummary(reviewAgentId);
    return {
      id: reviewAgentId,
      fullName: reviewAgentName?.trim() || summary?.fullName || null,
      profilePhotoUrl: null as string | null,
    };
  }

  private async loadCsatForTicket(ticketId: string) {
    const row = await this.csatRepo.findOne({ where: { ticket_id: ticketId } });
    return row ? this.mapCsatRow(row) : null;
  }

  private async loadCsatByTicketIds(ticketIds: string[]) {
    const map = new Map<
      string,
      ReturnType<SupportTicketsService['mapCsatRow']>
    >();
    if (!ticketIds.length) return map;
    const rows = await this.csatRepo.find({
      where: { ticket_id: In(ticketIds) },
    });
    for (const row of rows) {
      map.set(row.ticket_id, this.mapCsatRow(row));
    }
    return map;
  }

  private mapSupportReviewRow(row: Record<string, unknown>) {
    const submitted = row.submitted_at ?? row.submittedAt;
    const agentRatingRaw = row.agent_rating ?? row.agentRating;
    const solvedRaw = row.problem_solved ?? row.problemSolved;
    const reviewAgentId = row.review_agent_id ?? row.reviewAgentId;
    const reviewAgentName = row.review_agent_name ?? row.reviewAgentName;
    const agentId = row.agent_id ?? row.agentId;
    return {
      ticket_id: String(row.ticket_id ?? row.ticketId ?? ''),
      ticket_number: String(row.ticket_number ?? row.ticketNumber ?? ''),
      status: String(row.status ?? ''),
      customer_name: (row.customer_name ?? row.customerName ?? null) as
        | string
        | null,
      rating: Number(row.rating ?? 0),
      agent_rating:
        agentRatingRaw == null || agentRatingRaw === ''
          ? null
          : Number(agentRatingRaw),
      problem_solved:
        solvedRaw == null || solvedRaw === '' ? null : Boolean(solvedRaw),
      comment: (row.comment as string | null | undefined) ?? null,
      submitted_at:
        submitted instanceof Date
          ? submitted.toISOString()
          : String(submitted ?? ''),
      review_agent_id:
        reviewAgentId == null || reviewAgentId === ''
          ? null
          : String(reviewAgentId),
      review_agent_name:
        reviewAgentName == null || reviewAgentName === ''
          ? null
          : String(reviewAgentName),
      agent_id: agentId == null || agentId === '' ? null : String(agentId),
    };
  }

  async getCsatForUser(userId: string, ticketId: string) {
    const ticket = await this.ticketRepo.findOne({
      where: { id: ticketId, requester_user_id: userId },
    });
    if (!ticket) throw new NotFoundException('Ticket not found');
    const row = await this.csatRepo.findOne({ where: { ticket_id: ticketId } });
    const alreadyReviewed = Boolean(row);
    return {
      submitted: alreadyReviewed,
      alreadyReviewed,
      canReview: ticket.status === 'CLOSED' && !alreadyReviewed,
      ticketStatus: ticket.status,
      agent: await this.reviewAgentPayload(
        ticket.review_agent_id,
        ticket.review_agent_name,
      ),
      csat: row ? this.mapCsatRow(row) : null,
    };
  }

  async submitCsatForUser(
    userId: string,
    ticketId: string,
    input: {
      rating: number;
      comment?: string;
      agentRating?: number;
      problemSolved: boolean;
    },
  ) {
    if (typeof input.problemSolved !== 'boolean') {
      throw new BadRequestException('problemSolved is required');
    }
    const rating = parseCsatRating(input.rating, 'Rating');
    const comment = input.comment?.trim() || null;
    if (comment && comment.length > 2000) {
      throw new BadRequestException('Comment too long');
    }

    const ticket = await this.ticketRepo.findOne({
      where: { id: ticketId, requester_user_id: userId },
    });
    if (!ticket) throw new NotFoundException('Ticket not found');
    if (ticket.status !== 'CLOSED') {
      throw new ConflictException('Ticket is not closed');
    }

    const snapshotAgentId = ticket.review_agent_id;
    let agentRating: number | null = null;
    if (snapshotAgentId) {
      agentRating = parseCsatRating(input.agentRating, 'Agent rating');
    } else if (input.agentRating !== undefined && input.agentRating !== null) {
      throw new BadRequestException(
        'Agent rating is not available for this ticket',
      );
    }

    const existing = await this.csatRepo.findOne({
      where: { ticket_id: ticketId },
    });
    if (existing) {
      throw new ConflictException('CSAT already submitted for this ticket');
    }

    try {
      const saved = await this.csatRepo.save(
        this.csatRepo.create({
          ticket_id: ticketId,
          rating,
          comment,
          agent_id: snapshotAgentId,
          agent_rating: agentRating,
          problem_solved: input.problemSolved,
        }),
      );
      await this.ops.safeEvaluate(async () => {
        await this.ops.evaluateCsatForAdmin(snapshotAgentId);
        await this.ops.upsertFollowUpRequired({
          ticketId,
          problemSolved: input.problemSolved,
          overallRating: rating,
          agentRating,
        });
        await this.quality.evaluateAfterCsat(snapshotAgentId, ticket.category);
      });
      return {
        submitted: true as const,
        alreadyReviewed: true as const,
        canReview: false as const,
        ticketStatus: ticket.status,
        agent: await this.reviewAgentPayload(
          snapshotAgentId,
          ticket.review_agent_name,
        ),
        csat: this.mapCsatRow(saved),
      };
    } catch (err) {
      if (isUniqueViolation(err)) {
        throw new ConflictException('CSAT already submitted for this ticket');
      }
      throw err;
    }
  }

  async getInvestigationConversation(
    reportId: string,
    kind: (typeof TRUST_REPORT_KINDS)[number],
    limit = 50,
    beforeSequence?: number,
  ) {
    const canonical =
      kind === 'conversation_reported'
        ? await this.reportRepo.findOne({ where: { id: reportId } })
        : await this.safetyRepo.findOne({ where: { id: reportId } });
    if (!canonical) throw new NotFoundException('Report not found');

    const conv = await this.convRepo.findOne({
      where: { id: canonical.conversation_id },
    });
    if (!conv || conv.type === 'SUPPORT') {
      throw new NotFoundException('Report not found');
    }

    const take = Math.min(Math.max(limit, 1), 50);
    const qb = this.messageRepo
      .createQueryBuilder('m')
      .where('m.conversation_id = :id', { id: conv.id })
      .andWhere("m.type != 'SYSTEM_INTERNAL'")
      .andWhere('m.deleted_at IS NULL')
      .orderBy('m.conversation_sequence', 'DESC')
      .take(take + 1);
    if (beforeSequence != null) {
      qb.andWhere('m.conversation_sequence < :seq', { seq: beforeSequence });
    }
    const rows = await qb.getMany();
    const hasMore = rows.length > take;
    const page = (hasMore ? rows.slice(0, take) : rows).reverse();
    const messageIds = page.map((m) => m.id);
    const attachmentRows = messageIds.length
      ? (
          await this.attachmentRepo.find({
            where: { message_id: In(messageIds) },
          })
        ).filter((a): a is typeof a & { message_id: string } => !!a.message_id)
      : [];
    const byMessage = new Map<string, typeof attachmentRows>();
    for (const att of attachmentRows) {
      const list = byMessage.get(att.message_id) ?? [];
      list.push(att);
      byMessage.set(att.message_id, list);
    }
    const evidence = attachmentRows.length
      ? await this.buildEvidence(attachmentRows.map((a) => a.id))
      : [];
    const evidenceById = new Map(evidence.map((e) => [e.id, e]));

    return {
      conversation: {
        id: conv.id,
        booking_id: conv.booking_id,
        listing_id: conv.listing_id,
        type: conv.type,
      },
      items: page.map((m) => {
        let senderRole: 'GUEST' | 'HOST' | 'UNKNOWN' = 'UNKNOWN';
        if (m.sender_id && m.sender_id === conv.guest_user_id)
          senderRole = 'GUEST';
        else if (m.sender_id && m.sender_id === conv.host_user_id) {
          senderRole = 'HOST';
        }
        const atts = byMessage.get(m.id) ?? [];
        return {
          id: m.id,
          sender_id: m.sender_id,
          sender_role: senderRole,
          type: m.type,
          body: m.body ?? '',
          conversation_sequence: Number(m.conversation_sequence),
          created_at: (m.sent_at ?? m.created_at).toISOString(),
          attachments: atts.map((a) => evidenceById.get(a.id)).filter(Boolean),
        };
      }),
      next_cursor: hasMore
        ? {
            before_sequence: Number(page[0]?.conversation_sequence),
          }
        : null,
      has_more: hasMore,
    };
  }

