  /**
   * Support ops analytics for tickets created in [from, to).
   * SLA thresholds come from SUPPORT_SLA (not hardcoded SQL intervals).
   */
  async getAnalyticsForAdmin(query: { from?: string; to?: string } = {}) {
    const now = new Date();
    const defaultFrom = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
    const from = query.from ? new Date(query.from) : defaultFrom;
    const toExclusive = query.to
      ? new Date(query.to)
      : new Date(now.getTime() + 1);
    if (Number.isNaN(from.getTime()) || Number.isNaN(toExclusive.getTime())) {
      throw new BadRequestException('Invalid from/to date');
    }
    if (from >= toExclusive) {
      throw new BadRequestException('from must be before to');
    }
    const maxRangeMs = 90 * 24 * 60 * 60 * 1000;
    if (toExclusive.getTime() - from.getTime() > maxRangeMs) {
      throw new BadRequestException('Date range must be 90 days or less');
    }

    const frLow = SUPPORT_SLA.LOW.firstResponseHours;
    const frNormal = SUPPORT_SLA.NORMAL.firstResponseHours;
    const frHigh = SUPPORT_SLA.HIGH.firstResponseHours;
    const frUrgent = SUPPORT_SLA.URGENT.firstResponseHours;
    const resLow = SUPPORT_SLA.LOW.resolutionHours;
    const resNormal = SUPPORT_SLA.NORMAL.resolutionHours;
    const resHigh = SUPPORT_SLA.HIGH.resolutionHours;
    const resUrgent = SUPPORT_SLA.URGENT.resolutionHours;

    const frHoursExpr = `
      CASE t.priority
        WHEN 'LOW' THEN $3::int
        WHEN 'HIGH' THEN $5::int
        WHEN 'URGENT' THEN $6::int
        ELSE $4::int
      END
    `;
    const resHoursExpr = `
      CASE t.priority
        WHEN 'LOW' THEN $7::int
        WHEN 'HIGH' THEN $9::int
        WHEN 'URGENT' THEN $10::int
        ELSE $8::int
      END
    `;

    // Incomplete: elapsed/window < 0.8 ON_TRACK, < 1 AT_RISK, else BREACHED.
    // Complete: completed <= target ON_TRACK else BREACHED.
    const legStateSql = (completedCol: string, hoursExpr: string) => `
      CASE
        WHEN ${completedCol} IS NOT NULL THEN
          CASE
            WHEN ${completedCol} <= t.created_at + ((${hoursExpr}) * INTERVAL '1 hour')
              THEN 'ON_TRACK'
            ELSE 'BREACHED'
          END
        ELSE
          CASE
            WHEN EXTRACT(EPOCH FROM ($11::timestamptz - t.created_at))
              < 0.8 * (${hoursExpr}) * 3600 THEN 'ON_TRACK'
            WHEN EXTRACT(EPOCH FROM ($11::timestamptz - t.created_at))
              < (${hoursExpr}) * 3600 THEN 'AT_RISK'
            ELSE 'BREACHED'
          END
      END
    `;

    const params = [
      from.toISOString(),
      toExclusive.toISOString(),
      frLow,
      frNormal,
      frHigh,
      frUrgent,
      resLow,
      resNormal,
      resHigh,
      resUrgent,
      now.toISOString(),
    ];

    const [summary] = await this.dataSource.query(
      `
      SELECT
        COUNT(*)::int AS created,
        COUNT(*) FILTER (WHERE t.status IN ('OPEN','IN_PROGRESS','WAITING_FOR_CUSTOMER','WAITING_FOR_HOST','ESCALATED'))::int AS open,
        COUNT(*) FILTER (WHERE t.status = 'RESOLVED')::int AS resolved,
        COUNT(*) FILTER (WHERE t.status = 'CLOSED')::int AS closed,
        COUNT(*) FILTER (WHERE t.status = 'ESCALATED')::int AS escalated,
        COUNT(*) FILTER (WHERE t.assigned_admin_id IS NOT NULL)::int AS assigned,
        COUNT(*) FILTER (WHERE t.assigned_admin_id IS NULL)::int AS unassigned,
        AVG(EXTRACT(EPOCH FROM (t.first_admin_response_at - t.created_at)))
          FILTER (WHERE t.first_admin_response_at IS NOT NULL) AS avg_first_response_seconds,
        PERCENTILE_CONT(0.5) WITHIN GROUP (
          ORDER BY EXTRACT(EPOCH FROM (t.first_admin_response_at - t.created_at))
        ) FILTER (WHERE t.first_admin_response_at IS NOT NULL) AS median_first_response_seconds,
        AVG(EXTRACT(EPOCH FROM (t.resolved_at - t.created_at)))
          FILTER (WHERE t.resolved_at IS NOT NULL) AS avg_first_resolution_seconds,
        PERCENTILE_CONT(0.5) WITHIN GROUP (
          ORDER BY EXTRACT(EPOCH FROM (t.resolved_at - t.created_at))
        ) FILTER (WHERE t.resolved_at IS NOT NULL) AS median_first_resolution_seconds,
        AVG(EXTRACT(EPOCH FROM (t.closed_at - t.created_at)))
          FILTER (WHERE t.closed_at IS NOT NULL) AS avg_closure_seconds,
        PERCENTILE_CONT(0.5) WITHIN GROUP (
          ORDER BY EXTRACT(EPOCH FROM (t.closed_at - t.created_at))
        ) FILTER (WHERE t.closed_at IS NOT NULL) AS median_closure_seconds
      FROM stays_support_tickets t
      WHERE t.created_at >= $1::timestamptz
        AND t.created_at < $2::timestamptz
      `,
      params.slice(0, 2),
    );

    const slaRows = await this.dataSource.query(
      `
      SELECT
        ${legStateSql('t.first_admin_response_at', frHoursExpr)} AS fr_state,
        ${legStateSql('t.resolved_at', resHoursExpr)} AS res_state,
        COUNT(*)::int AS cnt
      FROM stays_support_tickets t
      WHERE t.created_at >= $1::timestamptz
        AND t.created_at < $2::timestamptz
      GROUP BY 1, 2
      `,
      params,
    );

    const emptyBuckets = () => ({ onTrack: 0, atRisk: 0, breached: 0 });
    const firstResponseSla = emptyBuckets();
    const firstResolutionSla = emptyBuckets();
    const bump = (
      bag: { onTrack: number; atRisk: number; breached: number },
      state: string,
      n: number,
    ) => {
      if (state === 'ON_TRACK') bag.onTrack += n;
      else if (state === 'AT_RISK') bag.atRisk += n;
      else bag.breached += n;
    };
    for (const row of slaRows as {
      fr_state: string;
      res_state: string;
      cnt: number;
    }[]) {
      bump(firstResponseSla, row.fr_state, Number(row.cnt));
      bump(firstResolutionSla, row.res_state, Number(row.cnt));
    }

    const [csat] = await this.dataSource.query(
      `
      SELECT
        COUNT(*)::int AS responses,
        AVG(c.rating)::float AS average_rating,
        COUNT(*) FILTER (WHERE ROUND(c.rating::numeric) = 1)::int AS r1,
        COUNT(*) FILTER (WHERE ROUND(c.rating::numeric) = 2)::int AS r2,
        COUNT(*) FILTER (WHERE ROUND(c.rating::numeric) = 3)::int AS r3,
        COUNT(*) FILTER (WHERE ROUND(c.rating::numeric) = 4)::int AS r4,
        COUNT(*) FILTER (WHERE ROUND(c.rating::numeric) = 5)::int AS r5
      FROM stays_support_ticket_csat c
      INNER JOIN stays_support_tickets t ON t.id = c.ticket_id
      WHERE t.created_at >= $1::timestamptz
        AND t.created_at < $2::timestamptz
      `,
      params.slice(0, 2),
    );

    const categories = await this.dataSource.query(
      `
      SELECT t.category AS category, COUNT(*)::int AS count
      FROM stays_support_tickets t
      WHERE t.created_at >= $1::timestamptz
        AND t.created_at < $2::timestamptz
      GROUP BY t.category
      ORDER BY count DESC, t.category ASC
      `,
      params.slice(0, 2),
    );

    const priorities = await this.dataSource.query(
      `
      SELECT t.priority AS priority, COUNT(*)::int AS count
      FROM stays_support_tickets t
      WHERE t.created_at >= $1::timestamptz
        AND t.created_at < $2::timestamptz
      GROUP BY t.priority
      ORDER BY count DESC, t.priority ASC
      `,
      params.slice(0, 2),
    );

    const statusDistribution = await this.dataSource.query(
      `
      SELECT t.status AS status, COUNT(*)::int AS count
      FROM stays_support_tickets t
      WHERE t.created_at >= $1::timestamptz
        AND t.created_at < $2::timestamptz
      GROUP BY t.status
      ORDER BY count DESC, t.status ASC
      `,
      params.slice(0, 2),
    );

    const volume = await this.dataSource.query(
      `
      SELECT
        d.day::text AS date,
        COALESCE(c.created, 0)::int AS created,
        COALESCE(x.closed, 0)::int AS closed
      FROM generate_series(
        ($1::timestamptz AT TIME ZONE 'UTC')::date,
        (($2::timestamptz - INTERVAL '1 millisecond') AT TIME ZONE 'UTC')::date,
        INTERVAL '1 day'
      ) AS d(day)
      LEFT JOIN (
        SELECT (t.created_at AT TIME ZONE 'UTC')::date AS day, COUNT(*)::int AS created
        FROM stays_support_tickets t
        WHERE t.created_at >= $1::timestamptz
          AND t.created_at < $2::timestamptz
        GROUP BY 1
      ) c ON c.day = d.day
      LEFT JOIN (
        SELECT (t.closed_at AT TIME ZONE 'UTC')::date AS day, COUNT(*)::int AS closed
        FROM stays_support_tickets t
        WHERE t.closed_at >= $1::timestamptz
          AND t.closed_at < $2::timestamptz
        GROUP BY 1
      ) x ON x.day = d.day
      ORDER BY d.day ASC
      `,
      params.slice(0, 2),
    );

    const num = (v: unknown) => (v == null || v === '' ? null : Number(v));

    return {
      from: from.toISOString(),
      to: toExclusive.toISOString(),
      tickets: {
        created: Number(summary?.created ?? 0),
        open: Number(summary?.open ?? 0),
        resolved: Number(summary?.resolved ?? 0),
        closed: Number(summary?.closed ?? 0),
        escalated: Number(summary?.escalated ?? 0),
      },
      response: {
        averageFirstResponseSeconds: num(summary?.avg_first_response_seconds),
        medianFirstResponseSeconds: num(summary?.median_first_response_seconds),
      },
      firstResolution: {
        averageSeconds: num(summary?.avg_first_resolution_seconds),
        medianSeconds: num(summary?.median_first_resolution_seconds),
      },
      closure: {
        averageSeconds: num(summary?.avg_closure_seconds),
        medianSeconds: num(summary?.median_closure_seconds),
      },
      sla: {
        firstResponse: firstResponseSla,
        firstResolution: firstResolutionSla,
      },
      csat: {
        responses: Number(csat?.responses ?? 0),
        averageRating: num(csat?.average_rating),
        ratingDistribution: {
          '1': Number(csat?.r1 ?? 0),
          '2': Number(csat?.r2 ?? 0),
          '3': Number(csat?.r3 ?? 0),
          '4': Number(csat?.r4 ?? 0),
          '5': Number(csat?.r5 ?? 0),
        },
      },
      categories: (categories as { category: string; count: number }[]).map(
        (r) => ({ category: r.category, count: Number(r.count) }),
      ),
      priorities: (priorities as { priority: string; count: number }[]).map(
        (r) => ({ priority: r.priority, count: Number(r.count) }),
      ),
      statusDistribution: (
        statusDistribution as { status: string; count: number }[]
      ).map((r) => ({ status: r.status, count: Number(r.count) })),
      assignment: {
        assigned: Number(summary?.assigned ?? 0),
        unassigned: Number(summary?.unassigned ?? 0),
      },
      volume: (
        volume as { date: string; created: number; closed: number }[]
      ).map((r) => ({
        date: String(r.date),
        created: Number(r.created),
        closed: Number(r.closed),
      })),
    };
  }

  async listReportActivity(
    reportId: string,
    kind: (typeof TRUST_REPORT_KINDS)[number],
    limit = 50,
    offset = 0,
  ) {
    if (kind === 'conversation_reported') {
      const row = await this.reportRepo.findOne({ where: { id: reportId } });
      if (!row) throw new NotFoundException('Report not found');
      return this.listActivityForEntity(
        'conversation_report',
        reportId,
        limit,
        offset,
      );
    }
    const row = await this.safetyRepo.findOne({ where: { id: reportId } });
    if (!row) throw new NotFoundException('Report not found');
    return this.listActivityForEntity('safety_issue', reportId, limit, offset);
  }

  private async listActivityForEntity(
    entityType: string,
    entityId: string,
    limit: number,
    offset: number,
  ) {
    const take = Math.min(Math.max(limit, 1), 100);
    const skip = Math.max(offset, 0);
    const qb = this.auditLogRepo
      .createQueryBuilder('a')
      .where('a.entity_type = :entityType', { entityType })
      .andWhere('a.entity_id = :entityId', { entityId });
    const total = await qb.clone().getCount();
    const rows = await qb
      .orderBy('a.created_at', 'DESC')
      .addOrderBy('a.id', 'DESC')
      .skip(skip)
      .take(take)
      .getMany();
    return {
      items: rows.map((row) => ({
        id: row.id,
        action: row.action,
        actor_id: row.actor_user_id,
        metadata: row.metadata ?? {},
        created_at: row.created_at.toISOString(),
      })),
      total,
      limit: take,
      offset: skip,
      hasMore: skip + rows.length < total,
    };
  }

  async resolveEvidenceForCanonical(
    attachmentIds: string[],
    allowedIds: string[],
  ) {
    const allowed = new Set(allowedIds.filter(Boolean));
    for (const id of attachmentIds) {
      if (!allowed.has(id)) {
        throw new BadRequestException('Invalid attachment references');
      }
    }
    return this.buildEvidence(attachmentIds.filter((id) => allowed.has(id)));
  }

  private async composeTrustRecords(
    reports: StaysConversationReport[],
    safety: StaysSafetyIssue[],
    includeEvidence: boolean,
  ) {
    const reportTickets = reports.length
      ? await this.ticketRepo.find({
          where: { report_id: In(reports.map((r) => r.id)) },
        })
      : [];
    const safetyTickets = safety.length
      ? await this.ticketRepo.find({
          where: { safety_issue_id: In(safety.map((s) => s.id)) },
        })
      : [];
    const ticketByReport = new Map(
      reportTickets.filter((t) => t.report_id).map((t) => [t.report_id!, t]),
    );
    const ticketBySafety = new Map(
      safetyTickets
        .filter((t) => t.safety_issue_id)
        .map((t) => [t.safety_issue_id!, t]),
    );

    const bookingIds = [
      ...reports.map((r) => r.booking_id),
      ...safety.map((s) => s.booking_id),
    ].filter(Boolean) as string[];
    const listingIds = [
      ...reports.map((r) => r.listing_id),
      ...safety.map((s) => s.listing_id),
    ].filter(Boolean) as string[];
    const userIds = [
      ...reports.flatMap((r) => [r.reporter_user_id, r.reported_user_id]),
      ...safety.flatMap((s) => [s.reporter_user_id, s.reported_user_id]),
    ].filter(Boolean) as string[];

    const [bookings, listings, identities] = await Promise.all([
      bookingIds.length
        ? this.bookingRepo.find({
            where: { id: In(bookingIds) },
            select: ['id', 'booking_reference'],
          })
        : Promise.resolve([] as StaysBooking[]),
      listingIds.length
        ? this.listingRepo.find({
            where: { id: In(listingIds) },
            select: ['id', 'title'],
          })
        : Promise.resolve([] as StaysListing[]),
      this.loadIdentities(userIds),
    ]);
    const bookingMap = new Map(bookings.map((b) => [b.id, b]));
    const listingMap = new Map(listings.map((l) => [l.id, l]));

    const reportItems = await Promise.all(
      reports.map(async (row) => {
        const ticket = ticketByReport.get(row.id) ?? null;
        return {
          id: row.id,
          kind: 'conversation_reported' as const,
          reason: row.reason ?? undefined,
          category: undefined as string | undefined,
          status: row.status,
          created_at: row.created_at.toISOString(),
          conversation_id: row.conversation_id,
          booking_id: row.booking_id,
          listing_id: row.listing_id,
          actor_user_id: row.reporter_user_id,
          reporter: this.toPerson(row.reporter_user_id, identities, true),
          reported_user: row.reported_user_id
            ? this.toPerson(row.reported_user_id, identities, false)
            : null,
          booking: this.toBookingRef(row.booking_id, bookingMap),
          listing: this.toListingRef(row.listing_id, listingMap),
          ticket: ticket
            ? {
                id: ticket.id,
                ticket_number: ticket.ticket_number,
                status: ticket.status,
              }
            : null,
          support_ticket_id: ticket?.id,
          evidence_count: row.attachment_ids?.length ?? 0,
          ...(includeEvidence
            ? { evidence: await this.buildEvidence(row.attachment_ids ?? []) }
            : {}),
        };
      }),
    );
    const safetyItems = await Promise.all(
      safety.map(async (row) => {
        const ticket = ticketBySafety.get(row.id) ?? null;
        return {
          id: row.id,
          kind: 'safety_issue' as const,
          reason: undefined as string | undefined,
          category: row.category,
          status: row.status,
          created_at: row.created_at.toISOString(),
          conversation_id: row.conversation_id,
          booking_id: row.booking_id,
          listing_id: row.listing_id,
          actor_user_id: row.reporter_user_id,
          reporter: this.toPerson(row.reporter_user_id, identities, true),
          reported_user: row.reported_user_id
            ? this.toPerson(row.reported_user_id, identities, false)
            : null,
          booking: this.toBookingRef(row.booking_id, bookingMap),
          listing: this.toListingRef(row.listing_id, listingMap),
          ticket: ticket
            ? {
                id: ticket.id,
                ticket_number: ticket.ticket_number,
                status: ticket.status,
              }
            : null,
          support_ticket_id: ticket?.id,
          evidence_count: row.attachment_ids?.length ?? 0,
          ...(includeEvidence
            ? { evidence: await this.buildEvidence(row.attachment_ids ?? []) }
            : {}),
        };
      }),
    );

    return [...reportItems, ...safetyItems].sort((a, b) =>
      b.created_at.localeCompare(a.created_at),
    );
  }

  private async applyTrustStatus(input: {
    kind: (typeof TRUST_REPORT_KINDS)[number];
    row: StaysConversationReport | StaysSafetyIssue;
    next: (typeof TRUST_REPORT_STATUSES)[number];
    actorUserId: string;
  }) {
    const from = input.row.status;

    if (input.next !== 'ESCALATED') {
      input.row.status = input.next;
      input.row.updated_at = new Date();
      if (input.kind === 'conversation_reported') {
        await this.reportRepo.save(input.row as StaysConversationReport);
      } else {
        await this.safetyRepo.save(input.row as StaysSafetyIssue);
      }

      const ticket =
        input.kind === 'conversation_reported'
          ? await this.ticketRepo.findOne({
              where: { report_id: input.row.id },
            })
          : await this.ticketRepo.findOne({
              where: { safety_issue_id: input.row.id },
            });

      await this.staysAudit.log({
        actorUserId: input.actorUserId,
        actorRole: 'ADMIN',
        entityType:
          input.kind === 'conversation_reported'
            ? 'conversation_report'
            : 'safety_issue',
        entityId: input.row.id,
        action: 'status_changed',
        metadata: {
          from,
          to: input.next,
          ticketId: ticket?.id ?? null,
        },
      });

      return this.getReportForAdmin(input.row.id, input.kind);
    }

    // ESCALATED: ensure ticket before status change in one TX so failure
    // cannot leave the canonical row escalated without a ticket.
    const { ticketId, createdTicket } = await this.dataSource.transaction(
      async (manager) => {
        const ticketRepo = manager.getRepository(StaysSupportTicket);
        const convRepo = manager.getRepository(StaysConversation);
        const reportRepo = manager.getRepository(StaysConversationReport);
        const safetyRepo = manager.getRepository(StaysSafetyIssue);

        let createdTicket = false;
        let ticket: StaysSupportTicket | null =
          input.kind === 'conversation_reported'
            ? await ticketRepo.findOne({
                where: { report_id: input.row.id },
              })
            : await ticketRepo.findOne({
                where: { safety_issue_id: input.row.id },
              });

        if (!ticket) {
          const conv = await convRepo.findOne({
            where: { id: input.row.conversation_id },
          });
          if (!conv) {
            throw new InternalServerErrorException(ENSURE_TICKET_FAILED);
          }
          ticket =
            input.kind === 'conversation_reported'
              ? await this.ensureTicketForReport({
                  report: input.row as StaysConversationReport,
                  sourceConversation: conv,
                  manager,
                })
              : await this.ensureTicketForSafetyIssue({
                  safety: input.row as StaysSafetyIssue,
                  sourceConversation: conv,
                  manager,
                });
          createdTicket = true;
        }

        if (ticket.priority !== 'URGENT') {
          await ticketRepo.update(ticket.id, {
            priority: 'HIGH',
            updated_at: new Date(),
          });
          ticket.priority = 'HIGH';
        }

        input.row.status = 'ESCALATED';
        input.row.updated_at = new Date();
        if (input.kind === 'conversation_reported') {
          await reportRepo.save(input.row as StaysConversationReport);
        } else {
          await safetyRepo.save(input.row as StaysSafetyIssue);
        }

        return { ticketId: ticket.id, createdTicket };
      },
    );

    await this.staysAudit.log({
      actorUserId: input.actorUserId,
      actorRole: 'ADMIN',
      entityType:
        input.kind === 'conversation_reported'
          ? 'conversation_report'
          : 'safety_issue',
      entityId: input.row.id,
      action: 'status_changed',
      metadata: {
        from,
        to: 'ESCALATED',
        ticketId,
      },
    });

    if (createdTicket) {
      await this.scheduleAutoAssignment(ticketId);
    }

    return this.getReportForAdmin(input.row.id, input.kind);
  }

  /** Post-commit routing. Create/report/safety must still succeed if this fails. */
  private async scheduleAutoAssignment(ticketId: string) {
    try {
      await this.assignment.attemptAutoAssignment(ticketId);
    } catch {
      // Fail-soft: ticket stays unassigned and surfaces in Operations Attention.
    }
  }

  private async buildEvidence(attachmentIds: string[]) {
    if (!attachmentIds.length) return [];
    const allowed = new Set(attachmentIds);
    const rows = await this.attachmentRepo.find({
      where: { id: In(attachmentIds) },
    });
    return rows
      .filter((row) => allowed.has(row.id))
      .map((row) => {
        const signed = this.media.resolveAttachment(
          row.id,
          'full',
          row.media_version ?? 1,
        );
        return {
          id: row.id,
          url: signed.url,
          contentType: row.mime,
          filename: row.original_filename,
          createdAt: row.created_at.toISOString(),
        };
      });
  }

  private async resolveSupportContacts(
    userIds: Array<string | null | undefined>,
  ) {
    const unique = [...new Set(userIds.filter((id): id is string => !!id))];
    const contacts = new Map<
      string,
      {
        id: string;
        name: string | null;
        email: string | null;
        phone: string | null;
      }
    >();
    if (unique.length === 0) return contacts;

    const [identities, hostProfiles] = await Promise.all([
      this.loadIdentities(unique),
      this.hostProfileRepo.find({ where: { user_id: In(unique) } }),
    ]);
    const profiles = new Map(hostProfiles.map((row) => [row.user_id, row]));

    for (const id of unique) {
      const identity = identities.get(id);
      const profile = profiles.get(id);
      contacts.set(id, {
        id,
        name: identity?.fullName?.trim() || profile?.full_name?.trim() || null,
        email: identity?.email?.trim() || profile?.email?.trim() || null,
        phone: identity?.phone?.trim() || profile?.phone?.trim() || null,
      });
    }
    return contacts;
  }

  private async loadIdentities(userIds: string[]) {
    const unique = [...new Set(userIds)];
    const entries = await Promise.all(
      unique.map(
        async (id) =>
          [id, await this.identityUsers.getProfileSummary(id)] as const,
      ),
    );
    return new Map(entries);
  }

  private toPerson(
    userId: string,
    identities: Map<
      string,
      Awaited<ReturnType<IdentityUserClient['getProfileSummary']>>
    >,
    includeEmail: boolean,
  ) {
    const summary = identities.get(userId);
    return {
      id: userId,
      name: summary?.fullName ?? null,
      ...(includeEmail ? { email: summary?.email ?? null } : {}),
    };
  }

  private toBookingRef(
    bookingId: string | null,
    bookings: Map<string, StaysBooking>,
  ) {
    if (!bookingId) return null;
    const row = bookings.get(bookingId);
    return row
      ? { id: row.id, reference: row.booking_reference }
      : { id: bookingId, reference: null };
  }

  private toListingRef(
    listingId: string | null,
    listings: Map<string, StaysListing>,
  ) {
    if (!listingId) return null;
    const row = listings.get(listingId);
    return row
      ? { id: row.id, title: row.title }
      : { id: listingId, title: null };
  }

  private async hydrateTicketIdentities(rows: StaysSupportTicket[]) {
    const missing = rows.filter(
      (row) => !row.customer_name || !row.requester_email,
    );
    if (!missing.length) return;
    await Promise.all(
      missing.map(async (row) => {
        const summary = await this.identityUsers.getProfileSummary(
          row.requester_user_id,
        );
        const name = summary?.fullName ?? null;
        const email = summary?.email ?? null;
        const patch: Partial<StaysSupportTicket> = {};
        if (!row.customer_name && name) {
          row.customer_name = name;
          patch.customer_name = name;
        }
        if (!row.requester_email && email) {
          row.requester_email = email;
          patch.requester_email = email;
        }
        if (Object.keys(patch).length) {
          await this.ticketRepo.update(row.id, patch);
        }
      }),
    );
  }

  private async resolveParty(userId: string): Promise<SupportTicketParty> {
    const host = await this.hostProfileRepo.findOne({
      where: { user_id: userId },
    });
    return host ? 'HOST' : 'GUEST';
  }

  private async resolveOwnedLinks(
    userId: string,
    party: SupportTicketParty,
    dto: CreateSupportTicketDto,
    manager?: EntityManager,
  ): Promise<{
    bookingId: string | null;
    listingId: string | null;
    reportId: string | null;
    safetyIssueId: string | null;
  }> {
    const bookingRepo = manager
      ? manager.getRepository(StaysBooking)
      : this.bookingRepo;
    const listingRepo = manager
      ? manager.getRepository(StaysListing)
      : this.listingRepo;
    const reportRepo = manager
      ? manager.getRepository(StaysConversationReport)
      : this.reportRepo;
    const safetyRepo = manager
      ? manager.getRepository(StaysSafetyIssue)
      : this.safetyRepo;

    let bookingId: string | null = null;
    let listingId: string | null = null;

    if (dto.bookingId) {
      const booking = await bookingRepo.findOne({
        where: { id: dto.bookingId },
        relations: ['listing'],
      });
      if (!booking) throw new NotFoundException('Ticket not found');
      const ownsAsGuest = booking.guest_user_id === userId;
      const ownsAsHost = booking.listing?.host_user_id === userId;
      if (!ownsAsGuest && !ownsAsHost) {
        throw new NotFoundException('Ticket not found');
      }
      bookingId = booking.id;
      listingId = booking.listing_id;
    }

    if (dto.listingId) {
      const listing = await listingRepo.findOne({
        where: { id: dto.listingId },
      });
      if (!listing) throw new NotFoundException('Ticket not found');
      if (party === 'HOST' && listing.host_user_id !== userId) {
        throw new NotFoundException('Ticket not found');
      }
      if (party === 'GUEST' && !bookingId) {
        // Guests may link a listing only via an owned booking path; bare listing requires ownership as host.
        if (listing.host_user_id !== userId) {
          throw new NotFoundException('Ticket not found');
        }
      }
      listingId = listing.id;
    }

    let reportId: string | null = null;
    if (dto.reportId) {
      const report = await reportRepo.findOne({ where: { id: dto.reportId } });
      if (!report || report.reporter_user_id !== userId) {
        throw new NotFoundException('Ticket not found');
      }
      reportId = report.id;
    }

    let safetyIssueId: string | null = null;
    if (dto.safetyIssueId) {
      const safety = await safetyRepo.findOne({
        where: { id: dto.safetyIssueId },
      });
      if (!safety || safety.reporter_user_id !== userId) {
        throw new NotFoundException('Ticket not found');
      }
      safetyIssueId = safety.id;
    }

    return { bookingId, listingId, reportId, safetyIssueId };
  }

  private async allocateTicketNumber(manager: EntityManager): Promise<string> {
    const year = new Date().getUTCFullYear();
    await manager.query(
      `INSERT INTO stays_support_ticket_ref_counters (year, counter)
       VALUES ($1, 1)
       ON CONFLICT (year) DO UPDATE
       SET counter = stays_support_ticket_ref_counters.counter + 1`,
      [year],
    );
    const rows = await manager.query(
      `SELECT counter FROM stays_support_ticket_ref_counters WHERE year = $1`,
      [year],
    );
    const counter = Number(rows?.[0]?.counter ?? 1);
    return `SUP-${year}-${String(counter).padStart(6, '0')}`;
  }

  private async createSupportConversation(
    manager: EntityManager,
    userId: string,
    party: SupportTicketParty,
    listingId: string | null,
    meta: { subject: string; ticketNumber: string },
  ): Promise<StaysConversation> {
    const convRepo = manager.getRepository(StaysConversation);
    const conv = convRepo.create({
      booking_id: null,
      type: 'SUPPORT',
      messaging_state: 'ACTIVE',
      guest_visibility: 'ACTIVE',
      host_visibility: 'ACTIVE',
      reservation_snapshot: {
        listingTitle: meta.subject,
        listingId,
        bookingReference: meta.ticketNumber,
        hostDisplayName: 'Nexa Support',
        checkinDate: '',
        checkoutDate: '',
        guestCount: 0,
      },
      listing_id: listingId,
      guest_user_id: party === 'GUEST' ? userId : null,
      host_user_id: party === 'HOST' ? userId : null,
      last_message_sequence: '0',
      unread_guest: 0,
      unread_host: 0,
    });
    return convRepo.save(conv);
  }

  private async loadBookingRefs(ids: string[]): Promise<Map<string, string>> {
    if (!ids.length) return new Map();
    const rows = await this.bookingRepo
      .createQueryBuilder('b')
      .select(['b.id', 'b.booking_reference'])
      .where('b.id IN (:...ids)', { ids })
      .getMany();
    return new Map(rows.map((r) => [r.id, r.booking_reference]));
  }

  private toListRow(
    ticket: StaysSupportTicket,
    bookingRef: string | null = null,
  ) {
    const sla = computeSupportSla({
      createdAt: ticket.created_at,
      priority: ticket.priority,
      firstAdminResponseAt: ticket.first_admin_response_at,
      resolvedAt: ticket.resolved_at,
    });
    const routingSuggestion = suggestRouting({
      category: ticket.category,
      currentPriority: ticket.priority,
      hasReportId: !!ticket.report_id,
      hasSafetyIssueId: !!ticket.safety_issue_id,
    });
    return {
      id: ticket.id,
      ticket_number: ticket.ticket_number,
      subject: ticket.subject,
      category: ticket.category,
      customer_name: ticket.customer_name,
      party: ticket.party,
      party_type: ticket.party,
      assigned_admin_id: ticket.assigned_admin_id,
      review_agent_id: ticket.review_agent_id,
      review_agent_name: ticket.review_agent_name,
      status: ticket.status,
      priority: ticket.priority,
      resolution_type: ticket.resolution_type ?? null,
      created_at: ticket.created_at.toISOString(),
      updated_at: ticket.updated_at.toISOString(),
      resolved_at: ticket.resolved_at?.toISOString() ?? null,
      closed_at: ticket.closed_at?.toISOString() ?? null,
      first_admin_response_at:
        ticket.first_admin_response_at?.toISOString() ?? null,
      requester_user_id: ticket.requester_user_id,
      requester_language: ticket.requester_language ?? null,
      booking_id: ticket.booking_id,
      booking_reference: bookingRef,
      listing_id: ticket.listing_id,
      report_id: ticket.report_id,
      safety_issue_id: ticket.safety_issue_id,
      unread_for_support: ticket.unread_for_support,
      last_message_preview: ticket.last_message_preview,
      requester_email: ticket.requester_email,
      conversation_id: ticket.conversation_id,
      sla,
      routing_suggestion: routingSuggestion,
    };
  }

  private resolveSenderType(
    ticket: StaysSupportTicket,
    senderId: string | null,
    isSystem: boolean,
  ): 'SUPPORT_AGENT' | 'SYSTEM' | 'CUSTOMER' {
    if (isSystem || !senderId) return 'SYSTEM';
    if (senderId === ticket.requester_user_id) return 'CUSTOMER';
    return 'SUPPORT_AGENT';
  }
}
